    [RowVersion] ROWVERSION NOT NULL,
    CONSTRAINT [PK_CollateralTypeAttribute] PRIMARY KEY CLUSTERED ([CollateralTypeAttributeId]),
    CONSTRAINT [UQ_CollateralTypeAttribute_Tenant] UNIQUE ([TenantId], [CollateralTypeAttributeId]),
    CONSTRAINT [UQ_CollateralTypeAttribute_CollateralTypeId_AttrKey] UNIQUE ([TenantId], [CollateralTypeId], [AttrKey]),
    CONSTRAINT [CK_CollateralTypeAttribute_1] CHECK (DataType <> 'LIST' OR ListOptions IS NOT NULL),
    CONSTRAINT [CK_CollateralTypeAttribute_DataType] CHECK ([DataType] IS NULL OR [DataType] IN ('TEXT', 'NUMBER', 'DATE', 'AMOUNT', 'BOOLEAN', 'LIST', 'REFERENCE')),
    CONSTRAINT [CK_CollateralTypeAttribute_ListOptions_json] CHECK ([ListOptions] IS NULL OR ISJSON([ListOptions]) = 1)
);
GO
-- نوع الالتزام بأربع عائلات (FR-CAT-014، BR-CAT-010)
CREATE TABLE [cat].[ObligationType] (
    [TenantId] INT NOT NULL,
    [ObligationTypeId] INT IDENTITY(1,1) NOT NULL,
    [Code] VARCHAR(80) NOT NULL,
    [NameAr] NVARCHAR(200) NOT NULL,
    [NameEn] NVARCHAR(200) NULL,
    [Description] NVARCHAR(500) NULL,
    [IsActive] BIT NOT NULL CONSTRAINT [DF_ObligationType_IsActive] DEFAULT 1,
    [IsSystem] BIT NOT NULL CONSTRAINT [DF_ObligationType_IsSystem] DEFAULT 0,
    [IsLocked] BIT NOT NULL CONSTRAINT [DF_ObligationType_IsLocked] DEFAULT 0,
    [SortOrder] INT NOT NULL CONSTRAINT [DF_ObligationType_SortOrder] DEFAULT 0,
    [SeedKey] VARCHAR(80) NULL,
    [ExternalCode] VARCHAR(80) NULL,
    [Family] VARCHAR(23) NOT NULL,
    [MeasureKind] VARCHAR(18) NULL,
    [IsQualitative] BIT NOT NULL CONSTRAINT [DF_ObligationType_IsQualitative] DEFAULT 0,
    [DefaultDeadlineBasis] VARCHAR(21) NULL,
    [DefaultUnit] NVARCHAR(30) NULL,
    [CreatedAt] DATETIME2(3) NOT NULL CONSTRAINT [DF_ObligationType_CreatedAt] DEFAULT SYSUTCDATETIME(),
    [CreatedBy] BIGINT NULL,
    [UpdatedAt] DATETIME2(3) NULL,
    [UpdatedBy] BIGINT NULL,
    [RowVersion] ROWVERSION NOT NULL,
    CONSTRAINT [PK_ObligationType] PRIMARY KEY CLUSTERED ([ObligationTypeId]),
    CONSTRAINT [UQ_ObligationType_Tenant] UNIQUE ([TenantId], [ObligationTypeId]),
    CONSTRAINT [UQ_ObligationType_Code] UNIQUE ([TenantId], [Code]),
    CONSTRAINT [CK_ObligationType_1] CHECK (Family <> 'COVENANT' OR MeasureKind IS NOT NULL),
    CONSTRAINT [CK_ObligationType_2] CHECK (MeasureKind IS NULL OR MeasureKind <> 'NONE' OR IsQualitative = 1),
    CONSTRAINT [CK_ObligationType_3] CHECK (Code NOT LIKE '%[^A-Z0-9_]%' AND Code NOT LIKE '[0-9_]%'),
    CONSTRAINT [CK_ObligationType_4] CHECK ((IsLocked = 0 OR (IsSystem = 1 AND IsActive = 1)) AND (IsSystem = 0 OR NameEn IS NOT NULL)),
    CONSTRAINT [CK_ObligationType_Family] CHECK ([Family] IS NULL OR [Family] IN ('REPORTING', 'COVENANT', 'TRANSACTION_RESTRICTION', 'STATIC_CLAUSE')),
    CONSTRAINT [CK_ObligationType_MeasureKind] CHECK ([MeasureKind] IS NULL OR [MeasureKind] IN ('RATIO', 'AMOUNT', 'PERCENT_OF_REVENUE', 'AVERAGE_BALANCE', 'FLOW_VOLUME', 'NONE')),
    CONSTRAINT [CK_ObligationType_DefaultDeadlineBasis] CHECK ([DefaultDeadlineBasis] IS NULL OR [DefaultDeadlineBasis] IN ('AFTER_PERIOD_END', 'AFTER_FISCAL_YEAR_END', 'BEFORE_EVENT', 'AFTER_EVENT', 'ON_DEMAND_REQUEST', 'FIXED_DATE'))
);
GO
-- سعر الأساس: سوق (InstitutionId فارغ) أو داخلي لبنك (FR-CAT-015، BR-CAT-011)؛ الأسماء البديلة في BaseRateAlias
CREATE TABLE [cat].[BaseRate] (
    [TenantId] INT NOT NULL,
    [BaseRateId] INT IDENTITY(1,1) NOT NULL,
    [Code] VARCHAR(80) NOT NULL,
    [NameAr] NVARCHAR(200) NOT NULL,
    [NameEn] NVARCHAR(200) NULL,
    [Description] NVARCHAR(500) NULL,
    [IsActive] BIT NOT NULL CONSTRAINT [DF_BaseRate_IsActive] DEFAULT 1,
    [IsSystem] BIT NOT NULL CONSTRAINT [DF_BaseRate_IsSystem] DEFAULT 0,
    [IsLocked] BIT NOT NULL CONSTRAINT [DF_BaseRate_IsLocked] DEFAULT 0,
    [SortOrder] INT NOT NULL CONSTRAINT [DF_BaseRate_SortOrder] DEFAULT 0,
    [SeedKey] VARCHAR(80) NULL,
    [ExternalCode] VARCHAR(80) NULL,
    [Kind] VARCHAR(13) NOT NULL,
    [InstitutionId] BIGINT NULL,
    [FamilyCode] VARCHAR(40) NOT NULL,
    [Tenor] VARCHAR(10) NOT NULL,
    [CurrencyId] INT NULL,
    [StaleAfterDays] INT NULL,
    [CreatedAt] DATETIME2(3) NOT NULL CONSTRAINT [DF_BaseRate_CreatedAt] DEFAULT SYSUTCDATETIME(),
    [CreatedBy] BIGINT NULL,
    [UpdatedAt] DATETIME2(3) NULL,
    [UpdatedBy] BIGINT NULL,
    [RowVersion] ROWVERSION NOT NULL,
    CONSTRAINT [PK_BaseRate] PRIMARY KEY CLUSTERED ([BaseRateId]),
    CONSTRAINT [UQ_BaseRate_Tenant] UNIQUE ([TenantId], [BaseRateId]),
    CONSTRAINT [UQ_BaseRate_Scope_Tenor] UNIQUE ([TenantId], [Tenor], [BaseRateId]),
    CONSTRAINT [UQ_BaseRate_FamilyCode_Tenor_InstitutionId] UNIQUE ([TenantId], [FamilyCode], [Tenor], [InstitutionId]),
    CONSTRAINT [UQ_BaseRate_Code] UNIQUE ([TenantId], [Code]),
    CONSTRAINT [CK_BaseRate_1] CHECK ((Kind = 'MARKET' AND InstitutionId IS NULL) OR (Kind = 'BANK_INTERNAL' AND InstitutionId IS NOT NULL)),
    CONSTRAINT [CK_BaseRate_2] CHECK (StaleAfterDays IS NULL OR StaleAfterDays > 0),
    CONSTRAINT [CK_BaseRate_3] CHECK (Code NOT LIKE '%[^A-Z0-9_]%' AND Code NOT LIKE '[0-9_]%'),
    CONSTRAINT [CK_BaseRate_4] CHECK ((IsLocked = 0 OR (IsSystem = 1 AND IsActive = 1)) AND (IsSystem = 0 OR NameEn IS NOT NULL)),
    CONSTRAINT [CK_BaseRate_Kind] CHECK ([Kind] IS NULL OR [Kind] IN ('MARKET', 'BANK_INTERNAL')),
    CONSTRAINT [CK_BaseRate_Tenor] CHECK ([Tenor] IS NULL OR [Tenor] IN ('ON', '1M', '3M', '6M', '12M'))
);
GO
-- اسم بديل لسعر أساس (SIBOR ≡ SAIBOR) بحث بلا حساسية حالة وفريد ضمن النطاق (BR-CAT-011، FR-CAT-015) -- جدول وسيط جديد يحل «Aliases set»
CREATE TABLE [cat].[BaseRateAlias] (
    [TenantId] INT NOT NULL,
    [BaseRateAliasId] INT IDENTITY(1,1) NOT NULL,
    [BaseRateId] INT NOT NULL,
    [Tenor] VARCHAR(10) NOT NULL,
    [InstitutionId] BIGINT NULL,
    [Alias] NVARCHAR(60) NOT NULL,
    [AliasKey] AS (UPPER(Alias)) PERSISTED,
    [CreatedAt] DATETIME2(3) NOT NULL CONSTRAINT [DF_BaseRateAlias_CreatedAt] DEFAULT SYSUTCDATETIME(),
    [CreatedBy] BIGINT NULL,
    [UpdatedAt] DATETIME2(3) NULL,
    [UpdatedBy] BIGINT NULL,
    [RowVersion] ROWVERSION NOT NULL,
    CONSTRAINT [PK_BaseRateAlias] PRIMARY KEY CLUSTERED ([BaseRateAliasId]),
    CONSTRAINT [UQ_BaseRateAlias_Tenant] UNIQUE ([TenantId], [BaseRateAliasId]),
    CONSTRAINT [UQ_BaseRateAlias_InstitutionId_Tenor_AliasKey] UNIQUE ([TenantId], [InstitutionId], [Tenor], [AliasKey]),
    CONSTRAINT [CK_BaseRateAlias_Tenor] CHECK ([Tenor] IS NULL OR [Tenor] IN ('ON', '1M', '3M', '6M', '12M'))
);
GO
-- قيمة سعر الأساس بتاريخ سريان؛ لا حذف: التصحيح صف جديد والقديم SUPERSEDED (FR-CAT-016، BR-CAT-012/013)
CREATE TABLE [cat].[BaseRateValue] (
    [TenantId] INT NOT NULL,
    [BaseRateValueId] BIGINT IDENTITY(1,1) NOT NULL,
    [BaseRateId] INT NOT NULL,
    [EffectiveDate] DATE NOT NULL,
    [ValuePct] DECIMAL(9,6) NOT NULL,
    [Source] VARCHAR(10) NOT NULL CONSTRAINT [DF_BaseRateValue_Source] DEFAULT 'MANUAL',
    [SourceNote] NVARCHAR(300) NULL,
    [Status] VARCHAR(10) NOT NULL CONSTRAINT [DF_BaseRateValue_Status] DEFAULT 'VALID',
    [SupersedesId] BIGINT NULL,
    [EnteredBy] BIGINT NOT NULL,
    [EnteredOn] DATETIME2(3) NOT NULL,
    [CreatedAt] DATETIME2(3) NOT NULL CONSTRAINT [DF_BaseRateValue_CreatedAt] DEFAULT SYSUTCDATETIME(),
    [CreatedBy] BIGINT NULL,
    [UpdatedAt] DATETIME2(3) NULL,
    [UpdatedBy] BIGINT NULL,
    [RowVersion] ROWVERSION NOT NULL,
    CONSTRAINT [PK_BaseRateValue] PRIMARY KEY CLUSTERED ([BaseRateValueId]),
    CONSTRAINT [UQ_BaseRateValue_Tenant] UNIQUE ([TenantId], [BaseRateValueId]),
    CONSTRAINT [UQ_BaseRateValue_Scope_BaseRateId] UNIQUE ([TenantId], [BaseRateId], [BaseRateValueId]),
    CONSTRAINT [CK_BaseRateValue_1] CHECK (SupersedesId IS NULL OR SupersedesId <> BaseRateValueId),
    CONSTRAINT [CK_BaseRateValue_Source] CHECK ([Source] IS NULL OR [Source] IN ('MANUAL', 'FEED')),
    CONSTRAINT [CK_BaseRateValue_Status] CHECK ([Status] IS NULL OR [Status] IN ('VALID', 'SUPERSEDED'))
);
GO
-- DR-03: مملوك للمشترك؛ نسخة النظام تُهيَّأ لكل مشترك من قالب المنصة  # قائمة قيم؛ TenantId فارغ = قائمة عالمية يملكها المشغّل للقراءة (FR-CAT-020، BR-CAT-015)
CREATE TABLE [cat].[LookupList] (
    [TenantId] INT NOT NULL,
    [LookupListId] INT IDENTITY(1,1) NOT NULL,
    [Code] VARCHAR(80) NOT NULL,
    [NameAr] NVARCHAR(200) NOT NULL,
    [NameEn] NVARCHAR(200) NULL,
    [Description] NVARCHAR(500) NULL,
    [IsActive] BIT NOT NULL CONSTRAINT [DF_LookupList_IsActive] DEFAULT 1,
    [IsSystem] BIT NOT NULL CONSTRAINT [DF_LookupList_IsSystem] DEFAULT 0,
    [IsLocked] BIT NOT NULL CONSTRAINT [DF_LookupList_IsLocked] DEFAULT 0,
    [SortOrder] INT NOT NULL CONSTRAINT [DF_LookupList_SortOrder] DEFAULT 0,
    [SeedKey] VARCHAR(80) NULL,
    [ExternalCode] VARCHAR(80) NULL,
    [Scope] VARCHAR(10) NOT NULL,
    [AllowTenantItems] BIT NOT NULL CONSTRAINT [DF_LookupList_AllowTenantItems] DEFAULT 0,
    [AttributeSchema] NVARCHAR(MAX) NULL,
    [CreatedAt] DATETIME2(3) NOT NULL CONSTRAINT [DF_LookupList_CreatedAt] DEFAULT SYSUTCDATETIME(),
    [CreatedBy] BIGINT NULL,
    [UpdatedAt] DATETIME2(3) NULL,
    [UpdatedBy] BIGINT NULL,
    [RowVersion] ROWVERSION NOT NULL,
    CONSTRAINT [PK_LookupList] PRIMARY KEY CLUSTERED ([LookupListId]),
    CONSTRAINT [UQ_LookupList_Tenant] UNIQUE ([TenantId], [LookupListId]),
    CONSTRAINT [UQ_LookupList_Code] UNIQUE ([TenantId], [Code]),
    CONSTRAINT [CK_LookupList_1] CHECK ((Scope = 'SYSTEM' AND IsSystem = 1) OR (Scope = 'TENANT' AND IsSystem = 0)),
    CONSTRAINT [CK_LookupList_2] CHECK (Code NOT LIKE '%[^A-Z0-9_]%' AND Code NOT LIKE '[0-9_]%'),
    CONSTRAINT [CK_LookupList_3] CHECK ((IsLocked = 0 OR (IsSystem = 1 AND IsActive = 1)) AND (IsSystem = 0 OR NameEn IS NOT NULL)),
    CONSTRAINT [CK_LookupList_Scope] CHECK ([Scope] IS NULL OR [Scope] IN ('SYSTEM', 'TENANT')),
    CONSTRAINT [CK_LookupList_AttributeSchema_json] CHECK ([AttributeSchema] IS NULL OR ISJSON([AttributeSchema]) = 1)
);
GO
-- DR-03/05/07: مملوك للمشترك (نسخ النظام لكل مشترك)  # بند في قائمة قيم؛ TenantId فارغ = بند عالمي للقراءة فقط؛ أعمدة الكتالوج يدوية لأن فرادة الرمز داخل القائمة لا المشترك (FR-CAT-020)
CREATE TABLE [cat].[LookupItem] (
    [TenantId] INT NOT NULL,
    [LookupItemId] INT IDENTITY(1,1) NOT NULL,
    [LookupListId] INT NOT NULL,
    [Code] VARCHAR(80) NOT NULL,
    [NameAr] NVARCHAR(200) NOT NULL,
    [NameEn] NVARCHAR(200) NULL,
    [Description] NVARCHAR(500) NULL,
    [Status] VARCHAR(10) NOT NULL CONSTRAINT [DF_LookupItem_Status] DEFAULT 'ACTIVE',
    [IsActive] BIT NOT NULL CONSTRAINT [DF_LookupItem_IsActive] DEFAULT 1,
    [IsSystem] BIT NOT NULL CONSTRAINT [DF_LookupItem_IsSystem] DEFAULT 0,
    [IsLocked] BIT NOT NULL CONSTRAINT [DF_LookupItem_IsLocked] DEFAULT 0,
    [SortOrder] INT NOT NULL CONSTRAINT [DF_LookupItem_SortOrder] DEFAULT 0,
    [SeedKey] VARCHAR(80) NULL,
    [ExternalCode] VARCHAR(80) NULL,
    [Attributes] NVARCHAR(MAX) NULL,
    [CreatedAt] DATETIME2(3) NOT NULL CONSTRAINT [DF_LookupItem_CreatedAt] DEFAULT SYSUTCDATETIME(),
    [CreatedBy] BIGINT NULL,
    [UpdatedAt] DATETIME2(3) NULL,
    [UpdatedBy] BIGINT NULL,
    [RowVersion] ROWVERSION NOT NULL,
    CONSTRAINT [PK_LookupItem] PRIMARY KEY CLUSTERED ([LookupItemId]),
    CONSTRAINT [UQ_LookupItem_Tenant] UNIQUE ([TenantId], [LookupItemId]),
    CONSTRAINT [UQ_LookupItem_LookupListId_Code] UNIQUE ([TenantId], [LookupListId], [Code]),
    CONSTRAINT [CK_LookupItem_1] CHECK (Code NOT LIKE '%[^A-Z0-9_]%' AND Code NOT LIKE '[0-9_]%'),
    CONSTRAINT [CK_LookupItem_2] CHECK ((IsLocked = 0 OR (IsSystem = 1 AND IsActive = 1)) AND (IsSystem = 0 OR NameEn IS NOT NULL)),
    CONSTRAINT [CK_LookupItem_Status] CHECK ([Status] IS NULL OR [Status] IN ('ACTIVE', 'LEGACY')),
    CONSTRAINT [CK_LookupItem_Attributes_json] CHECK ([Attributes] IS NULL OR ISJSON([Attributes]) = 1)
);
GO

-- ===== schema ins =====
-- المنشأة المالية (FR-INS-001..004، BR-INS-001..003، BR-INS-012)؛ Locality محلي/أجنبي مشتقة (BR-INS-002) فلا تُخزَّن
CREATE TABLE [ins].[Institution] (
    [TenantId] INT NOT NULL,
    [InstitutionId] BIGINT IDENTITY(1,1) NOT NULL,
    [Code] VARCHAR(40) NOT NULL,
    [NameAr] NVARCHAR(200) NOT NULL,
    [NameEn] NVARCHAR(200) NULL,
    [InstitutionTypeId] INT NOT NULL,
    [CountryId] INT NOT NULL,
    [SwiftBic] VARCHAR(11) NULL,
    [Website] NVARCHAR(300) NULL,
    [PartyId] BIGINT NULL,
    [Status] VARCHAR(10) NOT NULL,
    [DirectoryRef] VARCHAR(80) NULL,
    [Notes] NVARCHAR(2000) NULL,
    [PublicId] UNIQUEIDENTIFIER NOT NULL CONSTRAINT [DF_Institution_PublicId] DEFAULT NEWSEQUENTIALID(),
    [CreatedAt] DATETIME2(3) NOT NULL CONSTRAINT [DF_Institution_CreatedAt] DEFAULT SYSUTCDATETIME(),
    [CreatedBy] BIGINT NULL,
    [UpdatedAt] DATETIME2(3) NULL,
    [UpdatedBy] BIGINT NULL,
    [RowVersion] ROWVERSION NOT NULL,
    CONSTRAINT [PK_Institution] PRIMARY KEY CLUSTERED ([InstitutionId]),
    CONSTRAINT [UQ_Institution_Tenant] UNIQUE ([TenantId], [InstitutionId]),
    CONSTRAINT [UQ_Institution_PublicId] UNIQUE ([PublicId]),
    CONSTRAINT [UQ_Institution_Code] UNIQUE ([TenantId], [Code]),
    CONSTRAINT [CK_Institution_1] CHECK (Code NOT LIKE '% %'),
    CONSTRAINT [CK_Institution_2] CHECK (SwiftBic IS NULL OR SwiftBic LIKE '[A-Z][A-Z][A-Z][A-Z][A-Z][A-Z][A-Z0-9][A-Z0-9]' OR SwiftBic LIKE '[A-Z][A-Z][A-Z][A-Z][A-Z][A-Z][A-Z0-9][A-Z0-9][A-Z0-9][A-Z0-9][A-Z0-9]'),
    CONSTRAINT [CK_Institution_Status] CHECK ([Status] IS NULL OR [Status] IN ('DRAFT', 'ACTIVE', 'INACTIVE'))
);
GO
-- وحدة في هيكل المنشأة: إدارة/قسم/فرع، شجرة ذاتية حتى 4 مستويات (FR-INS-005/006، BR-INS-004)
CREATE TABLE [ins].[InstitutionUnit] (
    [TenantId] INT NOT NULL,
    [InstitutionUnitId] BIGINT IDENTITY(1,1) NOT NULL,
    [InstitutionId] BIGINT NOT NULL,
    [ParentUnitId] BIGINT NULL,
    [UnitTypeId] INT NOT NULL,
    [NameAr] NVARCHAR(200) NOT NULL,
    [NameEn] NVARCHAR(200) NULL,
    [IsActive] BIT NOT NULL CONSTRAINT [DF_InstitutionUnit_IsActive] DEFAULT 1,
    [CreatedAt] DATETIME2(3) NOT NULL CONSTRAINT [DF_InstitutionUnit_CreatedAt] DEFAULT SYSUTCDATETIME(),
    [CreatedBy] BIGINT NULL,
    [UpdatedAt] DATETIME2(3) NULL,
    [UpdatedBy] BIGINT NULL,
    [RowVersion] ROWVERSION NOT NULL,
    CONSTRAINT [PK_InstitutionUnit] PRIMARY KEY CLUSTERED ([InstitutionUnitId]),
    CONSTRAINT [UQ_InstitutionUnit_Tenant] UNIQUE ([TenantId], [InstitutionUnitId]),
    CONSTRAINT [UQ_InstitutionUnit_Scope_InstitutionId] UNIQUE ([TenantId], [InstitutionId], [InstitutionUnitId]),
    CONSTRAINT [UQ_InstitutionUnit_InstitutionId_ParentUnitId_NameAr] UNIQUE ([TenantId], [InstitutionId], [ParentUnitId], [NameAr]),
    CONSTRAINT [CK_InstitutionUnit_1] CHECK (ParentUnitId IS NULL OR ParentUnitId <> InstitutionUnitId)
);
GO
-- جهة اتصال لدى البنك: سجل خفيف بلا هوية، PartyId اختياري للترقية (FR-INS-007/008، BR-INS-005/006/014)
CREATE TABLE [ins].[Contact] (
    [TenantId] INT NOT NULL,
    [ContactId] BIGINT IDENTITY(1,1) NOT NULL,
    [InstitutionId] BIGINT NOT NULL,
    [UnitId] BIGINT NULL,
    [FullNameAr] NVARCHAR(200) NOT NULL,
    [FullNameEn] NVARCHAR(200) NULL,
    [JobTitleAr] NVARCHAR(200) NULL,
    [JobTitleEn] NVARCHAR(200) NULL,
    [ReportsToContactId] BIGINT NULL,
    [PartyId] BIGINT NULL,
    [Status] VARCHAR(10) NOT NULL CONSTRAINT [DF_Contact_Status] DEFAULT 'ACTIVE',
    [InactiveReason] VARCHAR(11) NULL,
    [Notes] NVARCHAR(1000) NULL,
    [PublicId] UNIQUEIDENTIFIER NOT NULL CONSTRAINT [DF_Contact_PublicId] DEFAULT NEWSEQUENTIALID(),
    [CreatedAt] DATETIME2(3) NOT NULL CONSTRAINT [DF_Contact_CreatedAt] DEFAULT SYSUTCDATETIME(),
    [CreatedBy] BIGINT NULL,
    [UpdatedAt] DATETIME2(3) NULL,
    [UpdatedBy] BIGINT NULL,
    [RowVersion] ROWVERSION NOT NULL,
    CONSTRAINT [PK_Contact] PRIMARY KEY CLUSTERED ([ContactId]),
    CONSTRAINT [UQ_Contact_Tenant] UNIQUE ([TenantId], [ContactId]),
    CONSTRAINT [UQ_Contact_Scope_InstitutionId] UNIQUE ([TenantId], [InstitutionId], [ContactId]),
    CONSTRAINT [UQ_Contact_PublicId] UNIQUE ([PublicId]),
    CONSTRAINT [CK_Contact_1] CHECK (ReportsToContactId IS NULL OR ReportsToContactId <> ContactId),
    CONSTRAINT [CK_Contact_2] CHECK (Status <> 'INACTIVE' OR InactiveReason IS NOT NULL),
    CONSTRAINT [CK_Contact_Status] CHECK ([Status] IS NULL OR [Status] IN ('ACTIVE', 'INACTIVE')),
    CONSTRAINT [CK_Contact_InactiveReason] CHECK ([InactiveReason] IS NULL OR [InactiveReason] IN ('LEFT_BANK', 'TRANSFERRED', 'OTHER'))
);
GO
-- علاقة شركة–منشأة (D-4)؛ فريدة مهما كانت حالتها (FR-INS-009، BR-INS-007/011)
CREATE TABLE [ins].[Relationship] (
    [TenantId] INT NOT NULL,
    [RelationshipId] BIGINT IDENTITY(1,1) NOT NULL,
    [CompanyId] BIGINT NOT NULL,
    [InstitutionId] BIGINT NOT NULL,
    [CustomerNoAtBank] VARCHAR(40) NULL,
    [Status] VARCHAR(10) NOT NULL,
    [StartedOn] DATE NULL,
    [ClosedOn] DATE NULL,
    [ClosureReason] NVARCHAR(300) NULL,
    [Notes] NVARCHAR(2000) NULL,
    [PublicId] UNIQUEIDENTIFIER NOT NULL CONSTRAINT [DF_Relationship_PublicId] DEFAULT NEWSEQUENTIALID(),
    [CreatedAt] DATETIME2(3) NOT NULL CONSTRAINT [DF_Relationship_CreatedAt] DEFAULT SYSUTCDATETIME(),
    [CreatedBy] BIGINT NULL,
    [UpdatedAt] DATETIME2(3) NULL,
    [UpdatedBy] BIGINT NULL,
    [RowVersion] ROWVERSION NOT NULL,
    CONSTRAINT [PK_Relationship] PRIMARY KEY CLUSTERED ([RelationshipId]),
    CONSTRAINT [UQ_Relationship_Tenant] UNIQUE ([TenantId], [RelationshipId]),
    CONSTRAINT [UQ_Relationship_Scope_CompanyId_InstitutionId] UNIQUE ([TenantId], [CompanyId], [InstitutionId], [RelationshipId]),
    CONSTRAINT [UQ_Relationship_Scope_InstitutionId] UNIQUE ([TenantId], [InstitutionId], [RelationshipId]),
    CONSTRAINT [UQ_Relationship_PublicId] UNIQUE ([PublicId]),
    CONSTRAINT [UQ_Relationship_CompanyId_InstitutionId] UNIQUE ([TenantId], [CompanyId], [InstitutionId]),
    CONSTRAINT [CK_Relationship_1] CHECK (Status <> 'CLOSED' OR (ClosedOn IS NOT NULL AND ClosureReason IS NOT NULL)),
    CONSTRAINT [CK_Relationship_2] CHECK (ClosedOn IS NULL OR StartedOn IS NULL OR ClosedOn >= StartedOn),
    CONSTRAINT [CK_Relationship_Status] CHECK ([Status] IS NULL OR [Status] IN ('PROSPECT', 'ACTIVE', 'SUSPENDED', 'CLOSED'))
);
GO
-- تغطية العلاقة (الطبقة الأولى): جهة اتصال بدور ورتبة وفترة (FR-INS-010، BR-INS-008/009)
CREATE TABLE [ins].[RelationshipContact] (
    [TenantId] INT NOT NULL,
    [RelationshipContactId] BIGINT IDENTITY(1,1) NOT NULL,
    [InstitutionId] BIGINT NOT NULL,
    [RelationshipId] BIGINT NOT NULL,
    [ContactId] BIGINT NOT NULL,
    [RoleId] INT NOT NULL,
    [Rank] INT NOT NULL,
    [IsPrimary] BIT NOT NULL CONSTRAINT [DF_RelationshipContact_IsPrimary] DEFAULT 0,
    [ValidFrom] DATE NOT NULL,
    [ValidTo] DATE NULL,
    [Notes] NVARCHAR(500) NULL,
    [CreatedAt] DATETIME2(3) NOT NULL CONSTRAINT [DF_RelationshipContact_CreatedAt] DEFAULT SYSUTCDATETIME(),
    [CreatedBy] BIGINT NULL,
    [UpdatedAt] DATETIME2(3) NULL,
    [UpdatedBy] BIGINT NULL,
    [RowVersion] ROWVERSION NOT NULL,
    CONSTRAINT [PK_RelationshipContact] PRIMARY KEY CLUSTERED ([RelationshipContactId]),
    CONSTRAINT [UQ_RelationshipContact_Tenant] UNIQUE ([TenantId], [RelationshipContactId]),
    CONSTRAINT [UQ_RelationshipContact_RelationshipId_ContactId_RoleId_ValidFrom] UNIQUE ([TenantId], [RelationshipId], [ContactId], [RoleId], [ValidFrom]),
    CONSTRAINT [CK_RelationshipContact_1] CHECK (ValidTo IS NULL OR ValidTo >= ValidFrom),
    CONSTRAINT [CK_RelationshipContact_2] CHECK (Rank >= 1)
);
GO
-- منتج يُتعامل به ضمن علاقة مع جهة افتراضية وقناة (FR-INS-011..013، BR-INS-010)
CREATE TABLE [ins].[RelationshipProduct] (
    [TenantId] INT NOT NULL,
    [RelationshipProductId] BIGINT IDENTITY(1,1) NOT NULL,
    [InstitutionId] BIGINT NOT NULL,
    [RelationshipId] BIGINT NOT NULL,
    [ProductId] INT NOT NULL,
    [DefaultContactId] BIGINT NULL,
    [PreferredChannel] VARCHAR(18) NOT NULL CONSTRAINT [DF_RelationshipProduct_PreferredChannel] DEFAULT 'MANUAL_FORM',
    [ChannelNotes] NVARCHAR(500) NULL,
    [IsActive] BIT NOT NULL CONSTRAINT [DF_RelationshipProduct_IsActive] DEFAULT 1,
    [SinceDate] DATE NULL,
    [CreatedAt] DATETIME2(3) NOT NULL CONSTRAINT [DF_RelationshipProduct_CreatedAt] DEFAULT SYSUTCDATETIME(),
    [CreatedBy] BIGINT NULL,
    [UpdatedAt] DATETIME2(3) NULL,
    [UpdatedBy] BIGINT NULL,
    [RowVersion] ROWVERSION NOT NULL,
    CONSTRAINT [PK_RelationshipProduct] PRIMARY KEY CLUSTERED ([RelationshipProductId]),
    CONSTRAINT [UQ_RelationshipProduct_Tenant] UNIQUE ([TenantId], [RelationshipProductId]),
    CONSTRAINT [UQ_RelationshipProduct_RelationshipId_ProductId] UNIQUE ([TenantId], [RelationshipId], [ProductId]),
    CONSTRAINT [CK_RelationshipProduct_PreferredChannel] CHECK ([PreferredChannel] IS NULL OR [PreferredChannel] IN ('BANK_PORTAL', 'MANUAL_FORM', 'DIRECT_INTEGRATION'))
);
GO

-- ===== schema acc =====
-- حساب شركة لدى منشأة (FR-ACC-001..009، BR-ACC-001..006، BR-ACC-016)؛ الرقم وIBAN مشفّران بفهرس أعمى للفرادة
CREATE TABLE [acc].[BankAccount] (
    [TenantId] INT NOT NULL,
    [BankAccountId] BIGINT IDENTITY(1,1) NOT NULL,
    [CompanyId] BIGINT NOT NULL,
    [InstitutionId] BIGINT NOT NULL,
    [RelationshipId] BIGINT NOT NULL,
    [AccountTypeId] INT NOT NULL,
    [MasterAccountId] BIGINT NULL,
    [CurrencyId] INT NOT NULL,
    [Nickname] NVARCHAR(100) NULL,
    [AccountNoEnc] VARBINARY(512) NOT NULL,
    [AccountNoMask] NVARCHAR(32) NOT NULL,
    [AccountNoHash] VARBINARY(32) NOT NULL,
    [AccountNoLast4] VARCHAR(4) NOT NULL,
    [IbanEnc] VARBINARY(512) NULL,
    [IbanMask] NVARCHAR(32) NULL,
    [IbanHash] VARBINARY(32) NULL,
    [EncKeyPurpose] VARCHAR(10) NOT NULL CONSTRAINT [DF_BankAccount_EncKeyPurpose] DEFAULT 'DATA',
    [EncKeyId] BIGINT NOT NULL,
    [HashKeyPurpose] VARCHAR(11) NOT NULL CONSTRAINT [DF_BankAccount_HashKeyPurpose] DEFAULT 'BLIND_INDEX',
    [HashKeyId] BIGINT NOT NULL,
    [BranchUnitId] BIGINT NULL,
    [SigningRuleText] NVARCHAR(500) NULL,
    [MinSignatures] INT NOT NULL CONSTRAINT [DF_BankAccount_MinSignatures] DEFAULT 1,
    [Status] VARCHAR(10) NOT NULL CONSTRAINT [DF_BankAccount_Status] DEFAULT 'ACTIVE',
    [OpenedOn] DATE NULL,
    [ClosedOn] DATE NULL,
    [ClosureReason] NVARCHAR(300) NULL,
    [PublicId] UNIQUEIDENTIFIER NOT NULL CONSTRAINT [DF_BankAccount_PublicId] DEFAULT NEWSEQUENTIALID(),
    [CreatedAt] DATETIME2(3) NOT NULL CONSTRAINT [DF_BankAccount_CreatedAt] DEFAULT SYSUTCDATETIME(),
    [CreatedBy] BIGINT NULL,
    [UpdatedAt] DATETIME2(3) NULL,
    [UpdatedBy] BIGINT NULL,
    [RowVersion] ROWVERSION NOT NULL,
    CONSTRAINT [PK_BankAccount] PRIMARY KEY CLUSTERED ([BankAccountId]),
    CONSTRAINT [UQ_BankAccount_Tenant] UNIQUE ([TenantId], [BankAccountId]),
    CONSTRAINT [UQ_BankAccount_Scope_CompanyId] UNIQUE ([TenantId], [CompanyId], [BankAccountId]),
    CONSTRAINT [UQ_BankAccount_Scope_CompanyId_InstitutionId_CurrencyId] UNIQUE ([TenantId], [CompanyId], [InstitutionId], [CurrencyId], [BankAccountId]),
    CONSTRAINT [UQ_BankAccount_Scope_CurrencyId] UNIQUE ([TenantId], [CurrencyId], [BankAccountId]),
    CONSTRAINT [UQ_BankAccount_Scope_RelationshipId] UNIQUE ([TenantId], [RelationshipId], [BankAccountId]),
    CONSTRAINT [UQ_BankAccount_PublicId] UNIQUE ([PublicId]),
    CONSTRAINT [UQ_BankAccount_InstitutionId_AccountNoHash] UNIQUE ([TenantId], [InstitutionId], [AccountNoHash]),
    CONSTRAINT [CK_BankAccount_1] CHECK (MinSignatures >= 1),
    CONSTRAINT [CK_BankAccount_2] CHECK (DATALENGTH(AccountNoEnc) >= 29),
    CONSTRAINT [CK_BankAccount_3] CHECK (IbanEnc IS NULL OR DATALENGTH(IbanEnc) >= 29),
    CONSTRAINT [CK_BankAccount_4] CHECK (MasterAccountId IS NULL OR MasterAccountId <> BankAccountId),
    CONSTRAINT [CK_BankAccount_5] CHECK ((IbanEnc IS NULL AND IbanMask IS NULL AND IbanHash IS NULL) OR (IbanEnc IS NOT NULL AND IbanMask IS NOT NULL AND IbanHash IS NOT NULL)),
    CONSTRAINT [CK_BankAccount_6] CHECK (ClosedOn IS NULL OR OpenedOn IS NULL OR ClosedOn >= OpenedOn),
    CONSTRAINT [CK_BankAccount_7] CHECK (Status <> 'CLOSED' OR (ClosedOn IS NOT NULL AND ClosureReason IS NOT NULL)),
    CONSTRAINT [CK_BankAccount_8] CHECK ((ClosedOn IS NULL AND ClosureReason IS NULL) OR Status = 'CLOSED'),
    CONSTRAINT [CK_BankAccount_EncKeyPurpose] CHECK ([EncKeyPurpose] IS NULL OR [EncKeyPurpose] IN ('DATA')),
    CONSTRAINT [CK_BankAccount_HashKeyPurpose] CHECK ([HashKeyPurpose] IS NULL OR [HashKeyPurpose] IN ('BLIND_INDEX')),
    CONSTRAINT [CK_BankAccount_Status] CHECK ([Status] IS NULL OR [Status] IN ('ACTIVE', 'DORMANT', 'FROZEN', 'CLOSED'))
);
GO
-- ربط حساب بتسهيل بغرض (S2) (FR-ACC-010، BR-ACC-007)؛ يُملأ من شاشة التسهيل
CREATE TABLE [acc].[FacilityAccount] (
    [TenantId] INT NOT NULL,
    [FacilityAccountId] BIGINT IDENTITY(1,1) NOT NULL,
    [FacilityId] BIGINT NOT NULL,
    [BankAccountId] BIGINT NOT NULL,
    [CurrencyId] INT NOT NULL,
    [PurposeId] INT NOT NULL,
    [IsDefault] BIT NOT NULL CONSTRAINT [DF_FacilityAccount_IsDefault] DEFAULT 0,
    [ValidFrom] DATE NULL,
    [ValidTo] DATE NULL,
    [Notes] NVARCHAR(500) NULL,
    [CreatedAt] DATETIME2(3) NOT NULL CONSTRAINT [DF_FacilityAccount_CreatedAt] DEFAULT SYSUTCDATETIME(),
    [CreatedBy] BIGINT NULL,
    [UpdatedAt] DATETIME2(3) NULL,
    [UpdatedBy] BIGINT NULL,
    [RowVersion] ROWVERSION NOT NULL,
    CONSTRAINT [PK_FacilityAccount] PRIMARY KEY CLUSTERED ([FacilityAccountId]),
    CONSTRAINT [UQ_FacilityAccount_Tenant] UNIQUE ([TenantId], [FacilityAccountId]),
    CONSTRAINT [UQ_FacilityAccount_FacilityId_BankAccountId_PurposeId] UNIQUE ([TenantId], [FacilityId], [BankAccountId], [PurposeId]),
    CONSTRAINT [CK_FacilityAccount_1] CHECK (ValidTo IS NULL OR ValidFrom IS NULL OR ValidTo >= ValidFrom)
);
GO
-- تفويض شخص لدى علاقة (S1-ب) (FR-ACC-012، FR-ACC-023، BR-ACC-008/009) + إضافات docs/05 G-10
CREATE TABLE [acc].[Signatory] (
    [TenantId] INT NOT NULL,
    [SignatoryId] BIGINT IDENTITY(1,1) NOT NULL,
    [RelationshipId] BIGINT NOT NULL,
    [PartyId] BIGINT NOT NULL,
    [SignatureClassId] INT NOT NULL,
    [PositionId] INT NULL,
    [JobTitle] NVARCHAR(200) NULL,
    [AuthorisationBasisId] INT NULL,
    [SignatureType] VARCHAR(22) NULL,
    [CashWithdrawalMode] VARCHAR(11) NOT NULL CONSTRAINT [DF_Signatory_CashWithdrawalMode] DEFAULT 'UNSPECIFIED',
    [CashWithdrawalLimit] DECIMAL(19,4) NULL,
    [CashWithdrawalCurrencyId] INT NULL,
    [AuthorizationDocumentId] BIGINT NULL,
    [SpecimenDocumentId] BIGINT NULL,
    [ValidFrom] DATE NOT NULL,
    [ValidTo] DATE NULL,
    [Status] VARCHAR(10) NOT NULL CONSTRAINT [DF_Signatory_Status] DEFAULT 'PENDING',
    [Notes] NVARCHAR(1000) NULL,
    [PublicId] UNIQUEIDENTIFIER NOT NULL CONSTRAINT [DF_Signatory_PublicId] DEFAULT NEWSEQUENTIALID(),
    [CreatedAt] DATETIME2(3) NOT NULL CONSTRAINT [DF_Signatory_CreatedAt] DEFAULT SYSUTCDATETIME(),
    [CreatedBy] BIGINT NULL,
    [UpdatedAt] DATETIME2(3) NULL,
    [UpdatedBy] BIGINT NULL,
    [RowVersion] ROWVERSION NOT NULL,
    CONSTRAINT [PK_Signatory] PRIMARY KEY CLUSTERED ([SignatoryId]),
    CONSTRAINT [UQ_Signatory_Tenant] UNIQUE ([TenantId], [SignatoryId]),
    CONSTRAINT [UQ_Signatory_Scope_RelationshipId] UNIQUE ([TenantId], [RelationshipId], [SignatoryId]),
    CONSTRAINT [UQ_Signatory_PublicId] UNIQUE ([PublicId]),
    CONSTRAINT [UQ_Signatory_RelationshipId_PartyId_SignatureClassId_ValidFrom] UNIQUE ([TenantId], [RelationshipId], [PartyId], [SignatureClassId], [ValidFrom]),
    CONSTRAINT [CK_Signatory_1] CHECK (ValidTo IS NULL OR ValidTo >= ValidFrom),
    CONSTRAINT [CK_Signatory_2] CHECK (Status NOT IN ('ACTIVE','SUSPENDED','EXPIRED') OR AuthorizationDocumentId IS NOT NULL),
    CONSTRAINT [CK_Signatory_3] CHECK ((CashWithdrawalMode = 'LIMITED' AND CashWithdrawalLimit IS NOT NULL AND CashWithdrawalLimit > 0 AND CashWithdrawalCurrencyId IS NOT NULL) OR (CashWithdrawalMode <> 'LIMITED' AND CashWithdrawalLimit IS NULL)),
    CONSTRAINT [CK_Signatory_SignatureType] CHECK ([SignatureType] IS NULL OR [SignatureType] IN ('INDIVIDUAL', 'WITH_PRIMARY_SIGNATORY')),
    CONSTRAINT [CK_Signatory_CashWithdrawalMode] CHECK ([CashWithdrawalMode] IS NULL OR [CashWithdrawalMode] IN ('LIMITED', 'UNLIMITED', 'UNSPECIFIED')),
    CONSTRAINT [CK_Signatory_Status] CHECK ([Status] IS NULL OR [Status] IN ('PENDING', 'ACTIVE', 'SUSPENDED', 'EXPIRED', 'REVOKED'))
);
GO
-- صلاحية المفوّض لعملية على حساب أو على البنك (S1-ب) (FR-ACC-013/014/017، BR-ACC-010/011)؛ لا تعديل في مكانه: الإغلاق والفتح؛ حالتها مشتقة فلا تُخزَّن
CREATE TABLE [acc].[SignatoryAuthority] (
    [TenantId] INT NOT NULL,
    [SignatoryAuthorityId] BIGINT IDENTITY(1,1) NOT NULL,
    [RelationshipId] BIGINT NOT NULL,
    [SignatoryId] BIGINT NOT NULL,
    [BankAccountId] BIGINT NULL,
    [OperationTypeId] INT NOT NULL,
    [CeilingMode] VARCHAR(11) NOT NULL,
    [MaxPerTransaction] DECIMAL(19,4) NULL,
    [DailyLimit] DECIMAL(19,4) NULL,
    [CurrencyId] INT NULL,
    [IsJoint] BIT NOT NULL CONSTRAINT [DF_SignatoryAuthority_IsJoint] DEFAULT 0,
    [JointMinCosigners] INT NULL,
    [ValidFrom] DATE NOT NULL,
    [ValidTo] DATE NULL,
    [SourceDocumentId] BIGINT NULL,
    [SupersededById] BIGINT NULL,
    [CreatedAt] DATETIME2(3) NOT NULL CONSTRAINT [DF_SignatoryAuthority_CreatedAt] DEFAULT SYSUTCDATETIME(),
    [CreatedBy] BIGINT NULL,
    [UpdatedAt] DATETIME2(3) NULL,
    [UpdatedBy] BIGINT NULL,
    [RowVersion] ROWVERSION NOT NULL,
    CONSTRAINT [PK_SignatoryAuthority] PRIMARY KEY CLUSTERED ([SignatoryAuthorityId]),
    CONSTRAINT [UQ_SignatoryAuthority_Tenant] UNIQUE ([TenantId], [SignatoryAuthorityId]),
    CONSTRAINT [UQ_SignatoryAuthority_Scope_SignatoryId] UNIQUE ([TenantId], [SignatoryId], [SignatoryAuthorityId]),
    CONSTRAINT [UQ_SignatoryAuthority_SignatoryId_OperationTypeId_BankAccountId_ValidFrom] UNIQUE ([TenantId], [SignatoryId], [OperationTypeId], [BankAccountId], [ValidFrom]),
    CONSTRAINT [CK_SignatoryAuthority_1] CHECK (ValidTo IS NULL OR ValidTo >= ValidFrom),
    CONSTRAINT [CK_SignatoryAuthority_2] CHECK (CeilingMode <> 'LIMITED' OR (CurrencyId IS NOT NULL AND ((MaxPerTransaction IS NOT NULL AND MaxPerTransaction > 0) OR (DailyLimit IS NOT NULL AND DailyLimit > 0)))),
    CONSTRAINT [CK_SignatoryAuthority_3] CHECK (CeilingMode = 'LIMITED' OR (MaxPerTransaction IS NULL AND DailyLimit IS NULL)),
    CONSTRAINT [CK_SignatoryAuthority_4] CHECK (MaxPerTransaction IS NULL OR MaxPerTransaction > 0),
    CONSTRAINT [CK_SignatoryAuthority_5] CHECK (DailyLimit IS NULL OR DailyLimit > 0),
    CONSTRAINT [CK_SignatoryAuthority_6] CHECK (MaxPerTransaction IS NULL OR DailyLimit IS NULL OR DailyLimit >= MaxPerTransaction),
    CONSTRAINT [CK_SignatoryAuthority_7] CHECK ((IsJoint = 1 AND (JointMinCosigners IS NULL OR JointMinCosigners >= 1)) OR (IsJoint = 0 AND JointMinCosigners IS NULL)),
    CONSTRAINT [CK_SignatoryAuthority_8] CHECK (SupersededById IS NULL OR SupersededById <> SignatoryAuthorityId),
    CONSTRAINT [CK_SignatoryAuthority_CeilingMode] CHECK ([CeilingMode] IS NULL OR [CeilingMode] IN ('LIMITED', 'UNLIMITED', 'UNSPECIFIED'))
);
GO
-- فئات التوقيع المطلوبة للتوقيع المشترك (JointClassIds) (BR-ACC-013) -- جدول وسيط جديد؛ لا حذف: التعديل بصف صلاحية جديد
CREATE TABLE [acc].[SignatoryAuthorityJointClass] (
    [TenantId] INT NOT NULL,
    [SignatoryAuthorityId] BIGINT NOT NULL,
    [SignatureClassId] INT NOT NULL,
    [CreatedAt] DATETIME2(3) NOT NULL CONSTRAINT [DF_SignatoryAuthorityJointClass_CreatedAt] DEFAULT SYSUTCDATETIME(),
    [CreatedBy] BIGINT NULL,
    [UpdatedAt] DATETIME2(3) NULL,
    [UpdatedBy] BIGINT NULL,
    CONSTRAINT [PK_SignatoryAuthorityJointClass] PRIMARY KEY CLUSTERED ([TenantId], [SignatoryAuthorityId], [SignatureClassId])
);
GO
-- نتيجة مقارنة صلاحية المفوّض بالحوكمة وقرار المراجع (S1-ب) (FR-ACC-018، BR-ACC-015)
CREATE TABLE [acc].[AuthorityConflict] (
    [TenantId] INT NOT NULL,
    [AuthorityConflictId] BIGINT IDENTITY(1,1) NOT NULL,
    [SignatoryAuthorityId] BIGINT NOT NULL,
    [ConflictCode] VARCHAR(25) NOT NULL,
    [Fingerprint] VARCHAR(64) NOT NULL,
    [Status] VARCHAR(12) NOT NULL CONSTRAINT [DF_AuthorityConflict_Status] DEFAULT 'OPEN',
    [Reason] NVARCHAR(500) NULL,
    [ReviewedBy] BIGINT NULL,
    [ReviewedOn] DATETIME2(3) NULL,
    [DetectedOn] DATETIME2(3) NOT NULL,
    [CreatedAt] DATETIME2(3) NOT NULL CONSTRAINT [DF_AuthorityConflict_CreatedAt] DEFAULT SYSUTCDATETIME(),
    [CreatedBy] BIGINT NULL,
    [UpdatedAt] DATETIME2(3) NULL,
    [UpdatedBy] BIGINT NULL,
    [RowVersion] ROWVERSION NOT NULL,
    CONSTRAINT [PK_AuthorityConflict] PRIMARY KEY CLUSTERED ([AuthorityConflictId]),
    CONSTRAINT [UQ_AuthorityConflict_Tenant] UNIQUE ([TenantId], [AuthorityConflictId]),
    CONSTRAINT [UQ_AuthorityConflict_SignatoryAuthorityId_ConflictCode_Fingerprint] UNIQUE ([TenantId], [SignatoryAuthorityId], [ConflictCode], [Fingerprint]),
    CONSTRAINT [CK_AuthorityConflict_1] CHECK (Status <> 'ACKNOWLEDGED' OR (ReviewedBy IS NOT NULL AND ReviewedOn IS NOT NULL AND Reason IS NOT NULL)),
    CONSTRAINT [CK_AuthorityConflict_2] CHECK (ReviewedBy IS NULL OR ReviewedOn IS NOT NULL),
    CONSTRAINT [CK_AuthorityConflict_ConflictCode] CHECK ([ConflictCode] IS NULL OR [ConflictCode] IN ('NO_GRANT', 'CEILING_EXCEEDS', 'JOINT_MISMATCH', 'GRANT_EXPIRED', 'GRANT_CEILING_UNSPECIFIED', 'NOT_COMPARABLE_CURRENCY', 'NOT_MAPPED')),
    CONSTRAINT [CK_AuthorityConflict_Status] CHECK ([Status] IS NULL OR [Status] IN ('OPEN', 'ACKNOWLEDGED', 'RESOLVED'))
);
GO

-- ===== schema fac =====
-- حزمة الاتفاقية الائتمانية: جذر التجميعة (FR-FAC-001..008، BR-FAC-001/005/006)
CREATE TABLE [fac].[Facility] (
    [TenantId] INT NOT NULL,
    [FacilityId] BIGINT IDENTITY(1,1) NOT NULL,
    [FacilityNo] VARCHAR(40) NOT NULL,
    [BankReferenceNo] NVARCHAR(80) NULL,
    [BankStructureNo] NVARCHAR(80) NULL,
    [BorrowerCompanyId] BIGINT NOT NULL,
    [FacilityTypeId] INT NOT NULL,
    [CurrencyId] INT NOT NULL,
    [TotalAmount] DECIMAL(19,4) NOT NULL,
    [IsSyndicated] BIT NOT NULL CONSTRAINT [DF_Facility_IsSyndicated] DEFAULT 0,
    [PrecedenceLanguage] VARCHAR(10) NOT NULL,
    [PrecedenceClauseRef] NVARCHAR(100) NULL,
    [AgreementDate] DATE NULL,
    [AgreementDateHijri] NVARCHAR(20) NULL,
    [EffectiveFrom] DATE NOT NULL,
    [EffectiveFromHijri] NVARCHAR(20) NULL,
    [ExpiryDate] DATE NOT NULL,
    [ExpiryDateHijri] NVARCHAR(20) NULL,
    [OperativeCalendar] VARCHAR(10) NOT NULL CONSTRAINT [DF_Facility_OperativeCalendar] DEFAULT 'GREGORIAN',
    [HijriAdjusted] BIT NOT NULL CONSTRAINT [DF_Facility_HijriAdjusted] DEFAULT 0,
    [HijriAdjustReason] NVARCHAR(300) NULL,
    [PreviousFacilityId] BIGINT NULL,
    [LifecycleStatus] VARCHAR(10) NOT NULL CONSTRAINT [DF_Facility_LifecycleStatus] DEFAULT 'DRAFT',
    [LifecycleReason] NVARCHAR(500) NULL,
    [BankUnilateralRights] VARCHAR(43) NULL,
    [NoticeDays] INT NULL,
    [UsageBlockOnBreach] BIT NOT NULL CONSTRAINT [DF_Facility_UsageBlockOnBreach] DEFAULT 0,
    [UsageBlockOnUnconfirmed] BIT NOT NULL CONSTRAINT [DF_Facility_UsageBlockOnUnconfirmed] DEFAULT 0,
    [AlertLeadDays] VARCHAR(40) NULL,
    [ApprovedRevisionNo] INT NOT NULL CONSTRAINT [DF_Facility_ApprovedRevisionNo] DEFAULT 0,
    [PublicId] UNIQUEIDENTIFIER NOT NULL CONSTRAINT [DF_Facility_PublicId] DEFAULT NEWSEQUENTIALID(),
    [CreatedAt] DATETIME2(3) NOT NULL CONSTRAINT [DF_Facility_CreatedAt] DEFAULT SYSUTCDATETIME(),
    [CreatedBy] BIGINT NULL,
    [UpdatedAt] DATETIME2(3) NULL,
    [UpdatedBy] BIGINT NULL,
    [RowVersion] ROWVERSION NOT NULL,
    CONSTRAINT [PK_Facility] PRIMARY KEY CLUSTERED ([FacilityId]),
    CONSTRAINT [UQ_Facility_Tenant] UNIQUE ([TenantId], [FacilityId]),
    CONSTRAINT [UQ_Facility_PublicId] UNIQUE ([PublicId]),
    CONSTRAINT [UQ_Facility_FacilityNo] UNIQUE ([TenantId], [FacilityNo]),
    CONSTRAINT [CK_Facility_1] CHECK (ExpiryDate >= EffectiveFrom),
    CONSTRAINT [CK_Facility_2] CHECK (AgreementDate IS NULL OR AgreementDate <= EffectiveFrom),
    CONSTRAINT [CK_Facility_3] CHECK (TotalAmount > 0),
    CONSTRAINT [CK_Facility_4] CHECK (PreviousFacilityId IS NULL OR PreviousFacilityId <> FacilityId),
    CONSTRAINT [CK_Facility_5] CHECK (NoticeDays IS NULL OR NoticeDays >= 0),
    CONSTRAINT [CK_Facility_6] CHECK (BankUnilateralRights IS NULL OR BankUnilateralRights NOT LIKE '%CHANGE_PRICING%' OR NoticeDays IS NOT NULL),
    CONSTRAINT [CK_Facility_7] CHECK (HijriAdjusted = 0 OR HijriAdjustReason IS NOT NULL),
    CONSTRAINT [CK_Facility_8] CHECK (LifecycleStatus NOT IN ('SUSPENDED','EXPIRED','TERMINATED') OR LifecycleReason IS NOT NULL),
    CONSTRAINT [CK_Facility_9] CHECK (ApprovedRevisionNo >= 0),
    CONSTRAINT [CK_Facility_10] CHECK (LifecycleStatus = 'DRAFT' OR ApprovedRevisionNo >= 1),
    CONSTRAINT [CK_Facility_11] CHECK (AlertLeadDays IS NULL OR AlertLeadDays NOT LIKE '%[^0-9,]%'),
    CONSTRAINT [CK_Facility_PrecedenceLanguage] CHECK ([PrecedenceLanguage] IS NULL OR [PrecedenceLanguage] IN ('AR', 'EN', 'EQUAL')),
    CONSTRAINT [CK_Facility_OperativeCalendar] CHECK ([OperativeCalendar] IS NULL OR [OperativeCalendar] IN ('GREGORIAN', 'HIJRI')),
    CONSTRAINT [CK_Facility_LifecycleStatus] CHECK ([LifecycleStatus] IS NULL OR [LifecycleStatus] IN ('DRAFT', 'ACTIVE', 'SUSPENDED', 'EXPIRED', 'TERMINATED', 'SUPERSEDED'))
);
GO
-- مراجعة معدّ/معتمِد لشروط التسهيل (FR-FAC-024، BR-FAC-003/004، §8)
CREATE TABLE [fac].[FacilityRevision] (
    [TenantId] INT NOT NULL,
    [FacilityRevisionId] BIGINT IDENTITY(1,1) NOT NULL,
    [FacilityId] BIGINT NOT NULL,
    [RevisionNo] INT NOT NULL,
    [ReasonKind] VARCHAR(12) NOT NULL,
    [Status] VARCHAR(10) NOT NULL CONSTRAINT [DF_FacilityRevision_Status] DEFAULT 'DRAFT',
    [EffectiveOn] DATE NOT NULL,
    [ChangeSummary] NVARCHAR(1000) NULL,
    [HeaderChanges] NVARCHAR(MAX) NULL,
    [SubmittedBy] BIGINT NULL,
    [SubmittedOn] DATETIME2(3) NULL,
    [ApprovedBy] BIGINT NULL,
    [ApprovedOn] DATETIME2(3) NULL,
    [RejectionReason] NVARCHAR(1000) NULL,
    [IntegrityResult] NVARCHAR(MAX) NULL,
    [CreatedAt] DATETIME2(3) NOT NULL CONSTRAINT [DF_FacilityRevision_CreatedAt] DEFAULT SYSUTCDATETIME(),
    [CreatedBy] BIGINT NULL,
    [UpdatedAt] DATETIME2(3) NULL,
    [UpdatedBy] BIGINT NULL,
    [RowVersion] ROWVERSION NOT NULL,
    CONSTRAINT [PK_FacilityRevision] PRIMARY KEY CLUSTERED ([FacilityRevisionId]),
    CONSTRAINT [UQ_FacilityRevision_Tenant] UNIQUE ([TenantId], [FacilityRevisionId]),
    CONSTRAINT [UQ_FacilityRevision_FacilityId_RevisionNo] UNIQUE ([TenantId], [FacilityId], [RevisionNo]),
    CONSTRAINT [CK_FacilityRevision_1] CHECK (RevisionNo >= 1),
    CONSTRAINT [CK_FacilityRevision_2] CHECK (ReasonKind <> 'INITIAL' OR RevisionNo = 1),
    CONSTRAINT [CK_FacilityRevision_3] CHECK (Status NOT IN ('SUBMITTED','APPROVED') OR (SubmittedBy IS NOT NULL AND SubmittedOn IS NOT NULL)),
    CONSTRAINT [CK_FacilityRevision_4] CHECK (Status <> 'APPROVED' OR (ApprovedBy IS NOT NULL AND ApprovedOn IS NOT NULL)),
    CONSTRAINT [CK_FacilityRevision_5] CHECK (Status <> 'REJECTED' OR RejectionReason IS NOT NULL),
    CONSTRAINT [CK_FacilityRevision_ReasonKind] CHECK ([ReasonKind] IS NULL OR [ReasonKind] IN ('INITIAL', 'AMENDMENT', 'EXTENSION', 'CORRECTION', 'RENEWAL_COPY')),
    CONSTRAINT [CK_FacilityRevision_Status] CHECK ([Status] IS NULL OR [Status] IN ('DRAFT', 'SUBMITTED', 'APPROVED', 'REJECTED', 'DISCARDED')),
    CONSTRAINT [CK_FacilityRevision_HeaderChanges_json] CHECK ([HeaderChanges] IS NULL OR ISJSON([HeaderChanges]) = 1),
    CONSTRAINT [CK_FacilityRevision_IntegrityResult_json] CHECK ([IntegrityResult] IS NULL OR ISJSON([IntegrityResult]) = 1)
);
GO
-- وثيقة ضمن الحزمة بأسبقية (FR-FAC-004، BR-FAC-008، V-FAC-03)؛ نوعها من doc.Document.DocumentTypeId
CREATE TABLE [fac].[FacilityDocument] (
    [TenantId] INT NOT NULL,
    [FacilityDocumentId] BIGINT IDENTITY(1,1) NOT NULL,
    [FacilityId] BIGINT NOT NULL,
    [DocumentId] BIGINT NOT NULL,
    [DocumentDate] DATE NULL,
    [DocumentDateHijri] NVARCHAR(20) NULL,
    [Language] VARCHAR(10) NOT NULL,
    [PrecedenceRank] INT NOT NULL,
    [AmendsFacilityDocumentId] BIGINT NULL,
    [PageCount] INT NULL,
    [IsSignedCopy] BIT NOT NULL CONSTRAINT [DF_FacilityDocument_IsSignedCopy] DEFAULT 0,
    [IsScanned] BIT NOT NULL CONSTRAINT [DF_FacilityDocument_IsScanned] DEFAULT 0,
    [FromRevision] INT NOT NULL CONSTRAINT [DF_FacilityDocument_FromRevision] DEFAULT 1,
    [ToRevision] INT NULL,
    [SupersedesId] BIGINT NULL,
    [CreatedAt] DATETIME2(3) NOT NULL CONSTRAINT [DF_FacilityDocument_CreatedAt] DEFAULT SYSUTCDATETIME(),
    [CreatedBy] BIGINT NULL,
    [UpdatedAt] DATETIME2(3) NULL,
    [UpdatedBy] BIGINT NULL,
    [RowVersion] ROWVERSION NOT NULL,
    CONSTRAINT [PK_FacilityDocument] PRIMARY KEY CLUSTERED ([FacilityDocumentId]),
    CONSTRAINT [UQ_FacilityDocument_Tenant] UNIQUE ([TenantId], [FacilityDocumentId]),
    CONSTRAINT [UQ_FacilityDocument_Scope_FacilityId] UNIQUE ([TenantId], [FacilityId], [FacilityDocumentId]),
    CONSTRAINT [CK_FacilityDocument_1] CHECK (PrecedenceRank >= 1),
    CONSTRAINT [CK_FacilityDocument_2] CHECK (PageCount IS NULL OR PageCount > 0),
    CONSTRAINT [CK_FacilityDocument_3] CHECK (AmendsFacilityDocumentId IS NULL OR AmendsFacilityDocumentId <> FacilityDocumentId),
    CONSTRAINT [CK_FacilityDocument_4] CHECK (ToRevision IS NULL OR ToRevision >= FromRevision),
    CONSTRAINT [CK_FacilityDocument_Language] CHECK ([Language] IS NULL OR [Language] IN ('AR', 'EN', 'BILINGUAL'))
);
GO
-- مقرض وحصته (FR-FAC-003، BR-FAC-007، V-FAC-02)؛ مجموع الحصص 100 ووكيل واحد يتحقق منهما التطبيق
CREATE TABLE [fac].[FacilityLender] (
    [TenantId] INT NOT NULL,
    [FacilityLenderId] BIGINT IDENTITY(1,1) NOT NULL,
    [FacilityId] BIGINT NOT NULL,
    [InstitutionId] BIGINT NOT NULL,
    [Roles] VARCHAR(40) NOT NULL,
    [SharePct] DECIMAL(9,6) NOT NULL,
    [ContactId] BIGINT NULL,
    [FromRevision] INT NOT NULL CONSTRAINT [DF_FacilityLender_FromRevision] DEFAULT 1,
    [ToRevision] INT NULL,
    [SupersedesId] BIGINT NULL,
    [CreatedAt] DATETIME2(3) NOT NULL CONSTRAINT [DF_FacilityLender_CreatedAt] DEFAULT SYSUTCDATETIME(),
    [CreatedBy] BIGINT NULL,
    [UpdatedAt] DATETIME2(3) NULL,
    [UpdatedBy] BIGINT NULL,
    [RowVersion] ROWVERSION NOT NULL,
    CONSTRAINT [PK_FacilityLender] PRIMARY KEY CLUSTERED ([FacilityLenderId]),
    CONSTRAINT [UQ_FacilityLender_Tenant] UNIQUE ([TenantId], [FacilityLenderId]),
    CONSTRAINT [CK_FacilityLender_1] CHECK (SharePct > 0 AND SharePct <= 100),
    CONSTRAINT [CK_FacilityLender_2] CHECK (Roles <> ''),
    CONSTRAINT [CK_FacilityLender_3] CHECK (Roles NOT LIKE '%SOLE%' OR SharePct = 100),
    CONSTRAINT [CK_FacilityLender_4] CHECK (ToRevision IS NULL OR ToRevision >= FromRevision)
);
GO
-- لقطة الرصيد المعترف به (FR-FAC-009، BR-FAC-017)؛ PctOfLimit مشتق لا يُخزَّن
CREATE TABLE [fac].[OutstandingSnapshot] (
    [TenantId] INT NOT NULL,
    [OutstandingSnapshotId] BIGINT IDENTITY(1,1) NOT NULL,
    [FacilityId] BIGINT NOT NULL,
    [LimitId] BIGINT NULL,
    [ProductId] INT NULL,
    [AsOfDate] DATE NOT NULL,
    [AcknowledgedAmount] DECIMAL(19,4) NOT NULL,
    [CurrencyId] INT NOT NULL,
    [SourceKind] VARCHAR(23) NOT NULL,
    [StatedPct] DECIMAL(9,6) NULL,
    [SourceDocumentId] BIGINT NULL,
    [SourcePage] VARCHAR(40) NULL,
    [ReadFromScan] BIT NOT NULL CONSTRAINT [DF_OutstandingSnapshot_ReadFromScan] DEFAULT 0,
    [OriginalText] NVARCHAR(2000) NULL,
    [NoSourceReason] NVARCHAR(300) NULL,
    [Confidence] VARCHAR(26) NOT NULL CONSTRAINT [DF_OutstandingSnapshot_Confidence] DEFAULT 'ENTERED_NO_DOCUMENT',
    [VerifiedBy] BIGINT NULL,
    [VerifiedOn] DATETIME2(3) NULL,
    [ConflictId] BIGINT NULL,
    [CreatedAt] DATETIME2(3) NOT NULL CONSTRAINT [DF_OutstandingSnapshot_CreatedAt] DEFAULT SYSUTCDATETIME(),
    [CreatedBy] BIGINT NULL,
    [UpdatedAt] DATETIME2(3) NULL,
    [UpdatedBy] BIGINT NULL,
    [RowVersion] ROWVERSION NOT NULL,
    CONSTRAINT [PK_OutstandingSnapshot] PRIMARY KEY CLUSTERED ([OutstandingSnapshotId]),
    CONSTRAINT [UQ_OutstandingSnapshot_Tenant] UNIQUE ([TenantId], [OutstandingSnapshotId]),
    CONSTRAINT [UQ_OutstandingSnapshot_FacilityId_LimitId_ProductId_AsOfDate_SourceKind] UNIQUE ([TenantId], [FacilityId], [LimitId], [ProductId], [AsOfDate], [SourceKind]),
    CONSTRAINT [CK_OutstandingSnapshot_1] CHECK (AcknowledgedAmount >= 0),
    CONSTRAINT [CK_OutstandingSnapshot_2] CHECK (StatedPct IS NULL OR StatedPct >= 0),
    CONSTRAINT [CK_OutstandingSnapshot_3] CHECK (SourceDocumentId IS NOT NULL AND SourcePage IS NOT NULL OR (SourceDocumentId IS NULL AND Confidence = 'ENTERED_NO_DOCUMENT')),
    CONSTRAINT [CK_OutstandingSnapshot_4] CHECK (Confidence <> 'CONFIRMED_AGAINST_ORIGINAL' OR (VerifiedBy IS NOT NULL AND VerifiedOn IS NOT NULL)),
    CONSTRAINT [CK_OutstandingSnapshot_SourceKind] CHECK ([SourceKind] IS NULL OR [SourceKind] IN ('RENEWAL_ACKNOWLEDGEMENT', 'BANK_STATEMENT', 'INTERNAL')),
    CONSTRAINT [CK_OutstandingSnapshot_Confidence] CHECK ([Confidence] IS NULL OR [Confidence] IN ('CONFIRMED_AGAINST_ORIGINAL', 'READ_FROM_SCAN_UNVERIFIED', 'ENTERED_NO_DOCUMENT'))
);
GO
-- عقدة شجرة الحدود (FR-FAC-010/011، BR-FAC-009/010، V-FAC-04..07)
CREATE TABLE [fac].[Limit] (
    [TenantId] INT NOT NULL,
    [LimitId] BIGINT IDENTITY(1,1) NOT NULL,
    [FacilityId] BIGINT NOT NULL,
    [ParentLimitId] BIGINT NULL,
    [LimitTypeId] INT NOT NULL,
    [Code] VARCHAR(40) NOT NULL,
    [NameAr] NVARCHAR(200) NOT NULL,
    [NameEn] NVARCHAR(200) NULL,
    [BankStructureNo] NVARCHAR(80) NULL,
    [AmountBasis] VARCHAR(13) NOT NULL CONSTRAINT [DF_Limit_AmountBasis] DEFAULT 'ABSOLUTE',
    [Amount] DECIMAL(19,4) NULL,
    [PctOfParent] DECIMAL(9,6) NULL,
    [EffectiveAmount] DECIMAL(19,4) NULL,
    [DistributionMode] VARCHAR(13) NOT NULL CONSTRAINT [DF_Limit_DistributionMode] DEFAULT 'SHARED_CAP',
    [IsRevolving] BIT NOT NULL,
    [IsCommitted] BIT NULL,
    [StartDate] DATE NULL,
    [EndDate] DATE NULL,
    [DueDate] DATE NULL,
    [PricingMode] VARCHAR(10) NOT NULL CONSTRAINT [DF_Limit_PricingMode] DEFAULT 'INHERIT',
    [CompanyAllocationMode] VARCHAR(10) NOT NULL CONSTRAINT [DF_Limit_CompanyAllocationMode] DEFAULT 'NONE',
    [FromRevision] INT NOT NULL CONSTRAINT [DF_Limit_FromRevision] DEFAULT 1,
    [ToRevision] INT NULL,
    [SupersedesId] BIGINT NULL,
    [SourceDocumentId] BIGINT NULL,
    [SourcePage] VARCHAR(40) NULL,
    [ReadFromScan] BIT NOT NULL CONSTRAINT [DF_Limit_ReadFromScan] DEFAULT 0,
    [OriginalText] NVARCHAR(2000) NULL,
    [NoSourceReason] NVARCHAR(300) NULL,
    [Confidence] VARCHAR(26) NOT NULL CONSTRAINT [DF_Limit_Confidence] DEFAULT 'ENTERED_NO_DOCUMENT',
    [VerifiedBy] BIGINT NULL,
    [VerifiedOn] DATETIME2(3) NULL,
    [ConflictId] BIGINT NULL,
    [CreatedAt] DATETIME2(3) NOT NULL CONSTRAINT [DF_Limit_CreatedAt] DEFAULT SYSUTCDATETIME(),
    [CreatedBy] BIGINT NULL,
    [UpdatedAt] DATETIME2(3) NULL,
    [UpdatedBy] BIGINT NULL,
    [RowVersion] ROWVERSION NOT NULL,
    CONSTRAINT [PK_Limit] PRIMARY KEY CLUSTERED ([LimitId]),
    CONSTRAINT [UQ_Limit_Tenant] UNIQUE ([TenantId], [LimitId]),
    CONSTRAINT [UQ_Limit_Scope_FacilityId] UNIQUE ([TenantId], [FacilityId], [LimitId]),
    CONSTRAINT [CK_Limit_1] CHECK ((AmountBasis = 'ABSOLUTE' AND Amount IS NOT NULL AND PctOfParent IS NULL) OR (AmountBasis = 'PCT_OF_PARENT' AND PctOfParent IS NOT NULL AND Amount IS NULL)),
    CONSTRAINT [CK_Limit_2] CHECK (Amount IS NULL OR Amount >= 0),
    CONSTRAINT [CK_Limit_3] CHECK (PctOfParent IS NULL OR (PctOfParent > 0 AND PctOfParent <= 100)),
    CONSTRAINT [CK_Limit_4] CHECK (EffectiveAmount IS NULL OR EffectiveAmount >= 0),
    CONSTRAINT [CK_Limit_5] CHECK (ParentLimitId IS NULL OR ParentLimitId <> LimitId),
    CONSTRAINT [CK_Limit_6] CHECK (StartDate IS NULL OR EndDate IS NULL OR EndDate >= StartDate),
    CONSTRAINT [CK_Limit_7] CHECK (ToRevision IS NULL OR ToRevision >= FromRevision),
    CONSTRAINT [CK_Limit_8] CHECK (SourceDocumentId IS NOT NULL AND SourcePage IS NOT NULL OR (SourceDocumentId IS NULL AND Confidence = 'ENTERED_NO_DOCUMENT')),
    CONSTRAINT [CK_Limit_9] CHECK (Confidence <> 'CONFIRMED_AGAINST_ORIGINAL' OR (VerifiedBy IS NOT NULL AND VerifiedOn IS NOT NULL)),
    CONSTRAINT [CK_Limit_AmountBasis] CHECK ([AmountBasis] IS NULL OR [AmountBasis] IN ('ABSOLUTE', 'PCT_OF_PARENT')),
    CONSTRAINT [CK_Limit_DistributionMode] CHECK ([DistributionMode] IS NULL OR [DistributionMode] IN ('SHARED_CAP', 'PARTITION', 'OUTSIDE_TOTAL')),
    CONSTRAINT [CK_Limit_PricingMode] CHECK ([PricingMode] IS NULL OR [PricingMode] IN ('INHERIT', 'OWN')),
    CONSTRAINT [CK_Limit_CompanyAllocationMode] CHECK ([CompanyAllocationMode] IS NULL OR [CompanyAllocationMode] IN ('NONE', 'PARTITION', 'SHARED_CAP')),
    CONSTRAINT [CK_Limit_Confidence] CHECK ([Confidence] IS NULL OR [Confidence] IN ('CONFIRMED_AGAINST_ORIGINAL', 'READ_FROM_SCAN_UNVERIFIED', 'ENTERED_NO_DOCUMENT'))
);
GO
-- خط منتج داخل حد: سقف اختياري SHARED_CAP دائمًا (FR-FAC-012، V-FAC-08)
CREATE TABLE [fac].[LimitProductLine] (
    [TenantId] INT NOT NULL,
    [LimitProductLineId] BIGINT IDENTITY(1,1) NOT NULL,
    [FacilityId] BIGINT NOT NULL,
    [LimitId] BIGINT NOT NULL,
    [ProductId] INT NOT NULL,
    [BankProductCode] NVARCHAR(60) NULL,
    [AmountBasis] VARCHAR(13) NULL,
    [Amount] DECIMAL(19,4) NULL,
    [PctOfParent] DECIMAL(9,6) NULL,
    [IsRevolving] BIT NULL,
    [DueDate] DATE NULL,
    [IsActive] BIT NOT NULL CONSTRAINT [DF_LimitProductLine_IsActive] DEFAULT 1,
    [FromRevision] INT NOT NULL CONSTRAINT [DF_LimitProductLine_FromRevision] DEFAULT 1,
    [ToRevision] INT NULL,
    [SupersedesId] BIGINT NULL,
    [SourceDocumentId] BIGINT NULL,
    [SourcePage] VARCHAR(40) NULL,
    [ReadFromScan] BIT NOT NULL CONSTRAINT [DF_LimitProductLine_ReadFromScan] DEFAULT 0,
    [OriginalText] NVARCHAR(2000) NULL,
    [NoSourceReason] NVARCHAR(300) NULL,
    [Confidence] VARCHAR(26) NOT NULL CONSTRAINT [DF_LimitProductLine_Confidence] DEFAULT 'ENTERED_NO_DOCUMENT',
    [VerifiedBy] BIGINT NULL,
    [VerifiedOn] DATETIME2(3) NULL,
    [ConflictId] BIGINT NULL,
    [CreatedAt] DATETIME2(3) NOT NULL CONSTRAINT [DF_LimitProductLine_CreatedAt] DEFAULT SYSUTCDATETIME(),
    [CreatedBy] BIGINT NULL,
    [UpdatedAt] DATETIME2(3) NULL,
    [UpdatedBy] BIGINT NULL,
    [RowVersion] ROWVERSION NOT NULL,
    CONSTRAINT [PK_LimitProductLine] PRIMARY KEY CLUSTERED ([LimitProductLineId]),
    CONSTRAINT [UQ_LimitProductLine_Tenant] UNIQUE ([TenantId], [LimitProductLineId]),
    CONSTRAINT [UQ_LimitProductLine_Scope_FacilityId] UNIQUE ([TenantId], [FacilityId], [LimitProductLineId]),
    CONSTRAINT [UQ_LimitProductLine_Scope_FacilityId_LimitId] UNIQUE ([TenantId], [FacilityId], [LimitId], [LimitProductLineId]),
    CONSTRAINT [CK_LimitProductLine_1] CHECK ((AmountBasis IS NULL AND Amount IS NULL AND PctOfParent IS NULL) OR (AmountBasis IS NOT NULL AND ((AmountBasis = 'ABSOLUTE' AND Amount IS NOT NULL AND PctOfParent IS NULL) OR (AmountBasis = 'PCT_OF_PARENT' AND PctOfParent IS NOT NULL AND Amount IS NULL)))),
    CONSTRAINT [CK_LimitProductLine_2] CHECK (Amount IS NULL OR Amount >= 0),
    CONSTRAINT [CK_LimitProductLine_3] CHECK (PctOfParent IS NULL OR (PctOfParent > 0 AND PctOfParent <= 100)),
    CONSTRAINT [CK_LimitProductLine_4] CHECK (ToRevision IS NULL OR ToRevision >= FromRevision),
    CONSTRAINT [CK_LimitProductLine_5] CHECK (SourceDocumentId IS NOT NULL AND SourcePage IS NOT NULL OR (SourceDocumentId IS NULL AND Confidence = 'ENTERED_NO_DOCUMENT')),
    CONSTRAINT [CK_LimitProductLine_6] CHECK (Confidence <> 'CONFIRMED_AGAINST_ORIGINAL' OR (VerifiedBy IS NOT NULL AND VerifiedOn IS NOT NULL)),
    CONSTRAINT [CK_LimitProductLine_AmountBasis] CHECK ([AmountBasis] IS NULL OR [AmountBasis] IN ('ABSOLUTE', 'PCT_OF_PARENT')),
    CONSTRAINT [CK_LimitProductLine_Confidence] CHECK ([Confidence] IS NULL OR [Confidence] IN ('CONFIRMED_AGAINST_ORIGINAL', 'READ_FROM_SCAN_UNVERIFIED', 'ENTERED_NO_DOCUMENT'))
);
GO
-- قيد شركة على حد: مسموح/مستثنى/تخصيص (FR-FAC-013، BR-FAC-012، V-FAC-09)
CREATE TABLE [fac].[LimitCompanyRule] (
    [TenantId] INT NOT NULL,
    [LimitCompanyRuleId] BIGINT IDENTITY(1,1) NOT NULL,
    [FacilityId] BIGINT NOT NULL,
    [LimitId] BIGINT NOT NULL,
    [CompanyId] BIGINT NOT NULL,
    [RuleKind] VARCHAR(10) NOT NULL,
    [AllocationAmount] DECIMAL(19,4) NULL,
    [AllocationPct] DECIMAL(9,6) NULL,
    [Reason] NVARCHAR(500) NULL,
    [ValidFrom] DATE NOT NULL,
    [ValidTo] DATE NULL,
    [FromRevision] INT NOT NULL CONSTRAINT [DF_LimitCompanyRule_FromRevision] DEFAULT 1,
    [ToRevision] INT NULL,
    [SupersedesId] BIGINT NULL,
    [SourceDocumentId] BIGINT NULL,
    [SourcePage] VARCHAR(40) NULL,
    [ReadFromScan] BIT NOT NULL CONSTRAINT [DF_LimitCompanyRule_ReadFromScan] DEFAULT 0,
    [OriginalText] NVARCHAR(2000) NULL,
    [NoSourceReason] NVARCHAR(300) NULL,
    [Confidence] VARCHAR(26) NOT NULL CONSTRAINT [DF_LimitCompanyRule_Confidence] DEFAULT 'ENTERED_NO_DOCUMENT',
    [VerifiedBy] BIGINT NULL,
    [VerifiedOn] DATETIME2(3) NULL,
    [ConflictId] BIGINT NULL,
    [CreatedAt] DATETIME2(3) NOT NULL CONSTRAINT [DF_LimitCompanyRule_CreatedAt] DEFAULT SYSUTCDATETIME(),
    [CreatedBy] BIGINT NULL,
    [UpdatedAt] DATETIME2(3) NULL,
    [UpdatedBy] BIGINT NULL,
    [RowVersion] ROWVERSION NOT NULL,
    CONSTRAINT [PK_LimitCompanyRule] PRIMARY KEY CLUSTERED ([LimitCompanyRuleId]),
    CONSTRAINT [UQ_LimitCompanyRule_Tenant] UNIQUE ([TenantId], [LimitCompanyRuleId]),
    CONSTRAINT [CK_LimitCompanyRule_1] CHECK (RuleKind <> 'ALLOCATION' OR (AllocationAmount IS NOT NULL AND AllocationPct IS NULL) OR (AllocationAmount IS NULL AND AllocationPct IS NOT NULL)),
    CONSTRAINT [CK_LimitCompanyRule_2] CHECK (RuleKind = 'ALLOCATION' OR (AllocationAmount IS NULL AND AllocationPct IS NULL)),
    CONSTRAINT [CK_LimitCompanyRule_3] CHECK (AllocationAmount IS NULL OR AllocationAmount > 0),
    CONSTRAINT [CK_LimitCompanyRule_4] CHECK (AllocationPct IS NULL OR (AllocationPct > 0 AND AllocationPct <= 100)),
    CONSTRAINT [CK_LimitCompanyRule_5] CHECK (ValidTo IS NULL OR ValidTo >= ValidFrom),
    CONSTRAINT [CK_LimitCompanyRule_6] CHECK (ToRevision IS NULL OR ToRevision >= FromRevision),
    CONSTRAINT [CK_LimitCompanyRule_7] CHECK (SourceDocumentId IS NOT NULL AND SourcePage IS NOT NULL OR (SourceDocumentId IS NULL AND Confidence = 'ENTERED_NO_DOCUMENT')),
    CONSTRAINT [CK_LimitCompanyRule_8] CHECK (Confidence <> 'CONFIRMED_AGAINST_ORIGINAL' OR (VerifiedBy IS NOT NULL AND VerifiedOn IS NOT NULL)),
    CONSTRAINT [CK_LimitCompanyRule_RuleKind] CHECK ([RuleKind] IS NULL OR [RuleKind] IN ('ALLOWED', 'EXCLUDED', 'ALLOCATION')),
    CONSTRAINT [CK_LimitCompanyRule_Confidence] CHECK ([Confidence] IS NULL OR [Confidence] IN ('CONFIRMED_AGAINST_ORIGINAL', 'READ_FROM_SCAN_UNVERIFIED', 'ENTERED_NO_DOCUMENT'))
);
GO
-- شروط العملية لخط المنتج بتواريخ سريان؛ الفارغ = «غير محدد» لا صفر (FR-FAC-014، BR-FAC-016)
CREATE TABLE [fac].[ProductLineTerm] (
    [TenantId] INT NOT NULL,
    [ProductLineTermId] BIGINT IDENTITY(1,1) NOT NULL,
    [FacilityId] BIGINT NOT NULL,
    [LimitProductLineId] BIGINT NOT NULL,
    [MaxTotalTenorDays] INT NULL,
    [MaxDeferralDays] INT NULL,
    [MaxPostDeferralFinancingDays] INT NULL,
    [LcValidityDays] INT NULL,
    [CashCoverPct] DECIMAL(9,6) NULL,
    [FinancingRatioPct] DECIMAL(9,6) NULL,
    [AdvanceNoticeDays] INT NULL,
    [AdvanceNoticeUnit] VARCHAR(10) NOT NULL CONSTRAINT [DF_ProductLineTerm_AdvanceNoticeUnit] DEFAULT 'BUSINESS',
    [CheckMode] VARCHAR(10) NOT NULL CONSTRAINT [DF_ProductLineTerm_CheckMode] DEFAULT 'WARN',
    [EffectiveFrom] DATE NOT NULL,
    [EffectiveTo] DATE NULL,
    [FromRevision] INT NOT NULL CONSTRAINT [DF_ProductLineTerm_FromRevision] DEFAULT 1,
    [ToRevision] INT NULL,
    [SupersedesId] BIGINT NULL,
    [SourceDocumentId] BIGINT NULL,
    [SourcePage] VARCHAR(40) NULL,
    [ReadFromScan] BIT NOT NULL CONSTRAINT [DF_ProductLineTerm_ReadFromScan] DEFAULT 0,
    [OriginalText] NVARCHAR(2000) NULL,
    [NoSourceReason] NVARCHAR(300) NULL,
    [Confidence] VARCHAR(26) NOT NULL CONSTRAINT [DF_ProductLineTerm_Confidence] DEFAULT 'ENTERED_NO_DOCUMENT',
    [VerifiedBy] BIGINT NULL,
    [VerifiedOn] DATETIME2(3) NULL,
    [ConflictId] BIGINT NULL,
    [CreatedAt] DATETIME2(3) NOT NULL CONSTRAINT [DF_ProductLineTerm_CreatedAt] DEFAULT SYSUTCDATETIME(),
    [CreatedBy] BIGINT NULL,
    [UpdatedAt] DATETIME2(3) NULL,
    [UpdatedBy] BIGINT NULL,
    [RowVersion] ROWVERSION NOT NULL,
    CONSTRAINT [PK_ProductLineTerm] PRIMARY KEY CLUSTERED ([ProductLineTermId]),
    CONSTRAINT [UQ_ProductLineTerm_Tenant] UNIQUE ([TenantId], [ProductLineTermId]),
    CONSTRAINT [CK_ProductLineTerm_1] CHECK (EffectiveTo IS NULL OR EffectiveTo >= EffectiveFrom),
    CONSTRAINT [CK_ProductLineTerm_2] CHECK (MaxTotalTenorDays IS NULL OR MaxTotalTenorDays >= 0),
    CONSTRAINT [CK_ProductLineTerm_3] CHECK (MaxDeferralDays IS NULL OR MaxDeferralDays >= 0),
    CONSTRAINT [CK_ProductLineTerm_4] CHECK (MaxPostDeferralFinancingDays IS NULL OR MaxPostDeferralFinancingDays >= 0),
    CONSTRAINT [CK_ProductLineTerm_5] CHECK (LcValidityDays IS NULL OR LcValidityDays >= 0),
    CONSTRAINT [CK_ProductLineTerm_6] CHECK (AdvanceNoticeDays IS NULL OR AdvanceNoticeDays >= 0),
    CONSTRAINT [CK_ProductLineTerm_7] CHECK (CashCoverPct IS NULL OR (CashCoverPct >= 0 AND CashCoverPct <= 100)),
    CONSTRAINT [CK_ProductLineTerm_8] CHECK (FinancingRatioPct IS NULL OR (FinancingRatioPct >= 0 AND FinancingRatioPct <= 100)),
    CONSTRAINT [CK_ProductLineTerm_9] CHECK (ToRevision IS NULL OR ToRevision >= FromRevision),
    CONSTRAINT [CK_ProductLineTerm_10] CHECK (SourceDocumentId IS NOT NULL AND SourcePage IS NOT NULL OR (SourceDocumentId IS NULL AND Confidence = 'ENTERED_NO_DOCUMENT')),
    CONSTRAINT [CK_ProductLineTerm_11] CHECK (Confidence <> 'CONFIRMED_AGAINST_ORIGINAL' OR (VerifiedBy IS NOT NULL AND VerifiedOn IS NOT NULL)),
    CONSTRAINT [CK_ProductLineTerm_AdvanceNoticeUnit] CHECK ([AdvanceNoticeUnit] IS NULL OR [AdvanceNoticeUnit] IN ('BUSINESS', 'CALENDAR')),
    CONSTRAINT [CK_ProductLineTerm_CheckMode] CHECK ([CheckMode] IS NULL OR [CheckMode] IN ('OFF', 'WARN', 'BLOCK')),
    CONSTRAINT [CK_ProductLineTerm_Confidence] CHECK ([Confidence] IS NULL OR [Confidence] IN ('CONFIRMED_AGAINST_ORIGINAL', 'READ_FROM_SCAN_UNVERIFIED', 'ENTERED_NO_DOCUMENT'))
);
GO
-- بند استخدام فعّال: يدوي أو مرتبط باعتماد مستندي؛ لا حذف (FR-FAC-016/030، BR-FAC-013/020)
CREATE TABLE [fac].[Utilization] (
    [TenantId] INT NOT NULL,
    [UtilizationId] BIGINT IDENTITY(1,1) NOT NULL,
    [FacilityId] BIGINT NOT NULL,
    [LimitId] BIGINT NOT NULL,
    [LimitProductLineId] BIGINT NULL,
    [CompanyId] BIGINT NOT NULL,
    [Reference] NVARCHAR(100) NOT NULL,
    [Description] NVARCHAR(300) NULL,
    [Amount] DECIMAL(19,4) NOT NULL,
    [CurrencyId] INT NOT NULL,
    [RateToFacilityCcy] DECIMAL(19,8) NULL,
    [StartDate] DATE NOT NULL,
    [MaturityDate] DATE NULL,
    [SourceType] VARCHAR(13) NOT NULL CONSTRAINT [DF_Utilization_SourceType] DEFAULT 'MANUAL',
    [SourceRefId] BIGINT NULL,
    [Status] VARCHAR(10) NOT NULL CONSTRAINT [DF_Utilization_Status] DEFAULT 'ACTIVE',
    [ReleasedOn] DATE NULL,
    [ReleaseReason] NVARCHAR(500) NULL,
    [PublicId] UNIQUEIDENTIFIER NOT NULL CONSTRAINT [DF_Utilization_PublicId] DEFAULT NEWSEQUENTIALID(),
    [CreatedAt] DATETIME2(3) NOT NULL CONSTRAINT [DF_Utilization_CreatedAt] DEFAULT SYSUTCDATETIME(),
    [CreatedBy] BIGINT NULL,
    [UpdatedAt] DATETIME2(3) NULL,
    [UpdatedBy] BIGINT NULL,
    [RowVersion] ROWVERSION NOT NULL,
    CONSTRAINT [PK_Utilization] PRIMARY KEY CLUSTERED ([UtilizationId]),
    CONSTRAINT [UQ_Utilization_Tenant] UNIQUE ([TenantId], [UtilizationId]),
    CONSTRAINT [UQ_Utilization_Scope_FacilityId] UNIQUE ([TenantId], [FacilityId], [UtilizationId]),
    CONSTRAINT [UQ_Utilization_PublicId] UNIQUE ([PublicId]),
    CONSTRAINT [CK_Utilization_1] CHECK (Amount >= 0),
    CONSTRAINT [CK_Utilization_2] CHECK (Status = 'RELEASED' OR Amount > 0),
    CONSTRAINT [CK_Utilization_3] CHECK (RateToFacilityCcy IS NULL OR RateToFacilityCcy > 0),
    CONSTRAINT [CK_Utilization_4] CHECK (MaturityDate IS NULL OR MaturityDate >= StartDate),
    CONSTRAINT [CK_Utilization_5] CHECK (Status <> 'RELEASED' OR (ReleasedOn IS NOT NULL AND ReleaseReason IS NOT NULL)),
    CONSTRAINT [CK_Utilization_6] CHECK (Status = 'RELEASED' OR (ReleasedOn IS NULL AND ReleaseReason IS NULL)),
    CONSTRAINT [CK_Utilization_SourceType] CHECK ([SourceType] IS NULL OR [SourceType] IN ('MANUAL', 'LC', 'OTHER_REQUEST')),
    CONSTRAINT [CK_Utilization_Status] CHECK ([Status] IS NULL OR [Status] IN ('ACTIVE', 'RELEASED'))
);
GO
-- حجز مبلغ لطلب = ExposureAmount (FR-FAC-017/018/020، BR-FAC-015)
CREATE TABLE [fac].[LimitReservation] (
    [TenantId] INT NOT NULL,
    [LimitReservationId] BIGINT IDENTITY(1,1) NOT NULL,
    [FacilityId] BIGINT NOT NULL,
    [LimitId] BIGINT NOT NULL,
    [LimitProductLineId] BIGINT NULL,
    [CompanyId] BIGINT NOT NULL,
    [RequestId] BIGINT NOT NULL,
    [Amount] DECIMAL(19,4) NOT NULL,
    [CurrencyId] INT NOT NULL,
    [RateToFacilityCcy] DECIMAL(19,8) NULL,
    [Status] VARCHAR(10) NOT NULL CONSTRAINT [DF_LimitReservation_Status] DEFAULT 'ACTIVE',
    [ExpiresOn] DATE NULL,
    [ConvertedUtilizationId] BIGINT NULL,
    [ReleasedOn] DATE NULL,
    [ReleaseReason] VARCHAR(10) NULL,
    [OverLimit] BIT NOT NULL CONSTRAINT [DF_LimitReservation_OverLimit] DEFAULT 0,
    [OverrideReason] NVARCHAR(500) NULL,
    [AcknowledgedWarnings] NVARCHAR(MAX) NULL,
    [IdempotencyKey] VARCHAR(100) NOT NULL,
    [CreatedAt] DATETIME2(3) NOT NULL CONSTRAINT [DF_LimitReservation_CreatedAt] DEFAULT SYSUTCDATETIME(),
    [CreatedBy] BIGINT NULL,
    [UpdatedAt] DATETIME2(3) NULL,
    [UpdatedBy] BIGINT NULL,
    [RowVersion] ROWVERSION NOT NULL,
    CONSTRAINT [PK_LimitReservation] PRIMARY KEY CLUSTERED ([LimitReservationId]),
    CONSTRAINT [UQ_LimitReservation_Tenant] UNIQUE ([TenantId], [LimitReservationId]),
    CONSTRAINT [UQ_LimitReservation_Scope_FacilityId] UNIQUE ([TenantId], [FacilityId], [LimitReservationId]),
    CONSTRAINT [UQ_LimitReservation_IdempotencyKey] UNIQUE ([TenantId], [IdempotencyKey]),
    CONSTRAINT [CK_LimitReservation_1] CHECK (Amount > 0),
    CONSTRAINT [CK_LimitReservation_2] CHECK (RateToFacilityCcy IS NULL OR RateToFacilityCcy > 0),
    CONSTRAINT [CK_LimitReservation_3] CHECK (Status <> 'CONVERTED' OR ConvertedUtilizationId IS NOT NULL),
    CONSTRAINT [CK_LimitReservation_4] CHECK (Status = 'CONVERTED' OR ConvertedUtilizationId IS NULL),
    CONSTRAINT [CK_LimitReservation_5] CHECK (Status <> 'RELEASED' OR (ReleasedOn IS NOT NULL AND ReleaseReason IS NOT NULL)),
    CONSTRAINT [CK_LimitReservation_6] CHECK (Status = 'RELEASED' OR (ReleasedOn IS NULL AND ReleaseReason IS NULL)),
    CONSTRAINT [CK_LimitReservation_7] CHECK (OverLimit = 0 OR OverrideReason IS NOT NULL),
    CONSTRAINT [CK_LimitReservation_Status] CHECK ([Status] IS NULL OR [Status] IN ('ACTIVE', 'CONVERTED', 'RELEASED')),
    CONSTRAINT [CK_LimitReservation_ReleaseReason] CHECK ([ReleaseReason] IS NULL OR [ReleaseReason] IN ('REJECTED', 'CANCELLED', 'EXPIRED', 'SUPERSEDED', 'MANUAL')),
    CONSTRAINT [CK_LimitReservation_AcknowledgedWarnings_json] CHECK ([AcknowledgedWarnings] IS NULL OR ISJSON([AcknowledgedWarnings]) = 1)
);
GO
-- سجل حركة على حجز أو استخدام؛ لا تعديل ولا حذف؛ مفتاح عدم التكرار (BR-FAC-015/020)
CREATE TABLE [fac].[LimitMovement] (
    [TenantId] INT NOT NULL,
    [LimitMovementId] BIGINT IDENTITY(1,1) NOT NULL,
    [FacilityId] BIGINT NOT NULL,
    [TargetKind] VARCHAR(11) NOT NULL,
    [LimitReservationId] BIGINT NULL,
    [UtilizationId] BIGINT NULL,
    [TargetId] AS (CASE WHEN LimitReservationId IS NOT NULL THEN LimitReservationId ELSE UtilizationId END) PERSISTED,
    [OpKind] VARCHAR(10) NOT NULL,
    [CurrencyId] INT NOT NULL,
    [RequestedDelta] DECIMAL(19,4) NULL,
    [AppliedDelta] DECIMAL(19,4) NULL,
    [AmountBefore] DECIMAL(19,4) NULL,
    [AmountAfter] DECIMAL(19,4) NULL,
    [Reason] NVARCHAR(500) NULL,
    [IdempotencyKey] VARCHAR(100) NOT NULL,
    [ActorUserId] BIGINT NOT NULL,
    [At] DATETIME2(3) NOT NULL CONSTRAINT [DF_LimitMovement_At] DEFAULT SYSUTCDATETIME(),
    [CreatedAt] DATETIME2(3) NOT NULL CONSTRAINT [DF_LimitMovement_CreatedAt] DEFAULT SYSUTCDATETIME(),
    [CreatedBy] BIGINT NULL,
    CONSTRAINT [PK_LimitMovement] PRIMARY KEY CLUSTERED ([LimitMovementId]),
    CONSTRAINT [UQ_LimitMovement_Tenant] UNIQUE ([TenantId], [LimitMovementId]),
    CONSTRAINT [UQ_LimitMovement_IdempotencyKey] UNIQUE ([TenantId], [IdempotencyKey]),
    CONSTRAINT [CK_LimitMovement_1] CHECK ((TargetKind = 'RESERVATION' AND LimitReservationId IS NOT NULL AND UtilizationId IS NULL) OR (TargetKind = 'UTILIZATION' AND UtilizationId IS NOT NULL AND LimitReservationId IS NULL)),
    CONSTRAINT [CK_LimitMovement_2] CHECK (AmountAfter IS NULL OR AmountAfter >= 0),
    CONSTRAINT [CK_LimitMovement_3] CHECK (AppliedDelta IS NULL OR RequestedDelta IS NULL OR ABS(AppliedDelta) <= ABS(RequestedDelta)),
    CONSTRAINT [CK_LimitMovement_4] CHECK (OpKind <> 'ADJUST' OR AmountBefore IS NULL OR AmountAfter IS NULL OR AppliedDelta IS NULL OR AmountAfter = AmountBefore + AppliedDelta),
    CONSTRAINT [CK_LimitMovement_TargetKind] CHECK ([TargetKind] IS NULL OR [TargetKind] IN ('RESERVATION', 'UTILIZATION')),
    CONSTRAINT [CK_LimitMovement_OpKind] CHECK ([OpKind] IS NULL OR [OpKind] IN ('CREATE', 'ADJUST', 'CONVERT', 'RELEASE'))
);
GO
-- تعارض قيمتين لحقل واحد وحسمه (FR-FAC-026، BR-FAC-019، BR-FAC-008)
CREATE TABLE [fac].[ValueConflict] (
    [TenantId] INT NOT NULL,
    [ValueConflictId] BIGINT IDENTITY(1,1) NOT NULL,
    [FacilityId] BIGINT NOT NULL,
    [TargetEntity] VARCHAR(60) NOT NULL,
    [TargetId] BIGINT NOT NULL,
    [FieldName] VARCHAR(80) NOT NULL,
    [CandidateAValue] NVARCHAR(1000) NOT NULL,
    [CandidateASourceDocumentId] BIGINT NULL,
    [CandidateASourcePage] VARCHAR(40) NULL,
    [CandidateAReadFromScan] BIT NOT NULL CONSTRAINT [DF_ValueConflict_CandidateAReadFromScan] DEFAULT 0,
    [CandidateAOriginalText] NVARCHAR(2000) NULL,
    [CandidateAConfidence] VARCHAR(26) NOT NULL CONSTRAINT [DF_ValueConflict_CandidateAConfidence] DEFAULT 'ENTERED_NO_DOCUMENT',
    [CandidateBValue] NVARCHAR(1000) NOT NULL,
    [CandidateBSourceDocumentId] BIGINT NULL,
    [CandidateBSourcePage] VARCHAR(40) NULL,
    [CandidateBReadFromScan] BIT NOT NULL CONSTRAINT [DF_ValueConflict_CandidateBReadFromScan] DEFAULT 0,
    [CandidateBOriginalText] NVARCHAR(2000) NULL,
    [CandidateBConfidence] VARCHAR(26) NOT NULL CONSTRAINT [DF_ValueConflict_CandidateBConfidence] DEFAULT 'ENTERED_NO_DOCUMENT',
    [Status] VARCHAR(10) NOT NULL CONSTRAINT [DF_ValueConflict_Status] DEFAULT 'OPEN',
    [ChosenSide] VARCHAR(10) NULL,
    [ResolvedValue] NVARCHAR(1000) NULL,
    [ResolutionReason] NVARCHAR(1000) NULL,
    [ResolvedBy] BIGINT NULL,
    [ResolvedOn] DATETIME2(3) NULL,
    [CreatedAt] DATETIME2(3) NOT NULL CONSTRAINT [DF_ValueConflict_CreatedAt] DEFAULT SYSUTCDATETIME(),
    [CreatedBy] BIGINT NULL,
    [UpdatedAt] DATETIME2(3) NULL,
    [UpdatedBy] BIGINT NULL,
    [RowVersion] ROWVERSION NOT NULL,
    CONSTRAINT [PK_ValueConflict] PRIMARY KEY CLUSTERED ([ValueConflictId]),
    CONSTRAINT [UQ_ValueConflict_Tenant] UNIQUE ([TenantId], [ValueConflictId]),
    CONSTRAINT [CK_ValueConflict_1] CHECK (Status <> 'RESOLVED' OR (ChosenSide IS NOT NULL AND ResolutionReason IS NOT NULL AND ResolvedBy IS NOT NULL AND ResolvedOn IS NOT NULL)),
    CONSTRAINT [CK_ValueConflict_2] CHECK (Status = 'RESOLVED' OR (ChosenSide IS NULL AND ResolvedBy IS NULL AND ResolvedOn IS NULL)),
    CONSTRAINT [CK_ValueConflict_3] CHECK (ChosenSide IS NULL OR ChosenSide <> 'OTHER' OR ResolvedValue IS NOT NULL),
    CONSTRAINT [CK_ValueConflict_4] CHECK (CandidateASourceDocumentId IS NOT NULL AND CandidateASourcePage IS NOT NULL OR (CandidateASourceDocumentId IS NULL AND CandidateAConfidence = 'ENTERED_NO_DOCUMENT')),
    CONSTRAINT [CK_ValueConflict_5] CHECK (CandidateBSourceDocumentId IS NOT NULL AND CandidateBSourcePage IS NOT NULL OR (CandidateBSourceDocumentId IS NULL AND CandidateBConfidence = 'ENTERED_NO_DOCUMENT')),
    CONSTRAINT [CK_ValueConflict_CandidateAConfidence] CHECK ([CandidateAConfidence] IS NULL OR [CandidateAConfidence] IN ('CONFIRMED_AGAINST_ORIGINAL', 'READ_FROM_SCAN_UNVERIFIED', 'ENTERED_NO_DOCUMENT')),
    CONSTRAINT [CK_ValueConflict_CandidateBConfidence] CHECK ([CandidateBConfidence] IS NULL OR [CandidateBConfidence] IN ('CONFIRMED_AGAINST_ORIGINAL', 'READ_FROM_SCAN_UNVERIFIED', 'ENTERED_NO_DOCUMENT')),
    CONSTRAINT [CK_ValueConflict_Status] CHECK ([Status] IS NULL OR [Status] IN ('OPEN', 'RESOLVED')),
    CONSTRAINT [CK_ValueConflict_ChosenSide] CHECK ([ChosenSide] IS NULL OR [ChosenSide] IN ('A', 'B', 'OTHER'))
);
GO

-- ===== schema prc =====
-- إصدار جدول رسوم لبنك؛ بخاص بتسهيل اختياريًا (FR-PRC-001، BR-PRC-001، V-PRC-01)
CREATE TABLE [prc].[TariffSchedule] (
    [TenantId] INT NOT NULL,
    [TariffScheduleId] BIGINT IDENTITY(1,1) NOT NULL,
    [InstitutionId] BIGINT NOT NULL,
    [FacilityId] BIGINT NULL,
    [NameAr] NVARCHAR(200) NOT NULL,
    [NameEn] NVARCHAR(200) NULL,
    [VersionNo] INT NOT NULL,
    [EffectiveFrom] DATE NOT NULL,
    [EffectiveTo] DATE NULL,
    [Status] VARCHAR(10) NOT NULL CONSTRAINT [DF_TariffSchedule_Status] DEFAULT 'DRAFT',
    [SourceDocumentId] BIGINT NULL,
    [ApprovedBy] BIGINT NULL,
    [ApprovedOn] DATETIME2(3) NULL,
    [PublicId] UNIQUEIDENTIFIER NOT NULL CONSTRAINT [DF_TariffSchedule_PublicId] DEFAULT NEWSEQUENTIALID(),
    [CreatedAt] DATETIME2(3) NOT NULL CONSTRAINT [DF_TariffSchedule_CreatedAt] DEFAULT SYSUTCDATETIME(),
    [CreatedBy] BIGINT NULL,
    [UpdatedAt] DATETIME2(3) NULL,
    [UpdatedBy] BIGINT NULL,
    [RowVersion] ROWVERSION NOT NULL,
    CONSTRAINT [PK_TariffSchedule] PRIMARY KEY CLUSTERED ([TariffScheduleId]),
    CONSTRAINT [UQ_TariffSchedule_Tenant] UNIQUE ([TenantId], [TariffScheduleId]),
    CONSTRAINT [UQ_TariffSchedule_PublicId] UNIQUE ([PublicId]),
    CONSTRAINT [UQ_TariffSchedule_InstitutionId_FacilityId_VersionNo] UNIQUE ([TenantId], [InstitutionId], [FacilityId], [VersionNo]),
    CONSTRAINT [CK_TariffSchedule_1] CHECK (VersionNo >= 1),
    CONSTRAINT [CK_TariffSchedule_2] CHECK (EffectiveTo IS NULL OR EffectiveTo >= EffectiveFrom),
    CONSTRAINT [CK_TariffSchedule_3] CHECK (Status <> 'APPROVED' OR (ApprovedBy IS NOT NULL AND ApprovedOn IS NOT NULL)),
    CONSTRAINT [CK_TariffSchedule_Status] CHECK ([Status] IS NULL OR [Status] IN ('DRAFT', 'APPROVED', 'SUPERSEDED'))
);
GO
-- بند رسم في جدول التعرفة (FR-PRC-002، BR-PRC-002..005)
CREATE TABLE [prc].[TariffItem] (
    [TenantId] INT NOT NULL,
    [TariffItemId] BIGINT IDENTITY(1,1) NOT NULL,
    [ScheduleId] BIGINT NOT NULL,
    [FeeTypeId] INT NOT NULL,
    [ItemCode] VARCHAR(40) NOT NULL,
    [NameAr] NVARCHAR(200) NOT NULL,
    [NameEn] NVARCHAR(200) NULL,
    [ProductId] INT NULL,
    [ChargeKind] VARCHAR(11) NOT NULL,
    [Rate] DECIMAL(9,6) NULL,
    [FixedAmount] DECIMAL(19,4) NULL,
    [PerMillionAmount] DECIMAL(19,4) NULL,
    [PeriodBasis] VARCHAR(18) NOT NULL CONSTRAINT [DF_TariffItem_PeriodBasis] DEFAULT 'FLAT',
    [PeriodDays] INT NULL,
    [MinAmount] DECIMAL(19,4) NULL,
    [MaxAmount] DECIMAL(19,4) NULL,
    [Locality] VARCHAR(12) NOT NULL CONSTRAINT [DF_TariffItem_Locality] DEFAULT 'ANY',
    [TierCalcMode] VARCHAR(10) NULL CONSTRAINT [DF_TariffItem_TierCalcMode] DEFAULT 'BAND',
    [PerMillionMode] VARCHAR(15) NULL CONSTRAINT [DF_TariffItem_PerMillionMode] DEFAULT 'PRORATA',
    [VatTreatment] VARCHAR(10) NOT NULL CONSTRAINT [DF_TariffItem_VatTreatment] DEFAULT 'EXCLUSIVE',
    [CurrencyId] INT NULL,
    [SourceDocumentId] BIGINT NULL,
    [SourcePage] VARCHAR(40) NULL,
    [ReadFromScan] BIT NOT NULL CONSTRAINT [DF_TariffItem_ReadFromScan] DEFAULT 0,
    [OriginalText] NVARCHAR(2000) NULL,
    [NoSourceReason] NVARCHAR(300) NULL,
    [Confidence] VARCHAR(26) NOT NULL CONSTRAINT [DF_TariffItem_Confidence] DEFAULT 'ENTERED_NO_DOCUMENT',
    [VerifiedBy] BIGINT NULL,
    [VerifiedOn] DATETIME2(3) NULL,
    [ConflictId] BIGINT NULL,
    [CreatedAt] DATETIME2(3) NOT NULL CONSTRAINT [DF_TariffItem_CreatedAt] DEFAULT SYSUTCDATETIME(),
    [CreatedBy] BIGINT NULL,
    [UpdatedAt] DATETIME2(3) NULL,
    [UpdatedBy] BIGINT NULL,
    [RowVersion] ROWVERSION NOT NULL,
    CONSTRAINT [PK_TariffItem] PRIMARY KEY CLUSTERED ([TariffItemId]),
    CONSTRAINT [UQ_TariffItem_Tenant] UNIQUE ([TenantId], [TariffItemId]),
    CONSTRAINT [UQ_TariffItem_ScheduleId_ItemCode] UNIQUE ([TenantId], [ScheduleId], [ItemCode]),
    CONSTRAINT [CK_TariffItem_1] CHECK (ChargeKind <> 'PERCENT' OR (Rate IS NOT NULL AND FixedAmount IS NULL AND PerMillionAmount IS NULL)),
    CONSTRAINT [CK_TariffItem_2] CHECK (ChargeKind <> 'FIXED' OR (FixedAmount IS NOT NULL AND Rate IS NULL AND PerMillionAmount IS NULL)),
    CONSTRAINT [CK_TariffItem_3] CHECK (ChargeKind <> 'PER_MILLION' OR (PerMillionAmount IS NOT NULL AND Rate IS NULL AND FixedAmount IS NULL)),
    CONSTRAINT [CK_TariffItem_4] CHECK (ChargeKind <> 'TIERED' OR (Rate IS NULL AND FixedAmount IS NULL AND PerMillionAmount IS NULL)),
    CONSTRAINT [CK_TariffItem_5] CHECK (Rate IS NULL OR (Rate >= 0 AND Rate <= 100)),
    CONSTRAINT [CK_TariffItem_6] CHECK (PeriodBasis <> 'PER_PERIOD_OR_PART' OR PeriodDays IS NOT NULL),
    CONSTRAINT [CK_TariffItem_7] CHECK (PeriodDays IS NULL OR PeriodDays > 0),
    CONSTRAINT [CK_TariffItem_8] CHECK (MinAmount IS NULL OR MinAmount >= 0),
    CONSTRAINT [CK_TariffItem_9] CHECK (MinAmount IS NULL OR MaxAmount IS NULL OR MinAmount <= MaxAmount),
    CONSTRAINT [CK_TariffItem_10] CHECK (SourceDocumentId IS NOT NULL AND SourcePage IS NOT NULL OR (SourceDocumentId IS NULL AND Confidence = 'ENTERED_NO_DOCUMENT')),
    CONSTRAINT [CK_TariffItem_11] CHECK (Confidence <> 'CONFIRMED_AGAINST_ORIGINAL' OR (VerifiedBy IS NOT NULL AND VerifiedOn IS NOT NULL)),
    CONSTRAINT [CK_TariffItem_ChargeKind] CHECK ([ChargeKind] IS NULL OR [ChargeKind] IN ('PERCENT', 'FIXED', 'PER_MILLION', 'TIERED')),
    CONSTRAINT [CK_TariffItem_PeriodBasis] CHECK ([PeriodBasis] IS NULL OR [PeriodBasis] IN ('FLAT', 'PER_ANNUM', 'PER_PERIOD_OR_PART')),
    CONSTRAINT [CK_TariffItem_Locality] CHECK ([Locality] IS NULL OR [Locality] IN ('ANY', 'INSIDE_BANK', 'OUTSIDE_BANK')),
    CONSTRAINT [CK_TariffItem_TierCalcMode] CHECK ([TierCalcMode] IS NULL OR [TierCalcMode] IN ('BAND', 'WHOLE')),
    CONSTRAINT [CK_TariffItem_PerMillionMode] CHECK ([PerMillionMode] IS NULL OR [PerMillionMode] IN ('PRORATA', 'STARTED_MILLION')),
    CONSTRAINT [CK_TariffItem_VatTreatment] CHECK ([VatTreatment] IS NULL OR [VatTreatment] IN ('EXCLUSIVE', 'INCLUSIVE', 'EXEMPT')),
    CONSTRAINT [CK_TariffItem_Confidence] CHECK ([Confidence] IS NULL OR [Confidence] IN ('CONFIRMED_AGAINST_ORIGINAL', 'READ_FROM_SCAN_UNVERIFIED', 'ENTERED_NO_DOCUMENT'))
);
GO
-- شريحة بند تعرفة بالمبلغ و/أو المدة (FR-PRC-003، BR-PRC-002)
CREATE TABLE [prc].[TariffTier] (
    [TenantId] INT NOT NULL,
    [TariffTierId] BIGINT IDENTITY(1,1) NOT NULL,
    [TariffItemId] BIGINT NOT NULL,
    [AmountFrom] DECIMAL(19,4) NULL,
    [AmountTo] DECIMAL(19,4) NULL,
    [PeriodFromDays] INT NULL,
    [PeriodToDays] INT NULL,
    [Rate] DECIMAL(9,6) NULL,
    [FixedAmount] DECIMAL(19,4) NULL,
    [MinAmount] DECIMAL(19,4) NULL,
    [SortOrder] INT NOT NULL,
    [CreatedAt] DATETIME2(3) NOT NULL CONSTRAINT [DF_TariffTier_CreatedAt] DEFAULT SYSUTCDATETIME(),
    [CreatedBy] BIGINT NULL,
    [UpdatedAt] DATETIME2(3) NULL,
    [UpdatedBy] BIGINT NULL,
    [RowVersion] ROWVERSION NOT NULL,
    CONSTRAINT [PK_TariffTier] PRIMARY KEY CLUSTERED ([TariffTierId]),
    CONSTRAINT [UQ_TariffTier_Tenant] UNIQUE ([TenantId], [TariffTierId]),
    CONSTRAINT [UQ_TariffTier_TariffItemId_SortOrder] UNIQUE ([TenantId], [TariffItemId], [SortOrder]),
    CONSTRAINT [UQ_TariffTier_TariffItemId_AmountFrom_PeriodFromDays] UNIQUE ([TenantId], [TariffItemId], [AmountFrom], [PeriodFromDays]),
    CONSTRAINT [CK_TariffTier_1] CHECK (AmountFrom IS NULL OR AmountFrom >= 0),
    CONSTRAINT [CK_TariffTier_2] CHECK (AmountTo IS NULL OR AmountFrom IS NULL OR AmountTo > AmountFrom),
    CONSTRAINT [CK_TariffTier_3] CHECK (PeriodFromDays IS NULL OR PeriodFromDays >= 0),
    CONSTRAINT [CK_TariffTier_4] CHECK (PeriodToDays IS NULL OR PeriodFromDays IS NULL OR PeriodToDays >= PeriodFromDays),
    CONSTRAINT [CK_TariffTier_5] CHECK (Rate IS NOT NULL OR FixedAmount IS NOT NULL),
    CONSTRAINT [CK_TariffTier_6] CHECK (Rate IS NULL OR FixedAmount IS NULL),
    CONSTRAINT [CK_TariffTier_7] CHECK (Rate IS NULL OR (Rate >= 0 AND Rate <= 100)),
    CONSTRAINT [CK_TariffTier_8] CHECK (MinAmount IS NULL OR MinAmount >= 0)
);
GO
-- قاعدة تسعير بنطاق ووراثة وطرق (FR-PRC-006..017، BR-PRC-006..012، V-PRC-02)
CREATE TABLE [prc].[PricingRule] (
    [TenantId] INT NOT NULL,
    [PricingRuleId] BIGINT IDENTITY(1,1) NOT NULL,
    [FacilityId] BIGINT NOT NULL,
    [ScopeLimitId] BIGINT NULL,
    [ScopeLimitProductLineId] BIGINT NULL,
    [ScopeProductId] INT NULL,
    [ScopeCompanyId] BIGINT NULL,
    [ComponentKind] VARCHAR(18) NOT NULL,
    [RateState] VARCHAR(26) NOT NULL CONSTRAINT [DF_PricingRule_RateState] DEFAULT 'SET',
    [FeeTypeId] INT NULL,
    [FinancingTypeId] INT NULL,
    [Method] VARCHAR(17) NOT NULL,
    [TariffItemId] BIGINT NULL,
    [AddOnPct] DECIMAL(9,6) NULL,
    [BaseRateId] INT NULL,
    [MarginPct] DECIMAL(9,6) NULL,
    [BaseFloorPct] DECIMAL(9,6) NULL,
    [RatePct] DECIMAL(9,6) NULL,
    [RateRangeLowPct] DECIMAL(9,6) NULL,
    [RateRangeHighPct] DECIMAL(9,6) NULL,
    [FixedAmount] DECIMAL(19,4) NULL,
    [PerMillionAmount] DECIMAL(19,4) NULL,
    [CurrencyId] INT NULL,
    [PeriodBasis] VARCHAR(18) NULL,
    [PeriodDays] INT NULL,
    [MinFeeAmount] DECIMAL(19,4) NULL,
    [MaxFeeAmount] DECIMAL(19,4) NULL,
    [RateFixing] VARCHAR(18) NULL,
    [RepricingMonths] INT NULL,
    [DayCount] VARCHAR(10) NULL,
    [VatExclusive] BIT NOT NULL CONSTRAINT [DF_PricingRule_VatExclusive] DEFAULT 1,
    [BenchmarkReplacement] VARCHAR(15) NOT NULL CONSTRAINT [DF_PricingRule_BenchmarkReplacement] DEFAULT 'NONE',
    [ReplacementText] NVARCHAR(1000) NULL,
    [BankMayChange] VARCHAR(21) NOT NULL CONSTRAINT [DF_PricingRule_BankMayChange] DEFAULT 'NO',
    [ObjectionDays] INT NULL,
    [ObjectionDaysKind] VARCHAR(10) NULL,
    [TriggerEvent] VARCHAR(35) NULL,
    [EffectiveFrom] DATE NOT NULL,
    [EffectiveTo] DATE NULL,
    [Retroactive] BIT NOT NULL CONSTRAINT [DF_PricingRule_Retroactive] DEFAULT 0,
    [RetroactiveReason] NVARCHAR(500) NULL,
    [FromRevision] INT NOT NULL CONSTRAINT [DF_PricingRule_FromRevision] DEFAULT 1,
    [ToRevision] INT NULL,
    [SupersedesId] BIGINT NULL,
    [SourceDocumentId] BIGINT NULL,
    [SourcePage] VARCHAR(40) NULL,
    [ReadFromScan] BIT NOT NULL CONSTRAINT [DF_PricingRule_ReadFromScan] DEFAULT 0,
    [OriginalText] NVARCHAR(2000) NULL,
    [NoSourceReason] NVARCHAR(300) NULL,
    [Confidence] VARCHAR(26) NOT NULL CONSTRAINT [DF_PricingRule_Confidence] DEFAULT 'ENTERED_NO_DOCUMENT',
    [VerifiedBy] BIGINT NULL,
    [VerifiedOn] DATETIME2(3) NULL,
    [ConflictId] BIGINT NULL,
    [CreatedAt] DATETIME2(3) NOT NULL CONSTRAINT [DF_PricingRule_CreatedAt] DEFAULT SYSUTCDATETIME(),
    [CreatedBy] BIGINT NULL,
    [UpdatedAt] DATETIME2(3) NULL,
    [UpdatedBy] BIGINT NULL,
    [RowVersion] ROWVERSION NOT NULL,
    CONSTRAINT [PK_PricingRule] PRIMARY KEY CLUSTERED ([PricingRuleId]),
    CONSTRAINT [UQ_PricingRule_Tenant] UNIQUE ([TenantId], [PricingRuleId]),
    CONSTRAINT [UQ_PricingRule_Scope_FacilityId] UNIQUE ([TenantId], [FacilityId], [PricingRuleId]),
    CONSTRAINT [CK_PricingRule_1] CHECK (ScopeLimitProductLineId IS NULL OR ScopeLimitId IS NOT NULL),
    CONSTRAINT [CK_PricingRule_2] CHECK (EffectiveTo IS NULL OR EffectiveTo >= EffectiveFrom),
    CONSTRAINT [CK_PricingRule_3] CHECK (ComponentKind <> 'FINANCING_RETURN' OR FeeTypeId IS NULL),
    CONSTRAINT [CK_PricingRule_4] CHECK (ComponentKind = 'FINANCING_RETURN' OR (FeeTypeId IS NOT NULL AND FinancingTypeId IS NULL)),
    CONSTRAINT [CK_PricingRule_5] CHECK (ComponentKind <> 'PENALTY_NON_INCOME' OR TriggerEvent IS NOT NULL),
    CONSTRAINT [CK_PricingRule_6] CHECK (ComponentKind = 'PENALTY_NON_INCOME' OR TriggerEvent IS NULL),
    CONSTRAINT [CK_PricingRule_7] CHECK (RateState <> 'NOT_SPECIFIED_IN_AGREEMENT' OR (AddOnPct IS NULL AND MarginPct IS NULL AND RatePct IS NULL AND RateRangeLowPct IS NULL AND RateRangeHighPct IS NULL AND FixedAmount IS NULL AND PerMillionAmount IS NULL)),
    CONSTRAINT [CK_PricingRule_8] CHECK (RateState <> 'SET' OR Method <> 'TARIFF_AS_IS' OR TariffItemId IS NOT NULL),
    CONSTRAINT [CK_PricingRule_9] CHECK (RateState <> 'SET' OR Method <> 'TARIFF_PLUS_ADDON' OR (TariffItemId IS NOT NULL AND AddOnPct IS NOT NULL)),
    CONSTRAINT [CK_PricingRule_10] CHECK (RateState <> 'SET' OR Method <> 'BASE_PLUS_MARGIN' OR (BaseRateId IS NOT NULL AND MarginPct IS NOT NULL AND RateFixing IS NOT NULL AND DayCount IS NOT NULL)),
    CONSTRAINT [CK_PricingRule_11] CHECK (RateState <> 'SET' OR Method <> 'PERCENT_OF_AMOUNT' OR RatePct IS NOT NULL OR (RateRangeLowPct IS NOT NULL AND RateRangeHighPct IS NOT NULL)),
    CONSTRAINT [CK_PricingRule_12] CHECK (RateState <> 'SET' OR Method <> 'FIXED_AMOUNT' OR FixedAmount IS NOT NULL),
    CONSTRAINT [CK_PricingRule_13] CHECK (RateState <> 'SET' OR Method <> 'PER_MILLION' OR PerMillionAmount IS NOT NULL),
    CONSTRAINT [CK_PricingRule_14] CHECK (Method IN ('TARIFF_AS_IS','TARIFF_PLUS_ADDON') OR TariffItemId IS NULL),
    CONSTRAINT [CK_PricingRule_15] CHECK (Method = 'TARIFF_PLUS_ADDON' OR AddOnPct IS NULL),
    CONSTRAINT [CK_PricingRule_16] CHECK (Method = 'BASE_PLUS_MARGIN' OR (BaseRateId IS NULL AND MarginPct IS NULL AND BaseFloorPct IS NULL AND RateFixing IS NULL AND RepricingMonths IS NULL)),
    CONSTRAINT [CK_PricingRule_17] CHECK (Method = 'PERCENT_OF_AMOUNT' OR (RatePct IS NULL AND RateRangeLowPct IS NULL AND RateRangeHighPct IS NULL)),
    CONSTRAINT [CK_PricingRule_18] CHECK (Method = 'FIXED_AMOUNT' OR FixedAmount IS NULL),
    CONSTRAINT [CK_PricingRule_19] CHECK (Method = 'PER_MILLION' OR PerMillionAmount IS NULL),
    CONSTRAINT [CK_PricingRule_20] CHECK (RatePct IS NULL OR (RateRangeLowPct IS NULL AND RateRangeHighPct IS NULL)),
    CONSTRAINT [CK_PricingRule_21] CHECK ((RateRangeLowPct IS NULL AND RateRangeHighPct IS NULL) OR (RateRangeLowPct IS NOT NULL AND RateRangeHighPct IS NOT NULL AND RateRangeLowPct <= RateRangeHighPct)),
    CONSTRAINT [CK_PricingRule_22] CHECK (RatePct IS NULL OR (RatePct >= 0 AND RatePct <= 100)),
    CONSTRAINT [CK_PricingRule_23] CHECK (FixedAmount IS NULL OR FixedAmount >= 0),
    CONSTRAINT [CK_PricingRule_24] CHECK (PerMillionAmount IS NULL OR PerMillionAmount >= 0),
    CONSTRAINT [CK_PricingRule_25] CHECK (MinFeeAmount IS NULL OR MinFeeAmount >= 0),
    CONSTRAINT [CK_PricingRule_26] CHECK (MinFeeAmount IS NULL OR MaxFeeAmount IS NULL OR MinFeeAmount <= MaxFeeAmount),
    CONSTRAINT [CK_PricingRule_27] CHECK (PeriodDays IS NULL OR PeriodDays > 0),
    CONSTRAINT [CK_PricingRule_28] CHECK (PeriodBasis IS NULL OR PeriodBasis <> 'PER_PERIOD_OR_PART' OR PeriodDays IS NOT NULL OR Method IN ('TARIFF_AS_IS','TARIFF_PLUS_ADDON','TIERED')),
    CONSTRAINT [CK_PricingRule_29] CHECK (PeriodBasis IS NULL OR PeriodBasis <> 'PER_ANNUM' OR DayCount IS NOT NULL),
    CONSTRAINT [CK_PricingRule_30] CHECK (RepricingMonths IS NULL OR RepricingMonths > 0),
    CONSTRAINT [CK_PricingRule_31] CHECK (RateFixing IS NULL OR RateFixing <> 'FLOATING' OR RateState <> 'SET' OR RepricingMonths IS NOT NULL),
    CONSTRAINT [CK_PricingRule_32] CHECK (BenchmarkReplacement <> 'NAMED_FALLBACK' OR ReplacementText IS NOT NULL),
    CONSTRAINT [CK_PricingRule_33] CHECK (BankMayChange <> 'WITH_NOTICE_OBJECTION' OR (ObjectionDays IS NOT NULL AND ObjectionDaysKind IS NOT NULL)),
    CONSTRAINT [CK_PricingRule_34] CHECK (ObjectionDays IS NULL OR ObjectionDays >= 0),
    CONSTRAINT [CK_PricingRule_35] CHECK (Retroactive = 0 OR RetroactiveReason IS NOT NULL),
    CONSTRAINT [CK_PricingRule_36] CHECK (ToRevision IS NULL OR ToRevision >= FromRevision),
    CONSTRAINT [CK_PricingRule_37] CHECK (SourceDocumentId IS NOT NULL AND SourcePage IS NOT NULL OR (SourceDocumentId IS NULL AND Confidence = 'ENTERED_NO_DOCUMENT')),
    CONSTRAINT [CK_PricingRule_38] CHECK (Confidence <> 'CONFIRMED_AGAINST_ORIGINAL' OR (VerifiedBy IS NOT NULL AND VerifiedOn IS NOT NULL)),
    CONSTRAINT [CK_PricingRule_ComponentKind] CHECK ([ComponentKind] IS NULL OR [ComponentKind] IN ('FEE', 'FINANCING_RETURN', 'PENALTY_NON_INCOME')),
    CONSTRAINT [CK_PricingRule_RateState] CHECK ([RateState] IS NULL OR [RateState] IN ('SET', 'NOT_SPECIFIED_IN_AGREEMENT')),
    CONSTRAINT [CK_PricingRule_Method] CHECK ([Method] IS NULL OR [Method] IN ('TARIFF_AS_IS', 'TARIFF_PLUS_ADDON', 'BASE_PLUS_MARGIN', 'PERCENT_OF_AMOUNT', 'FIXED_AMOUNT', 'PER_MILLION', 'TIERED')),
    CONSTRAINT [CK_PricingRule_PeriodBasis] CHECK ([PeriodBasis] IS NULL OR [PeriodBasis] IN ('FLAT', 'PER_ANNUM', 'PER_PERIOD_OR_PART')),
    CONSTRAINT [CK_PricingRule_RateFixing] CHECK ([RateFixing] IS NULL OR [RateFixing] IN ('FIXED_FOR_CONTRACT', 'FLOATING')),
    CONSTRAINT [CK_PricingRule_DayCount] CHECK ([DayCount] IS NULL OR [DayCount] IN ('ACT_360', 'ACT_365')),
    CONSTRAINT [CK_PricingRule_BenchmarkReplacement] CHECK ([BenchmarkReplacement] IS NULL OR [BenchmarkReplacement] IN ('NONE', 'BANK_DETERMINES', 'NAMED_FALLBACK')),
    CONSTRAINT [CK_PricingRule_BankMayChange] CHECK ([BankMayChange] IS NULL OR [BankMayChange] IN ('NO', 'WITH_NOTICE_OBJECTION', 'UNILATERAL')),
    CONSTRAINT [CK_PricingRule_ObjectionDaysKind] CHECK ([ObjectionDaysKind] IS NULL OR [ObjectionDaysKind] IN ('CALENDAR', 'BUSINESS')),
    CONSTRAINT [CK_PricingRule_TriggerEvent] CHECK ([TriggerEvent] IS NULL OR [TriggerEvent] IN ('LATE_PAYMENT', 'LATE_GUARANTEE_PAYMENT_AFTER_DEMAND', 'OTHER')),
    CONSTRAINT [CK_PricingRule_Confidence] CHECK ([Confidence] IS NULL OR [Confidence] IN ('CONFIRMED_AGAINST_ORIGINAL', 'READ_FROM_SCAN_UNVERIFIED', 'ENTERED_NO_DOCUMENT'))
);
GO
-- شريحة قاعدة TIERED بالمبلغ و/أو المدة (FR-PRC-003، BR-PRC-002)
CREATE TABLE [prc].[PricingTier] (
    [TenantId] INT NOT NULL,
    [PricingTierId] BIGINT IDENTITY(1,1) NOT NULL,
    [FacilityId] BIGINT NOT NULL,
    [PricingRuleId] BIGINT NOT NULL,
    [AmountFrom] DECIMAL(19,4) NULL,
    [AmountTo] DECIMAL(19,4) NULL,
    [PeriodFromDays] INT NULL,
    [PeriodToDays] INT NULL,
    [RatePct] DECIMAL(9,6) NULL,
    [MarginPct] DECIMAL(9,6) NULL,
    [FixedAmount] DECIMAL(19,4) NULL,
    [SortOrder] INT NOT NULL,
    [FromRevision] INT NOT NULL CONSTRAINT [DF_PricingTier_FromRevision] DEFAULT 1,
    [ToRevision] INT NULL,
    [SupersedesId] BIGINT NULL,
    [CreatedAt] DATETIME2(3) NOT NULL CONSTRAINT [DF_PricingTier_CreatedAt] DEFAULT SYSUTCDATETIME(),
    [CreatedBy] BIGINT NULL,
    [UpdatedAt] DATETIME2(3) NULL,
    [UpdatedBy] BIGINT NULL,
    [RowVersion] ROWVERSION NOT NULL,
    CONSTRAINT [PK_PricingTier] PRIMARY KEY CLUSTERED ([PricingTierId]),
    CONSTRAINT [UQ_PricingTier_Tenant] UNIQUE ([TenantId], [PricingTierId]),
    CONSTRAINT [CK_PricingTier_1] CHECK (AmountFrom IS NULL OR AmountFrom >= 0),
    CONSTRAINT [CK_PricingTier_2] CHECK (AmountTo IS NULL OR AmountFrom IS NULL OR AmountTo > AmountFrom),
    CONSTRAINT [CK_PricingTier_3] CHECK (PeriodFromDays IS NULL OR PeriodFromDays >= 0),
    CONSTRAINT [CK_PricingTier_4] CHECK (PeriodToDays IS NULL OR PeriodFromDays IS NULL OR PeriodToDays >= PeriodFromDays),
    CONSTRAINT [CK_PricingTier_5] CHECK ((CASE WHEN RatePct IS NULL THEN 0 ELSE 1 END + CASE WHEN MarginPct IS NULL THEN 0 ELSE 1 END + CASE WHEN FixedAmount IS NULL THEN 0 ELSE 1 END) = 1),
    CONSTRAINT [CK_PricingTier_6] CHECK (RatePct IS NULL OR (RatePct >= 0 AND RatePct <= 100)),
    CONSTRAINT [CK_PricingTier_7] CHECK (FixedAmount IS NULL OR FixedAmount >= 0),
    CONSTRAINT [CK_PricingTier_8] CHECK (ToRevision IS NULL OR ToRevision >= FromRevision)
);
GO

-- ===== schema cmp =====
-- مفتاح شرط قابل للمقارنة (FR-CMP-001)؛ الرمز بنمط PRC.MARGIN_PCT؛ النظامي لا يُحذف ولا تتغير وحدته (IsSystem)
CREATE TABLE [cmp].[TermType] (
    [TenantId] INT NOT NULL,
    [TermTypeId] INT IDENTITY(1,1) NOT NULL,
    [Code] VARCHAR(80) NOT NULL,
    [NameAr] NVARCHAR(200) NOT NULL,
    [NameEn] NVARCHAR(200) NULL,
    [Description] NVARCHAR(500) NULL,
    [IsActive] BIT NOT NULL CONSTRAINT [DF_TermType_IsActive] DEFAULT 1,
    [IsSystem] BIT NOT NULL CONSTRAINT [DF_TermType_IsSystem] DEFAULT 0,
    [IsLocked] BIT NOT NULL CONSTRAINT [DF_TermType_IsLocked] DEFAULT 0,
    [SortOrder] INT NOT NULL CONSTRAINT [DF_TermType_SortOrder] DEFAULT 0,
    [SeedKey] VARCHAR(80) NULL,
    [ExternalCode] VARCHAR(80) NULL,
    [Category] VARCHAR(10) NOT NULL,
    [ValueKind] VARCHAR(10) NOT NULL,
    [Unit] VARCHAR(20) NOT NULL,
    [DefaultBound] VARCHAR(10) NOT NULL CONSTRAINT [DF_TermType_DefaultBound] DEFAULT 'EXACT',
    [Direction] VARCHAR(13) NOT NULL CONSTRAINT [DF_TermType_Direction] DEFAULT 'NEUTRAL',
    [ScopeKinds] VARCHAR(44) NOT NULL,
    [SourceBinding] NVARCHAR(200) NULL,
    [EnumOptions] NVARCHAR(MAX) NULL,
    [IsComparable] BIT NOT NULL CONSTRAINT [DF_TermType_IsComparable] DEFAULT 1,
    [CreatedAt] DATETIME2(3) NOT NULL CONSTRAINT [DF_TermType_CreatedAt] DEFAULT SYSUTCDATETIME(),
    [CreatedBy] BIGINT NULL,
    [UpdatedAt] DATETIME2(3) NULL,
    [UpdatedBy] BIGINT NULL,
    [RowVersion] ROWVERSION NOT NULL,
    CONSTRAINT [PK_TermType] PRIMARY KEY CLUSTERED ([TermTypeId]),
    CONSTRAINT [UQ_TermType_Tenant] UNIQUE ([TenantId], [TermTypeId]),
    CONSTRAINT [UQ_TermType_Code] UNIQUE ([TenantId], [Code]),
    CONSTRAINT [CK_TermType_1] CHECK (ScopeKinds <> ''),
    CONSTRAINT [CK_TermType_2] CHECK (ValueKind <> 'ENUM' OR EnumOptions IS NOT NULL),
    CONSTRAINT [CK_TermType_3] CHECK (ValueKind = 'ENUM' OR EnumOptions IS NULL),
    CONSTRAINT [CK_TermType_Category] CHECK ([Category] IS NULL OR [Category] IN ('PRICING', 'DURATION', 'COLLATERAL', 'COVENANT', 'OTHER')),
    CONSTRAINT [CK_TermType_ValueKind] CHECK ([ValueKind] IS NULL OR [ValueKind] IN ('PERCENT', 'AMOUNT', 'DAYS', 'MONTHS', 'COUNT', 'BOOLEAN', 'ENUM', 'TEXT')),
    CONSTRAINT [CK_TermType_DefaultBound] CHECK ([DefaultBound] IS NULL OR [DefaultBound] IN ('EXACT', 'MAX', 'MIN')),
    CONSTRAINT [CK_TermType_Direction] CHECK ([Direction] IS NULL OR [Direction] IN ('LOWER_BETTER', 'HIGHER_BETTER', 'NEUTRAL')),
    CONSTRAINT [CK_TermType_EnumOptions_json] CHECK ([EnumOptions] IS NULL OR ISJSON([EnumOptions]) = 1)
);
GO
-- قيمة شرط في تسهيل بنطاقها ومصدرها (FR-CMP-002..006، BR-CMP-001..006، V-CMP-01)
CREATE TABLE [cmp].[TermValue] (
    [TenantId] INT NOT NULL,
    [TermValueId] BIGINT IDENTITY(1,1) NOT NULL,
    [FacilityId] BIGINT NOT NULL,
    [TermTypeId] INT NOT NULL,
    [OtherLabel] NVARCHAR(200) NULL,
    [LimitId] BIGINT NULL,
    [LimitProductLineId] BIGINT NULL,
    [ProductId] INT NULL,
    [CompanyId] BIGINT NULL,
    [ValueState] VARCHAR(26) NOT NULL CONSTRAINT [DF_TermValue_ValueState] DEFAULT 'SPECIFIED',
    [ValueNumber] DECIMAL(19,6) NULL,
    [ValueText] NVARCHAR(1000) NULL,
    [ValueBool] BIT NULL,
    [ValueEnum] NVARCHAR(100) NULL,
    [Unit] VARCHAR(20) NOT NULL,
    [CurrencyId] INT NULL,
    [Bound] VARCHAR(10) NOT NULL CONSTRAINT [DF_TermValue_Bound] DEFAULT 'EXACT',
    [NormalizedValue] DECIMAL(19,6) NULL,
    [Origin] VARCHAR(10) NOT NULL CONSTRAINT [DF_TermValue_Origin] DEFAULT 'ENTERED',
    [ProjectedFrom] VARCHAR(120) NULL,
    [EffectiveFrom] DATE NOT NULL,
    [EffectiveTo] DATE NULL,
    [FromRevision] INT NOT NULL CONSTRAINT [DF_TermValue_FromRevision] DEFAULT 1,
    [ToRevision] INT NULL,
    [SupersedesId] BIGINT NULL,
    [SourceDocumentId] BIGINT NULL,
    [SourcePage] VARCHAR(40) NULL,
    [ReadFromScan] BIT NOT NULL CONSTRAINT [DF_TermValue_ReadFromScan] DEFAULT 0,
    [OriginalText] NVARCHAR(2000) NULL,
    [NoSourceReason] NVARCHAR(300) NULL,
    [Confidence] VARCHAR(26) NOT NULL CONSTRAINT [DF_TermValue_Confidence] DEFAULT 'ENTERED_NO_DOCUMENT',
    [VerifiedBy] BIGINT NULL,
    [VerifiedOn] DATETIME2(3) NULL,
    [ConflictId] BIGINT NULL,
    [CreatedAt] DATETIME2(3) NOT NULL CONSTRAINT [DF_TermValue_CreatedAt] DEFAULT SYSUTCDATETIME(),
    [CreatedBy] BIGINT NULL,
    [UpdatedAt] DATETIME2(3) NULL,
    [UpdatedBy] BIGINT NULL,
    [RowVersion] ROWVERSION NOT NULL,
    CONSTRAINT [PK_TermValue] PRIMARY KEY CLUSTERED ([TermValueId]),
    CONSTRAINT [UQ_TermValue_Tenant] UNIQUE ([TenantId], [TermValueId]),
    CONSTRAINT [CK_TermValue_1] CHECK (LimitProductLineId IS NULL OR LimitId IS NOT NULL),
    CONSTRAINT [CK_TermValue_2] CHECK (EffectiveTo IS NULL OR EffectiveTo >= EffectiveFrom),
    CONSTRAINT [CK_TermValue_3] CHECK (ValueState = 'SPECIFIED' OR (ValueNumber IS NULL AND ValueText IS NULL AND ValueBool IS NULL AND ValueEnum IS NULL AND NormalizedValue IS NULL)),
    CONSTRAINT [CK_TermValue_4] CHECK (ValueState <> 'SPECIFIED' OR (CASE WHEN ValueNumber IS NULL THEN 0 ELSE 1 END + CASE WHEN ValueText IS NULL THEN 0 ELSE 1 END + CASE WHEN ValueBool IS NULL THEN 0 ELSE 1 END + CASE WHEN ValueEnum IS NULL THEN 0 ELSE 1 END) = 1),
    CONSTRAINT [CK_TermValue_5] CHECK (NormalizedValue IS NULL OR ValueNumber IS NOT NULL),
    CONSTRAINT [CK_TermValue_6] CHECK (Origin <> 'PROJECTED' OR ProjectedFrom IS NOT NULL),
    CONSTRAINT [CK_TermValue_7] CHECK (Origin = 'PROJECTED' OR ProjectedFrom IS NULL),
    CONSTRAINT [CK_TermValue_8] CHECK (ToRevision IS NULL OR ToRevision >= FromRevision),
    CONSTRAINT [CK_TermValue_9] CHECK (SourceDocumentId IS NOT NULL AND SourcePage IS NOT NULL OR (SourceDocumentId IS NULL AND Confidence = 'ENTERED_NO_DOCUMENT')),
    CONSTRAINT [CK_TermValue_10] CHECK (Confidence <> 'CONFIRMED_AGAINST_ORIGINAL' OR (VerifiedBy IS NOT NULL AND VerifiedOn IS NOT NULL)),
    CONSTRAINT [CK_TermValue_ValueState] CHECK ([ValueState] IS NULL OR [ValueState] IN ('SPECIFIED', 'NOT_SPECIFIED_IN_AGREEMENT', 'NOT_APPLICABLE', 'UNKNOWN')),
    CONSTRAINT [CK_TermValue_Bound] CHECK ([Bound] IS NULL OR [Bound] IN ('EXACT', 'MAX', 'MIN')),
    CONSTRAINT [CK_TermValue_Origin] CHECK ([Origin] IS NULL OR [Origin] IN ('ENTERED', 'PROJECTED')),
    CONSTRAINT [CK_TermValue_Confidence] CHECK ([Confidence] IS NULL OR [Confidence] IN ('CONFIRMED_AGAINST_ORIGINAL', 'READ_FROM_SCAN_UNVERIFIED', 'ENTERED_NO_DOCUMENT'))
);
GO

-- ===== schema col =====
-- سجل ضمان؛ اعتماد مستقل عن مراجعة التسهيل والتعديل نسخة جديدة (FR-COL-001/014، V-COL-01، §8)
CREATE TABLE [col].[Collateral] (
    [TenantId] INT NOT NULL,
    [CollateralId] BIGINT IDENTITY(1,1) NOT NULL,
    [CollateralTypeId] INT NOT NULL,
    [TitleAr] NVARCHAR(300) NOT NULL,
    [Description] NVARCHAR(2000) NULL,
    [OwnerPartyId] BIGINT NULL,
    [Attributes] NVARCHAR(MAX) NULL,
    [CashMarginAccountId] BIGINT NULL,
    [Status] VARCHAR(10) NOT NULL CONSTRAINT [DF_Collateral_Status] DEFAULT 'DRAFT',
    [ApprovalState] VARCHAR(10) NOT NULL CONSTRAINT [DF_Collateral_ApprovalState] DEFAULT 'DRAFT',
    [ApprovedBy] BIGINT NULL,
    [ApprovedOn] DATETIME2(3) NULL,
    [SupersedesId] BIGINT NULL,
    [GrantedOn] DATE NULL,
    [ReleasedOn] DATE NULL,
    [ReleaseReason] NVARCHAR(500) NULL,
    [ReleaseDocumentId] BIGINT NULL,
    [SourceDocumentId] BIGINT NULL,
    [SourcePage] VARCHAR(40) NULL,
    [ReadFromScan] BIT NOT NULL CONSTRAINT [DF_Collateral_ReadFromScan] DEFAULT 0,
    [OriginalText] NVARCHAR(2000) NULL,
    [NoSourceReason] NVARCHAR(300) NULL,
    [Confidence] VARCHAR(26) NOT NULL CONSTRAINT [DF_Collateral_Confidence] DEFAULT 'ENTERED_NO_DOCUMENT',
    [VerifiedBy] BIGINT NULL,
    [VerifiedOn] DATETIME2(3) NULL,
    [ConflictId] BIGINT NULL,
    [PublicId] UNIQUEIDENTIFIER NOT NULL CONSTRAINT [DF_Collateral_PublicId] DEFAULT NEWSEQUENTIALID(),
    [CreatedAt] DATETIME2(3) NOT NULL CONSTRAINT [DF_Collateral_CreatedAt] DEFAULT SYSUTCDATETIME(),
    [CreatedBy] BIGINT NULL,
    [UpdatedAt] DATETIME2(3) NULL,
    [UpdatedBy] BIGINT NULL,
    [RowVersion] ROWVERSION NOT NULL,
    CONSTRAINT [PK_Collateral] PRIMARY KEY CLUSTERED ([CollateralId]),
    CONSTRAINT [UQ_Collateral_Tenant] UNIQUE ([TenantId], [CollateralId]),
    CONSTRAINT [UQ_Collateral_PublicId] UNIQUE ([PublicId]),
    CONSTRAINT [CK_Collateral_1] CHECK (Status = 'DRAFT' OR ApprovalState = 'APPROVED'),
    CONSTRAINT [CK_Collateral_2] CHECK (ApprovalState <> 'APPROVED' OR Status <> 'DRAFT'),
    CONSTRAINT [CK_Collateral_3] CHECK (ApprovalState <> 'APPROVED' OR (ApprovedBy IS NOT NULL AND ApprovedOn IS NOT NULL)),
    CONSTRAINT [CK_Collateral_4] CHECK (Status <> 'RELEASED' OR (ReleasedOn IS NOT NULL AND ReleaseReason IS NOT NULL)),
    CONSTRAINT [CK_Collateral_5] CHECK (Status = 'RELEASED' OR (ReleasedOn IS NULL AND ReleaseReason IS NULL AND ReleaseDocumentId IS NULL)),
    CONSTRAINT [CK_Collateral_6] CHECK (GrantedOn IS NULL OR ReleasedOn IS NULL OR ReleasedOn >= GrantedOn),
    CONSTRAINT [CK_Collateral_7] CHECK (SupersedesId IS NULL OR SupersedesId <> CollateralId),
    CONSTRAINT [CK_Collateral_8] CHECK (SourceDocumentId IS NOT NULL AND SourcePage IS NOT NULL OR (SourceDocumentId IS NULL AND Confidence = 'ENTERED_NO_DOCUMENT')),
    CONSTRAINT [CK_Collateral_9] CHECK (Confidence <> 'CONFIRMED_AGAINST_ORIGINAL' OR (VerifiedBy IS NOT NULL AND VerifiedOn IS NOT NULL)),
    CONSTRAINT [CK_Collateral_Status] CHECK ([Status] IS NULL OR [Status] IN ('DRAFT', 'ACTIVE', 'RELEASED', 'EXPIRED')),
    CONSTRAINT [CK_Collateral_ApprovalState] CHECK ([ApprovalState] IS NULL OR [ApprovalState] IN ('DRAFT', 'APPROVED')),
    CONSTRAINT [CK_Collateral_Confidence] CHECK ([Confidence] IS NULL OR [Confidence] IN ('CONFIRMED_AGAINST_ORIGINAL', 'READ_FROM_SCAN_UNVERIFIED', 'ENTERED_NO_DOCUMENT')),
    CONSTRAINT [CK_Collateral_Attributes_json] CHECK ([Attributes] IS NULL OR ISJSON([Attributes]) = 1)
);
GO
-- ربط ضمان بتسهيل أو حد؛ ضمان واحد لعدة تسهيلات (FR-COL-002، BR-COL-005)
CREATE TABLE [col].[CollateralLink] (
    [TenantId] INT NOT NULL,
    [CollateralLinkId] BIGINT IDENTITY(1,1) NOT NULL,
    [CollateralId] BIGINT NOT NULL,
    [FacilityId] BIGINT NOT NULL,
    [LimitId] BIGINT NULL,
    [CoverageAmount] DECIMAL(19,4) NULL,
    [LienRank] INT NULL,
    [LinkedOn] DATE NOT NULL,
    [UnlinkedOn] DATE NULL,
    [FromRevision] INT NOT NULL CONSTRAINT [DF_CollateralLink_FromRevision] DEFAULT 1,
    [ToRevision] INT NULL,
    [SupersedesId] BIGINT NULL,
    [CreatedAt] DATETIME2(3) NOT NULL CONSTRAINT [DF_CollateralLink_CreatedAt] DEFAULT SYSUTCDATETIME(),
    [CreatedBy] BIGINT NULL,
    [UpdatedAt] DATETIME2(3) NULL,
    [UpdatedBy] BIGINT NULL,
    [RowVersion] ROWVERSION NOT NULL,
    CONSTRAINT [PK_CollateralLink] PRIMARY KEY CLUSTERED ([CollateralLinkId]),
    CONSTRAINT [UQ_CollateralLink_Tenant] UNIQUE ([TenantId], [CollateralLinkId]),
    CONSTRAINT [CK_CollateralLink_1] CHECK (CoverageAmount IS NULL OR CoverageAmount > 0),
    CONSTRAINT [CK_CollateralLink_2] CHECK (LienRank IS NULL OR LienRank >= 1),
    CONSTRAINT [CK_CollateralLink_3] CHECK (UnlinkedOn IS NULL OR UnlinkedOn >= LinkedOn),
    CONSTRAINT [CK_CollateralLink_4] CHECK (ToRevision IS NULL OR ToRevision >= FromRevision)
);
GO
-- كفالة 1:1 مع Collateral؛ الكفيل Party دائمًا ولا أرقام هوية هنا (FR-COL-003/004، BR-COL-001)
CREATE TABLE [col].[Guarantee] (
    [TenantId] INT NOT NULL,
    [GuaranteeId] BIGINT IDENTITY(1,1) NOT NULL,
    [CollateralId] BIGINT NOT NULL,
    [GuarantorPartyId] BIGINT NOT NULL,
    [GuarantorIdentityDocumentId] BIGINT NULL,
    [GuaranteeForm] VARCHAR(33) NOT NULL,
    [IsJointSeveral] BIT NOT NULL,
    [AmountMode] VARCHAR(11) NOT NULL,
    [Amount] DECIMAL(19,4) NULL,
    [CurrencyId] INT NULL,
    [SignedOn] DATE NULL,
    [ValidTo] DATE NULL,
    [DeedDocumentId] BIGINT NULL,
    [CreatedAt] DATETIME2(3) NOT NULL CONSTRAINT [DF_Guarantee_CreatedAt] DEFAULT SYSUTCDATETIME(),
    [CreatedBy] BIGINT NULL,
    [UpdatedAt] DATETIME2(3) NULL,
    [UpdatedBy] BIGINT NULL,
    [RowVersion] ROWVERSION NOT NULL,
    CONSTRAINT [PK_Guarantee] PRIMARY KEY CLUSTERED ([GuaranteeId]),
    CONSTRAINT [UQ_Guarantee_Tenant] UNIQUE ([TenantId], [GuaranteeId]),
    CONSTRAINT [UQ_Guarantee_CollateralId] UNIQUE ([TenantId], [CollateralId]),
    CONSTRAINT [CK_Guarantee_1] CHECK (AmountMode <> 'SPECIFIED' OR (Amount IS NOT NULL AND CurrencyId IS NOT NULL)),
    CONSTRAINT [CK_Guarantee_2] CHECK (AmountMode <> 'UNSPECIFIED' OR (Amount IS NULL AND CurrencyId IS NULL)),
    CONSTRAINT [CK_Guarantee_3] CHECK (Amount IS NULL OR Amount > 0),
    CONSTRAINT [CK_Guarantee_4] CHECK (SignedOn IS NULL OR ValidTo IS NULL OR ValidTo >= SignedOn),
    CONSTRAINT [CK_Guarantee_5] CHECK (GuaranteeForm <> 'JOINT_SEVERAL_PAYMENT_PERFORMANCE' OR IsJointSeveral = 1),
    CONSTRAINT [CK_Guarantee_GuaranteeForm] CHECK ([GuaranteeForm] IS NULL OR [GuaranteeForm] IN ('JOINT_SEVERAL_PAYMENT_PERFORMANCE', 'SIMPLE', 'OTHER')),
    CONSTRAINT [CK_Guarantee_AmountMode] CHECK ([AmountMode] IS NULL OR [AmountMode] IN ('SPECIFIED', 'UNSPECIFIED'))
);
GO
-- سند لأمر 1:1؛ مبلغ مستقل قد يفوق الحد (FR-COL-005، BR-COL-002)؛ NextRenewalDue وPNRatio مشتقان
CREATE TABLE [col].[PromissoryNote] (
    [TenantId] INT NOT NULL,
    [PromissoryNoteId] BIGINT IDENTITY(1,1) NOT NULL,
    [CollateralId] BIGINT NOT NULL,
    [NoteAmount] DECIMAL(19,4) NOT NULL,
    [CurrencyId] INT NOT NULL,
    [IssuedOn] DATE NOT NULL,
    [DueKind] VARCHAR(10) NOT NULL,
    [DueDate] DATE NULL,
    [RenewalCycle] VARCHAR(10) NOT NULL,
    [LastRenewedOn] DATE NULL,
    [CustodyKind] VARCHAR(10) NOT NULL,
    [NoteDocumentId] BIGINT NULL,
    [CreatedAt] DATETIME2(3) NOT NULL CONSTRAINT [DF_PromissoryNote_CreatedAt] DEFAULT SYSUTCDATETIME(),
    [CreatedBy] BIGINT NULL,
    [UpdatedAt] DATETIME2(3) NULL,
    [UpdatedBy] BIGINT NULL,
    [RowVersion] ROWVERSION NOT NULL,
    CONSTRAINT [PK_PromissoryNote] PRIMARY KEY CLUSTERED ([PromissoryNoteId]),
    CONSTRAINT [UQ_PromissoryNote_Tenant] UNIQUE ([TenantId], [PromissoryNoteId]),
    CONSTRAINT [UQ_PromissoryNote_CollateralId] UNIQUE ([TenantId], [CollateralId]),
    CONSTRAINT [CK_PromissoryNote_1] CHECK (NoteAmount > 0),
    CONSTRAINT [CK_PromissoryNote_2] CHECK (DueKind <> 'FIXED_DATE' OR (DueDate IS NOT NULL AND DueDate >= IssuedOn)),
    CONSTRAINT [CK_PromissoryNote_3] CHECK (DueKind <> 'ON_DEMAND' OR DueDate IS NULL),
    CONSTRAINT [CK_PromissoryNote_4] CHECK (LastRenewedOn IS NULL OR LastRenewedOn >= IssuedOn),
    CONSTRAINT [CK_PromissoryNote_5] CHECK (RenewalCycle <> 'NONE' OR LastRenewedOn IS NULL),
    CONSTRAINT [CK_PromissoryNote_DueKind] CHECK ([DueKind] IS NULL OR [DueKind] IN ('ON_DEMAND', 'FIXED_DATE')),
    CONSTRAINT [CK_PromissoryNote_RenewalCycle] CHECK ([RenewalCycle] IS NULL OR [RenewalCycle] IN ('NONE', 'ANNUAL')),
    CONSTRAINT [CK_PromissoryNote_CustodyKind] CHECK ([CustodyKind] IS NULL OR [CustodyKind] IN ('BANK', 'COMPANY', 'OTHER'))
);
GO
-- موقّعو السند (SignerPartyIds) -- جدول وسيط جديد؛ موقّعو PromissoryNote (FR-COL-015)
CREATE TABLE [col].[PromissoryNoteSigner] (
    [TenantId] INT NOT NULL,
    [PromissoryNoteId] BIGINT NOT NULL,
    [PartyId] BIGINT NOT NULL,
    [CreatedAt] DATETIME2(3) NOT NULL CONSTRAINT [DF_PromissoryNoteSigner_CreatedAt] DEFAULT SYSUTCDATETIME(),
    [CreatedBy] BIGINT NULL,
    [UpdatedAt] DATETIME2(3) NULL,
    [UpdatedBy] BIGINT NULL,
    CONSTRAINT [PK_PromissoryNoteSigner] PRIMARY KEY CLUSTERED ([TenantId], [PromissoryNoteId], [PartyId])
);
GO
-- تجيير وثيقة تأمين؛ مفتاح الفرادة (CollateralId,PolicyNo) يسمح بتجديد الوثيقة (FR-COL-006، BR-COL-003)
CREATE TABLE [col].[InsurancePolicyAssignment] (
    [TenantId] INT NOT NULL,
    [InsurancePolicyAssignmentId] BIGINT IDENTITY(1,1) NOT NULL,
    [CollateralId] BIGINT NOT NULL,
    [PolicyNo] NVARCHAR(60) NOT NULL,
    [InsurerName] NVARCHAR(200) NOT NULL,
    [AssignedToInstitutionId] BIGINT NOT NULL,
    [CoverageBasis] VARCHAR(12) NOT NULL,
    [CoveragePct] DECIMAL(9,6) NULL,
    [CoverageAmount] DECIMAL(19,4) NULL,
    [SumInsured] DECIMAL(19,4) NOT NULL,
    [CurrencyId] INT NOT NULL,
    [PolicyStart] DATE NULL,
    [PolicyExpiry] DATE NOT NULL,
    [AssignmentDate] DATE NULL,
    [PolicyDocumentId] BIGINT NULL,
    [CreatedAt] DATETIME2(3) NOT NULL CONSTRAINT [DF_InsurancePolicyAssignment_CreatedAt] DEFAULT SYSUTCDATETIME(),
    [CreatedBy] BIGINT NULL,
    [UpdatedAt] DATETIME2(3) NULL,
    [UpdatedBy] BIGINT NULL,
    [RowVersion] ROWVERSION NOT NULL,
    CONSTRAINT [PK_InsurancePolicyAssignment] PRIMARY KEY CLUSTERED ([InsurancePolicyAssignmentId]),
    CONSTRAINT [UQ_InsurancePolicyAssignment_Tenant] UNIQUE ([TenantId], [InsurancePolicyAssignmentId]),
    CONSTRAINT [UQ_InsurancePolicyAssignment_CollateralId_PolicyNo] UNIQUE ([TenantId], [CollateralId], [PolicyNo]),
    CONSTRAINT [CK_InsurancePolicyAssignment_1] CHECK (SumInsured > 0),
    CONSTRAINT [CK_InsurancePolicyAssignment_2] CHECK (PolicyStart IS NULL OR PolicyExpiry >= PolicyStart),
    CONSTRAINT [CK_InsurancePolicyAssignment_3] CHECK (CoverageBasis <> 'PCT_OF_LIMIT' OR (CoveragePct IS NOT NULL AND CoveragePct > 0 AND CoverageAmount IS NULL)),
    CONSTRAINT [CK_InsurancePolicyAssignment_4] CHECK (CoverageBasis <> 'FIXED_AMOUNT' OR (CoverageAmount IS NOT NULL AND CoverageAmount > 0 AND CoveragePct IS NULL)),
    CONSTRAINT [CK_InsurancePolicyAssignment_5] CHECK (CoverageBasis <> 'FULL_LIMITS' OR (CoveragePct IS NULL AND CoverageAmount IS NULL)),
    CONSTRAINT [CK_InsurancePolicyAssignment_CoverageBasis] CHECK ([CoverageBasis] IS NULL OR [CoverageBasis] IN ('PCT_OF_LIMIT', 'FIXED_AMOUNT', 'FULL_LIMITS'))
);
GO
-- مراحل تقييم عقار (FR-COL-008، BR-COL-004)؛ مثل 3 مقيّمين في السنة الأولى ثم مقيّم سنويًا
CREATE TABLE [col].[ValuationSchedule] (
    [TenantId] INT NOT NULL,
    [ValuationScheduleId] BIGINT IDENTITY(1,1) NOT NULL,
    [CollateralId] BIGINT NOT NULL,
    [PhaseNo] INT NOT NULL,
    [FromYear] INT NOT NULL,
    [ToYear] INT NULL,
    [RequiredValuerCount] INT NOT NULL,
    [FrequencyMonths] INT NOT NULL,
    [ReferenceDate] DATE NOT NULL,
    [LastValuationOn] DATE NULL,
    [LastValuationAmount] DECIMAL(19,4) NULL,
    [CurrencyId] INT NULL,
    [CreatedAt] DATETIME2(3) NOT NULL CONSTRAINT [DF_ValuationSchedule_CreatedAt] DEFAULT SYSUTCDATETIME(),
    [CreatedBy] BIGINT NULL,
    [UpdatedAt] DATETIME2(3) NULL,
    [UpdatedBy] BIGINT NULL,
    [RowVersion] ROWVERSION NOT NULL,
    CONSTRAINT [PK_ValuationSchedule] PRIMARY KEY CLUSTERED ([ValuationScheduleId]),
    CONSTRAINT [UQ_ValuationSchedule_Tenant] UNIQUE ([TenantId], [ValuationScheduleId]),
    CONSTRAINT [UQ_ValuationSchedule_CollateralId_PhaseNo] UNIQUE ([TenantId], [CollateralId], [PhaseNo]),
    CONSTRAINT [CK_ValuationSchedule_1] CHECK (PhaseNo >= 1),
    CONSTRAINT [CK_ValuationSchedule_2] CHECK (FromYear >= 1),
    CONSTRAINT [CK_ValuationSchedule_3] CHECK (ToYear IS NULL OR ToYear >= FromYear),
    CONSTRAINT [CK_ValuationSchedule_4] CHECK (RequiredValuerCount >= 1),
    CONSTRAINT [CK_ValuationSchedule_5] CHECK (FrequencyMonths >= 0),
    CONSTRAINT [CK_ValuationSchedule_6] CHECK (LastValuationAmount IS NULL OR (LastValuationAmount > 0 AND LastValuationOn IS NOT NULL AND CurrencyId IS NOT NULL)),
    CONSTRAINT [CK_ValuationSchedule_7] CHECK (LastValuationOn IS NULL OR LastValuationAmount IS NOT NULL)
);
GO

-- ===== schema obl =====
-- التزام على تسهيل (أو حد/خط/شركات)؛ العائلة من ObligationType ولا تُحرَّر (FR-OBL-001، BR-OBL-001)
CREATE TABLE [obl].[Obligation] (
    [TenantId] INT NOT NULL,
    [ObligationId] BIGINT IDENTITY(1,1) NOT NULL,
    [FacilityId] BIGINT NOT NULL,
    [ObligationTypeId] INT NOT NULL,
    [TitleAr] NVARCHAR(300) NOT NULL,
    [TitleEn] NVARCHAR(300) NULL,
    [Phase] VARCHAR(10) NOT NULL CONSTRAINT [DF_Obligation_Phase] DEFAULT 'ONGOING',
    [ScopeLimitId] BIGINT NULL,
    [ScopeProductLineId] BIGINT NULL,
    [ClauseRef] NVARCHAR(100) NULL,
    [ClauseText] NVARCHAR(MAX) NULL,
    [ConsequenceText] NVARCHAR(2000) NULL,
    [GraceDays] INT NULL,
    [CureDays] INT NULL,
    [ParamValue] DECIMAL(19,6) NULL,
    [ParamUnit] VARCHAR(13) NULL,
    [ParamCurrencyId] INT NULL,
    [TriggerField] VARCHAR(100) NULL,
    [TriggerValues] NVARCHAR(MAX) NULL,
    [CheckMode] VARCHAR(10) NULL,
    [Status] VARCHAR(10) NOT NULL CONSTRAINT [DF_Obligation_Status] DEFAULT 'ACTIVE',
    [ValidFrom] DATE NOT NULL,
    [ValidTo] DATE NULL,
    [FromRevision] INT NOT NULL CONSTRAINT [DF_Obligation_FromRevision] DEFAULT 1,
    [ToRevision] INT NULL,
    [SupersedesId] BIGINT NULL,
    [SourceDocumentId] BIGINT NULL,
    [SourcePage] VARCHAR(40) NULL,
    [ReadFromScan] BIT NOT NULL CONSTRAINT [DF_Obligation_ReadFromScan] DEFAULT 0,
    [OriginalText] NVARCHAR(2000) NULL,
    [NoSourceReason] NVARCHAR(300) NULL,
    [Confidence] VARCHAR(26) NOT NULL CONSTRAINT [DF_Obligation_Confidence] DEFAULT 'ENTERED_NO_DOCUMENT',
    [VerifiedBy] BIGINT NULL,
    [VerifiedOn] DATETIME2(3) NULL,
    [ConflictId] BIGINT NULL,
    [PublicId] UNIQUEIDENTIFIER NOT NULL CONSTRAINT [DF_Obligation_PublicId] DEFAULT NEWSEQUENTIALID(),
    [CreatedAt] DATETIME2(3) NOT NULL CONSTRAINT [DF_Obligation_CreatedAt] DEFAULT SYSUTCDATETIME(),
    [CreatedBy] BIGINT NULL,
    [UpdatedAt] DATETIME2(3) NULL,
    [UpdatedBy] BIGINT NULL,
    [RowVersion] ROWVERSION NOT NULL,
    CONSTRAINT [PK_Obligation] PRIMARY KEY CLUSTERED ([ObligationId]),
    CONSTRAINT [UQ_Obligation_Tenant] UNIQUE ([TenantId], [ObligationId]),
    CONSTRAINT [UQ_Obligation_PublicId] UNIQUE ([PublicId]),
    CONSTRAINT [CK_Obligation_1] CHECK (ValidTo IS NULL OR ValidTo >= ValidFrom),
    CONSTRAINT [CK_Obligation_2] CHECK (GraceDays IS NULL OR GraceDays >= 0),
    CONSTRAINT [CK_Obligation_3] CHECK (CureDays IS NULL OR CureDays >= 0),
    CONSTRAINT [CK_Obligation_4] CHECK ((ParamValue IS NULL AND ParamUnit IS NULL) OR (ParamValue IS NOT NULL AND ParamUnit IS NOT NULL)),
    CONSTRAINT [CK_Obligation_5] CHECK (ParamValue IS NULL OR ParamValue >= 0),
    CONSTRAINT [CK_Obligation_6] CHECK (ParamUnit IS NULL OR ParamUnit <> 'AMOUNT' OR ParamCurrencyId IS NOT NULL),
    CONSTRAINT [CK_Obligation_7] CHECK (ParamCurrencyId IS NULL OR ParamUnit = 'AMOUNT'),
    CONSTRAINT [CK_Obligation_8] CHECK (TriggerValues IS NULL OR TriggerField IS NOT NULL),
    CONSTRAINT [CK_Obligation_9] CHECK (ToRevision IS NULL OR ToRevision >= FromRevision),
    CONSTRAINT [CK_Obligation_10] CHECK (SourceDocumentId IS NOT NULL AND SourcePage IS NOT NULL OR (SourceDocumentId IS NULL AND Confidence = 'ENTERED_NO_DOCUMENT')),
    CONSTRAINT [CK_Obligation_11] CHECK (Confidence <> 'CONFIRMED_AGAINST_ORIGINAL' OR (VerifiedBy IS NOT NULL AND VerifiedOn IS NOT NULL)),
    CONSTRAINT [CK_Obligation_Phase] CHECK ([Phase] IS NULL OR [Phase] IN ('PRECEDENT', 'ONGOING', 'SUBSEQUENT')),
    CONSTRAINT [CK_Obligation_ParamUnit] CHECK ([ParamUnit] IS NULL OR [ParamUnit] IN ('DAYS', 'BUSINESS_DAYS', 'MONTHS', 'PCT', 'AMOUNT')),
    CONSTRAINT [CK_Obligation_CheckMode] CHECK ([CheckMode] IS NULL OR [CheckMode] IN ('OFF', 'WARN', 'BLOCK')),
    CONSTRAINT [CK_Obligation_Status] CHECK ([Status] IS NULL OR [Status] IN ('ACTIVE', 'SUSPENDED', 'ENDED')),
    CONSTRAINT [CK_Obligation_Confidence] CHECK ([Confidence] IS NULL OR [Confidence] IN ('CONFIRMED_AGAINST_ORIGINAL', 'READ_FROM_SCAN_UNVERIFIED', 'ENTERED_NO_DOCUMENT')),
    CONSTRAINT [CK_Obligation_TriggerValues_json] CHECK ([TriggerValues] IS NULL OR ISJSON([TriggerValues]) = 1)
);
GO
-- AppliesToCompanyIds -- جدول وسيط جديد؛ الحذف لصفوف مسودة المراجعة فقط (يفرضه التطبيق)
CREATE TABLE [obl].[ObligationCompany] (
    [TenantId] INT NOT NULL,
    [ObligationId] BIGINT NOT NULL,
    [CompanyId] BIGINT NOT NULL,
    [CreatedAt] DATETIME2(3) NOT NULL CONSTRAINT [DF_ObligationCompany_CreatedAt] DEFAULT SYSUTCDATETIME(),
    [CreatedBy] BIGINT NULL,
    [UpdatedAt] DATETIME2(3) NULL,
    [UpdatedBy] BIGINT NULL,
    CONSTRAINT [PK_ObligationCompany] PRIMARY KEY CLUSTERED ([TenantId], [ObligationId], [CompanyId])
);
GO
-- قاعدة استحقاق تقرير/إخطار 1:1 مع Obligation (FR-OBL-002/003، BR-OBL-002، V-OBL-01)
CREATE TABLE [obl].[ReportingObligation] (
    [TenantId] INT NOT NULL,
    [ReportingObligationId] BIGINT IDENTITY(1,1) NOT NULL,
    [ObligationId] BIGINT NOT NULL,
    [Frequency] VARCHAR(11) NOT NULL,
    [AnchorKind] VARCHAR(21) NOT NULL,
    [OffsetValue] INT NULL,
    [OffsetUnit] VARCHAR(13) NOT NULL CONSTRAINT [DF_ReportingObligation_OffsetUnit] DEFAULT 'CALENDAR_DAYS',
    [FixedDueDate] DATE NULL,
    [Direction] VARCHAR(10) NOT NULL,
    [DocumentBasis] VARCHAR(14) NOT NULL,
    [StatementScope] VARCHAR(12) NULL,
    [SubmissionChannelId] INT NULL,
    [ChannelNote] NVARCHAR(300) NULL,
    [AlertLeadDays] VARCHAR(40) NULL CONSTRAINT [DF_ReportingObligation_AlertLeadDays] DEFAULT '30,14,7,3,1',
    [FirstPeriodEnd] DATE NULL,
    [HorizonMonths] INT NULL CONSTRAINT [DF_ReportingObligation_HorizonMonths] DEFAULT 24,
    [ExpectsEvidence] BIT NOT NULL,
    [FromRevision] INT NOT NULL CONSTRAINT [DF_ReportingObligation_FromRevision] DEFAULT 1,
    [ToRevision] INT NULL,
    [SupersedesId] BIGINT NULL,
    [CreatedAt] DATETIME2(3) NOT NULL CONSTRAINT [DF_ReportingObligation_CreatedAt] DEFAULT SYSUTCDATETIME(),
    [CreatedBy] BIGINT NULL,
    [UpdatedAt] DATETIME2(3) NULL,
    [UpdatedBy] BIGINT NULL,
    [RowVersion] ROWVERSION NOT NULL,
    CONSTRAINT [PK_ReportingObligation] PRIMARY KEY CLUSTERED ([ReportingObligationId]),
    CONSTRAINT [UQ_ReportingObligation_Tenant] UNIQUE ([TenantId], [ReportingObligationId]),
    CONSTRAINT [CK_ReportingObligation_1] CHECK (AnchorKind <> 'FIXED_DATE' OR (FixedDueDate IS NOT NULL AND OffsetValue IS NULL)),
    CONSTRAINT [CK_ReportingObligation_2] CHECK (AnchorKind = 'FIXED_DATE' OR (FixedDueDate IS NULL AND OffsetValue IS NOT NULL)),
    CONSTRAINT [CK_ReportingObligation_3] CHECK (OffsetValue IS NULL OR OffsetValue >= 0),
    CONSTRAINT [CK_ReportingObligation_4] CHECK (HorizonMonths IS NULL OR HorizonMonths > 0),
    CONSTRAINT [CK_ReportingObligation_5] CHECK (Frequency <> 'EVENT_BASED' OR AnchorKind IN ('BEFORE_EVENT','AFTER_EVENT')),
    CONSTRAINT [CK_ReportingObligation_6] CHECK (AnchorKind NOT IN ('BEFORE_EVENT','AFTER_EVENT') OR Frequency = 'EVENT_BASED'),
    CONSTRAINT [CK_ReportingObligation_7] CHECK (Frequency <> 'ON_DEMAND' OR AnchorKind = 'ON_DEMAND_REQUEST'),
    CONSTRAINT [CK_ReportingObligation_8] CHECK (AnchorKind <> 'ON_DEMAND_REQUEST' OR Frequency = 'ON_DEMAND'),
    CONSTRAINT [CK_ReportingObligation_9] CHECK (AlertLeadDays IS NULL OR AlertLeadDays NOT LIKE '%[^0-9,]%'),
    CONSTRAINT [CK_ReportingObligation_10] CHECK (ToRevision IS NULL OR ToRevision >= FromRevision),
    CONSTRAINT [CK_ReportingObligation_Frequency] CHECK ([Frequency] IS NULL OR [Frequency] IN ('ANNUAL', 'SEMIANNUAL', 'QUARTERLY', 'MONTHLY', 'ONE_TIME', 'EVENT_BASED', 'ON_DEMAND')),
    CONSTRAINT [CK_ReportingObligation_AnchorKind] CHECK ([AnchorKind] IS NULL OR [AnchorKind] IN ('AFTER_PERIOD_END', 'AFTER_FISCAL_YEAR_END', 'BEFORE_EVENT', 'AFTER_EVENT', 'ON_DEMAND_REQUEST', 'FIXED_DATE')),
    CONSTRAINT [CK_ReportingObligation_OffsetUnit] CHECK ([OffsetUnit] IS NULL OR [OffsetUnit] IN ('CALENDAR_DAYS', 'BUSINESS_DAYS', 'MONTHS')),
    CONSTRAINT [CK_ReportingObligation_Direction] CHECK ([Direction] IS NULL OR [Direction] IN ('WE_SUBMIT', 'WE_RESPOND')),
    CONSTRAINT [CK_ReportingObligation_DocumentBasis] CHECK ([DocumentBasis] IS NULL OR [DocumentBasis] IN ('AUDITED', 'INTERNAL', 'ANY', 'NOT_APPLICABLE')),
    CONSTRAINT [CK_ReportingObligation_StatementScope] CHECK ([StatementScope] IS NULL OR [StatementScope] IN ('STANDALONE', 'CONSOLIDATED', 'ANY'))
);
GO
-- بند أجندة مولَّد أو مسجَّل لحدث (FR-OBL-003..005، BR-OBL-003، §8)؛ DUE_SOON/OVERDUE مشتقتان
CREATE TABLE [obl].[ReportingInstance] (
    [TenantId] INT NOT NULL,
    [ReportingInstanceId] BIGINT IDENTITY(1,1) NOT NULL,
    [ReportingObligationId] BIGINT NOT NULL,
    [PeriodStart] DATE NULL,
    [PeriodEnd] DATE NULL,
    [EventDate] DATE NULL,
    [DueDate] DATE NOT NULL,
    [DueDateOverrideReason] NVARCHAR(500) NULL,
    [Status] VARCHAR(14) NOT NULL CONSTRAINT [DF_ReportingInstance_Status] DEFAULT 'SCHEDULED',
    [StatusReason] NVARCHAR(500) NULL,
    [SubmittedOn] DATE NULL,
    [SubmissionChannelUsedId] INT NULL,
    [SubmissionRef] NVARCHAR(100) NULL,
    [EvidenceDocumentId] BIGINT NULL,
    [ReportedAmount] DECIMAL(19,4) NULL,
    [CurrencyId] INT NULL,
    [GeneratedBy] VARCHAR(12) NOT NULL CONSTRAINT [DF_ReportingInstance_GeneratedBy] DEFAULT 'JOB',
    [PublicId] UNIQUEIDENTIFIER NOT NULL CONSTRAINT [DF_ReportingInstance_PublicId] DEFAULT NEWSEQUENTIALID(),
    [CreatedAt] DATETIME2(3) NOT NULL CONSTRAINT [DF_ReportingInstance_CreatedAt] DEFAULT SYSUTCDATETIME(),
    [CreatedBy] BIGINT NULL,
    [UpdatedAt] DATETIME2(3) NULL,
    [UpdatedBy] BIGINT NULL,
    [RowVersion] ROWVERSION NOT NULL,
    CONSTRAINT [PK_ReportingInstance] PRIMARY KEY CLUSTERED ([ReportingInstanceId]),
    CONSTRAINT [UQ_ReportingInstance_Tenant] UNIQUE ([TenantId], [ReportingInstanceId]),
    CONSTRAINT [UQ_ReportingInstance_PublicId] UNIQUE ([PublicId]),
    CONSTRAINT [CK_ReportingInstance_1] CHECK (PeriodStart IS NULL OR (PeriodEnd IS NOT NULL AND PeriodEnd >= PeriodStart)),
    CONSTRAINT [CK_ReportingInstance_2] CHECK (GeneratedBy <> 'MANUAL_EVENT' OR EventDate IS NOT NULL),
    CONSTRAINT [CK_ReportingInstance_3] CHECK (Status <> 'SUBMITTED' OR SubmittedOn IS NOT NULL),
    CONSTRAINT [CK_ReportingInstance_4] CHECK (Status = 'SUBMITTED' OR (SubmittedOn IS NULL AND SubmissionChannelUsedId IS NULL AND SubmissionRef IS NULL)),
    CONSTRAINT [CK_ReportingInstance_5] CHECK (Status NOT IN ('NOT_APPLICABLE','CANCELLED') OR StatusReason IS NOT NULL),
    CONSTRAINT [CK_ReportingInstance_6] CHECK (ReportedAmount IS NULL OR CurrencyId IS NOT NULL),
    CONSTRAINT [CK_ReportingInstance_7] CHECK (CurrencyId IS NULL OR ReportedAmount IS NOT NULL),
    CONSTRAINT [CK_ReportingInstance_Status] CHECK ([Status] IS NULL OR [Status] IN ('SCHEDULED', 'SUBMITTED', 'WAIVED', 'NOT_APPLICABLE', 'CANCELLED')),
    CONSTRAINT [CK_ReportingInstance_GeneratedBy] CHECK ([GeneratedBy] IS NULL OR [GeneratedBy] IN ('JOB', 'MANUAL_EVENT'))
);
GO
-- نسخة تعهد بتواريخ؛ الحدود المتدرجة = عدة نسخ (FR-OBL-006، BR-OBL-001/005/006، Q-OBL-01)
CREATE TABLE [obl].[Covenant] (
    [TenantId] INT NOT NULL,
    [CovenantId] BIGINT IDENTITY(1,1) NOT NULL,
    [ObligationId] BIGINT NOT NULL,
    [MeasureKind] VARCHAR(18) NOT NULL,
    [FormulaId] BIGINT NULL,
    [Operator] VARCHAR(10) NULL,
    [ThresholdState] VARCHAR(26) NOT NULL,
    [ThresholdValue] DECIMAL(19,6) NULL,
    [ThresholdUnit] VARCHAR(10) NULL,
    [CurrencyId] INT NULL,
    [TestFrequency] VARCHAR(11) NOT NULL,
    [AggregationMode] VARCHAR(14) NULL,
    [AnnualWindowBasis] VARCHAR(13) NULL,
    [StatementBasis] VARCHAR(12) NULL,
    [RequiredAssurance] VARCHAR(14) NULL,
    [RevenueBasisRule] VARCHAR(15) NULL,
    [AccountScopeKind] VARCHAR(28) NULL,
    [TestedCompanyId] BIGINT NOT NULL,
    [SubmissionLagDays] INT NULL,
    [FirstTestPeriodEnd] DATE NOT NULL,
    [EarlyWarningPct] DECIMAL(9,6) NULL,
    [ValidFrom] DATE NOT NULL,
    [ValidTo] DATE NULL,
    [FromRevision] INT NOT NULL CONSTRAINT [DF_Covenant_FromRevision] DEFAULT 1,
    [ToRevision] INT NULL,
    [SupersedesId] BIGINT NULL,
    [CreatedAt] DATETIME2(3) NOT NULL CONSTRAINT [DF_Covenant_CreatedAt] DEFAULT SYSUTCDATETIME(),
    [CreatedBy] BIGINT NULL,
    [UpdatedAt] DATETIME2(3) NULL,
    [UpdatedBy] BIGINT NULL,
    [RowVersion] ROWVERSION NOT NULL,
    CONSTRAINT [PK_Covenant] PRIMARY KEY CLUSTERED ([CovenantId]),
    CONSTRAINT [UQ_Covenant_Tenant] UNIQUE ([TenantId], [CovenantId]),
    CONSTRAINT [CK_Covenant_1] CHECK (MeasureKind NOT IN ('RATIO','AMOUNT','PERCENT_OF_REVENUE') OR FormulaId IS NOT NULL),
    CONSTRAINT [CK_Covenant_2] CHECK (MeasureKind <> 'NONE' OR (FormulaId IS NULL AND Operator IS NULL AND ThresholdValue IS NULL AND ThresholdState <> 'SET')),
    CONSTRAINT [CK_Covenant_3] CHECK (ThresholdState <> 'SET' OR (Operator IS NOT NULL AND ThresholdValue IS NOT NULL)),
    CONSTRAINT [CK_Covenant_4] CHECK (ThresholdState = 'SET' OR ThresholdValue IS NULL),
    CONSTRAINT [CK_Covenant_5] CHECK (ThresholdState <> 'SET' OR ThresholdUnit IS NULL OR ThresholdUnit <> 'AMOUNT' OR CurrencyId IS NOT NULL),
    CONSTRAINT [CK_Covenant_6] CHECK (CurrencyId IS NULL OR ThresholdUnit = 'AMOUNT'),
    CONSTRAINT [CK_Covenant_7] CHECK (RevenueBasisRule IS NULL OR MeasureKind = 'PERCENT_OF_REVENUE'),
    CONSTRAINT [CK_Covenant_8] CHECK (SubmissionLagDays IS NULL OR SubmissionLagDays >= 0),
    CONSTRAINT [CK_Covenant_9] CHECK (EarlyWarningPct IS NULL OR (EarlyWarningPct >= 0 AND EarlyWarningPct <= 100)),
    CONSTRAINT [CK_Covenant_10] CHECK (ValidTo IS NULL OR ValidTo >= ValidFrom),
    CONSTRAINT [CK_Covenant_11] CHECK (ToRevision IS NULL OR ToRevision >= FromRevision),
    CONSTRAINT [CK_Covenant_MeasureKind] CHECK ([MeasureKind] IS NULL OR [MeasureKind] IN ('RATIO', 'AMOUNT', 'PERCENT_OF_REVENUE', 'AVERAGE_BALANCE', 'FLOW_VOLUME', 'NONE')),
    CONSTRAINT [CK_Covenant_Operator] CHECK ([Operator] IS NULL OR [Operator] IN ('GE', 'LE', 'GT', 'LT', 'EQ')),
    CONSTRAINT [CK_Covenant_ThresholdState] CHECK ([ThresholdState] IS NULL OR [ThresholdState] IN ('SET', 'NOT_SPECIFIED_IN_AGREEMENT', 'TO_BE_DETERMINED')),
    CONSTRAINT [CK_Covenant_ThresholdUnit] CHECK ([ThresholdUnit] IS NULL OR [ThresholdUnit] IN ('RATIO', 'AMOUNT', 'PERCENT')),
    CONSTRAINT [CK_Covenant_TestFrequency] CHECK ([TestFrequency] IS NULL OR [TestFrequency] IN ('MONTHLY', 'QUARTERLY', 'SEMIANNUAL', 'ANNUAL', 'ROLLING_12M')),
    CONSTRAINT [CK_Covenant_AggregationMode] CHECK ([AggregationMode] IS NULL OR [AggregationMode] IN ('POINT_IN_TIME', 'PERIOD_AVERAGE', 'EACH_MONTH_MIN', 'PERIOD_SUM')),
    CONSTRAINT [CK_Covenant_AnnualWindowBasis] CHECK ([AnnualWindowBasis] IS NULL OR [AnnualWindowBasis] IN ('FISCAL_YEAR', 'CALENDAR_YEAR', 'FACILITY_YEAR')),
    CONSTRAINT [CK_Covenant_StatementBasis] CHECK ([StatementBasis] IS NULL OR [StatementBasis] IN ('STANDALONE', 'CONSOLIDATED')),
    CONSTRAINT [CK_Covenant_RequiredAssurance] CHECK ([RequiredAssurance] IS NULL OR [RequiredAssurance] IN ('AUDITED_ONLY', 'PREFER_AUDITED', 'ANY')),
    CONSTRAINT [CK_Covenant_RevenueBasisRule] CHECK ([RevenueBasisRule] IS NULL OR [RevenueBasisRule] IN ('SAME_PERIOD', 'PRIOR_YEAR', 'MANUAL_ESTIMATE')),
    CONSTRAINT [CK_Covenant_AccountScopeKind] CHECK ([AccountScopeKind] IS NULL OR [AccountScopeKind] IN ('ALL_COMPANY_ACCOUNTS_AT_BANK', 'SELECTED_ACCOUNTS', 'GROUP_ACCOUNTS'))
);
GO
-- AccountIds لـ SELECTED_ACCOUNTS -- جدول وسيط جديد؛ الحذف لصفوف مسودة المراجعة فقط (يفرضه التطبيق)
CREATE TABLE [obl].[CovenantAccount] (
    [TenantId] INT NOT NULL,
    [CovenantId] BIGINT NOT NULL,
    [BankAccountId] BIGINT NOT NULL,
    [CreatedAt] DATETIME2(3) NOT NULL CONSTRAINT [DF_CovenantAccount_CreatedAt] DEFAULT SYSUTCDATETIME(),
    [CreatedBy] BIGINT NULL,
    [UpdatedAt] DATETIME2(3) NULL,
    [UpdatedBy] BIGINT NULL,
    CONSTRAINT [PK_CovenantAccount] PRIMARY KEY CLUSTERED ([TenantId], [CovenantId], [BankAccountId])
);
GO
-- تقييم تعهد لفترة وإصدار تقييم؛ المخزَّن لا يُعدَّل (FR-OBL-011، FR-FIN-012/013، BR-OBL-006/007، §8)
CREATE TABLE [obl].[CovenantTest] (
    [TenantId] INT NOT NULL,
    [CovenantTestId] BIGINT IDENTITY(1,1) NOT NULL,
    [CovenantId] BIGINT NOT NULL,
    [PeriodStart] DATE NOT NULL,
    [PeriodEnd] DATE NOT NULL,
    [DueDate] DATE NOT NULL,
    [EvaluationNo] INT NOT NULL CONSTRAINT [DF_CovenantTest_EvaluationNo] DEFAULT 1,
    [State] VARCHAR(12) NOT NULL CONSTRAINT [DF_CovenantTest_State] DEFAULT 'SCHEDULED',
    [Result] VARCHAR(25) NULL,
    [Method] VARCHAR(13) NOT NULL,
    [ActualValue] DECIMAL(19,6) NULL,
    [ThresholdApplied] DECIMAL(19,6) NULL,
    [OperatorApplied] VARCHAR(10) NULL,
    [Headroom] DECIMAL(19,6) NULL,
    [HeadroomPct] DECIMAL(19,6) NULL,
    [InputsSnapshot] NVARCHAR(MAX) NULL,
    [FormulaVersion] INT NULL,
    [EvaluatedAt] DATETIME2(3) NULL,
    [EvaluatedBy] BIGINT NULL,
    [EvidenceDocumentId] BIGINT NULL,
    [ReviewNote] NVARCHAR(1000) NULL,
    [ReviewedBy] BIGINT NULL,
    [ReviewedOn] DATETIME2(3) NULL,
    [NextReviewOn] DATE NULL,
    [PublicId] UNIQUEIDENTIFIER NOT NULL CONSTRAINT [DF_CovenantTest_PublicId] DEFAULT NEWSEQUENTIALID(),
    [CreatedAt] DATETIME2(3) NOT NULL CONSTRAINT [DF_CovenantTest_CreatedAt] DEFAULT SYSUTCDATETIME(),
    [CreatedBy] BIGINT NULL,
    [UpdatedAt] DATETIME2(3) NULL,
    [UpdatedBy] BIGINT NULL,
    [RowVersion] ROWVERSION NOT NULL,
    CONSTRAINT [PK_CovenantTest] PRIMARY KEY CLUSTERED ([CovenantTestId]),
    CONSTRAINT [UQ_CovenantTest_Tenant] UNIQUE ([TenantId], [CovenantTestId]),
    CONSTRAINT [UQ_CovenantTest_PublicId] UNIQUE ([PublicId]),
    CONSTRAINT [UQ_CovenantTest_CovenantId_PeriodEnd_EvaluationNo] UNIQUE ([TenantId], [CovenantId], [PeriodEnd], [EvaluationNo]),
    CONSTRAINT [CK_CovenantTest_1] CHECK (EvaluationNo >= 1),
    CONSTRAINT [CK_CovenantTest_2] CHECK (PeriodEnd >= PeriodStart),
    CONSTRAINT [CK_CovenantTest_3] CHECK (DueDate >= PeriodEnd),
    CONSTRAINT [CK_CovenantTest_4] CHECK (State <> 'SCHEDULED' OR (Result IS NULL AND EvaluatedAt IS NULL)),
    CONSTRAINT [CK_CovenantTest_5] CHECK (State NOT IN ('EVALUATED','REVIEWED') OR (Result IS NOT NULL AND EvaluatedAt IS NOT NULL AND InputsSnapshot IS NOT NULL)),
    CONSTRAINT [CK_CovenantTest_6] CHECK (State <> 'REVIEWED' OR (ReviewedBy IS NOT NULL AND ReviewedOn IS NOT NULL)),
    CONSTRAINT [CK_CovenantTest_7] CHECK (Result NOT IN ('COMPLIANT','WARNING','BREACH') OR (ActualValue IS NOT NULL AND ThresholdApplied IS NOT NULL AND OperatorApplied IS NOT NULL)),
    CONSTRAINT [CK_CovenantTest_8] CHECK (Result <> 'NOT_ASSESSED_NO_THRESHOLD' OR ThresholdApplied IS NULL),
    CONSTRAINT [CK_CovenantTest_9] CHECK (ThresholdApplied IS NULL OR OperatorApplied IS NOT NULL),
    CONSTRAINT [CK_CovenantTest_10] CHECK (Headroom IS NULL OR (ActualValue IS NOT NULL AND ThresholdApplied IS NOT NULL)),
    CONSTRAINT [CK_CovenantTest_11] CHECK (HeadroomPct IS NULL OR Headroom IS NOT NULL),
    CONSTRAINT [CK_CovenantTest_12] CHECK (Result NOT IN ('MANUAL_COMPLIANT','MANUAL_NON_COMPLIANT','UNDER_REVIEW') OR Method = 'MANUAL_STATUS'),
    CONSTRAINT [CK_CovenantTest_13] CHECK (Method <> 'MANUAL_STATUS' OR Result IS NULL OR Result IN ('MANUAL_COMPLIANT','MANUAL_NON_COMPLIANT','UNDER_REVIEW')),
    CONSTRAINT [CK_CovenantTest_14] CHECK (FormulaVersion IS NULL OR FormulaVersion >= 1),
    CONSTRAINT [CK_CovenantTest_State] CHECK ([State] IS NULL OR [State] IN ('SCHEDULED', 'PENDING_DATA', 'EVALUATED', 'REVIEWED')),
    CONSTRAINT [CK_CovenantTest_Result] CHECK ([Result] IS NULL OR [Result] IN ('COMPLIANT', 'WARNING', 'BREACH', 'MISSING_DATA', 'NOT_ASSESSED_NO_THRESHOLD', 'NOT_COMPARABLE', 'MANUAL_COMPLIANT', 'MANUAL_NON_COMPLIANT', 'UNDER_REVIEW')),
    CONSTRAINT [CK_CovenantTest_Method] CHECK ([Method] IS NULL OR [Method] IN ('AUTO', 'MANUAL_VALUE', 'MANUAL_STATUS')),
    CONSTRAINT [CK_CovenantTest_OperatorApplied] CHECK ([OperatorApplied] IS NULL OR [OperatorApplied] IN ('GE', 'LE', 'GT', 'LT', 'EQ')),
    CONSTRAINT [CK_CovenantTest_InputsSnapshot_json] CHECK ([InputsSnapshot] IS NULL OR ISJSON([InputsSnapshot]) = 1)
);
GO
-- سجل خرق وعلاجه وتنازله (FR-OBL-012، BR-OBL-009/011، §8)
CREATE TABLE [obl].[ObligationBreach] (
    [TenantId] INT NOT NULL,
    [ObligationBreachId] BIGINT IDENTITY(1,1) NOT NULL,
    [ObligationId] BIGINT NOT NULL,
    [Kind] VARCHAR(21) NOT NULL,
    [CovenantTestId] BIGINT NULL,
    [ReportingInstanceId] BIGINT NULL,
    [DetectedOn] DATE NOT NULL,
    [Description] NVARCHAR(2000) NULL,
    [Status] VARCHAR(16) NOT NULL CONSTRAINT [DF_ObligationBreach_Status] DEFAULT 'OPEN',
    [CureDeadline] DATE NULL,
    [BankNotifiedOn] DATE NULL,
    [WaiverRef] NVARCHAR(100) NULL,
    [WaiverDate] DATE NULL,
    [WaiverBankContactId] BIGINT NULL,
    [WaiverConditions] NVARCHAR(2000) NULL,
    [WaiverValidUntil] DATE NULL,
    [WaiverDocumentId] BIGINT NULL,
    [ConsequenceApplied] NVARCHAR(1000) NULL,
    [ResolvedOn] DATE NULL,
    [NeedsReview] BIT NOT NULL CONSTRAINT [DF_ObligationBreach_NeedsReview] DEFAULT 0,
    [PublicId] UNIQUEIDENTIFIER NOT NULL CONSTRAINT [DF_ObligationBreach_PublicId] DEFAULT NEWSEQUENTIALID(),
    [CreatedAt] DATETIME2(3) NOT NULL CONSTRAINT [DF_ObligationBreach_CreatedAt] DEFAULT SYSUTCDATETIME(),
    [CreatedBy] BIGINT NULL,
    [UpdatedAt] DATETIME2(3) NULL,
    [UpdatedBy] BIGINT NULL,
    [RowVersion] ROWVERSION NOT NULL,
    CONSTRAINT [PK_ObligationBreach] PRIMARY KEY CLUSTERED ([ObligationBreachId]),
    CONSTRAINT [UQ_ObligationBreach_Tenant] UNIQUE ([TenantId], [ObligationBreachId]),
    CONSTRAINT [UQ_ObligationBreach_PublicId] UNIQUE ([PublicId]),
    CONSTRAINT [CK_ObligationBreach_1] CHECK (CovenantTestId IS NULL OR Kind = 'COVENANT_BREACH'),
    CONSTRAINT [CK_ObligationBreach_2] CHECK (ReportingInstanceId IS NULL OR Kind = 'LATE_REPORT'),
    CONSTRAINT [CK_ObligationBreach_3] CHECK (CureDeadline IS NULL OR CureDeadline >= DetectedOn),
    CONSTRAINT [CK_ObligationBreach_4] CHECK (Status <> 'IN_CURE' OR CureDeadline IS NOT NULL),
    CONSTRAINT [CK_ObligationBreach_5] CHECK (Status NOT IN ('CURED','WAIVED','CLOSED_NO_ACTION') OR ResolvedOn IS NOT NULL),
    CONSTRAINT [CK_ObligationBreach_6] CHECK (Status IN ('CURED','WAIVED','CLOSED_NO_ACTION') OR ResolvedOn IS NULL),
    CONSTRAINT [CK_ObligationBreach_7] CHECK (ResolvedOn IS NULL OR ResolvedOn >= DetectedOn),
    CONSTRAINT [CK_ObligationBreach_8] CHECK (Status <> 'WAIVED' OR (WaiverRef IS NOT NULL AND WaiverDate IS NOT NULL AND WaiverBankContactId IS NOT NULL)),
    CONSTRAINT [CK_ObligationBreach_9] CHECK (Status = 'WAIVED' OR (WaiverRef IS NULL AND WaiverDate IS NULL AND WaiverBankContactId IS NULL AND WaiverConditions IS NULL AND WaiverValidUntil IS NULL AND WaiverDocumentId IS NULL)),
    CONSTRAINT [CK_ObligationBreach_10] CHECK (WaiverValidUntil IS NULL OR WaiverDate IS NULL OR WaiverValidUntil >= WaiverDate),
    CONSTRAINT [CK_ObligationBreach_Kind] CHECK ([Kind] IS NULL OR [Kind] IN ('COVENANT_BREACH', 'LATE_REPORT', 'RESTRICTION_VIOLATION', 'OTHER')),
    CONSTRAINT [CK_ObligationBreach_Status] CHECK ([Status] IS NULL OR [Status] IN ('OPEN', 'IN_CURE', 'CURED', 'WAIVED', 'CLOSED_NO_ACTION'))
);
GO

-- ===== schema fin =====
-- بند معياري للقوائم؛ 39 بندًا مبذورًا؛ النظامي في الصيغ لا يُحذف (FR-FIN-001، CatalogBase)
CREATE TABLE [fin].[LineCatalogItem] (
    [TenantId] INT NOT NULL,
    [LineCatalogItemId] INT IDENTITY(1,1) NOT NULL,
    [Code] VARCHAR(80) NOT NULL,
    [NameAr] NVARCHAR(200) NOT NULL,
    [NameEn] NVARCHAR(200) NULL,
    [Description] NVARCHAR(500) NULL,
    [IsActive] BIT NOT NULL CONSTRAINT [DF_LineCatalogItem_IsActive] DEFAULT 1,
    [IsSystem] BIT NOT NULL CONSTRAINT [DF_LineCatalogItem_IsSystem] DEFAULT 0,
    [IsLocked] BIT NOT NULL CONSTRAINT [DF_LineCatalogItem_IsLocked] DEFAULT 0,
    [SortOrder] INT NOT NULL CONSTRAINT [DF_LineCatalogItem_SortOrder] DEFAULT 0,
    [SeedKey] VARCHAR(80) NULL,
    [ExternalCode] VARCHAR(80) NULL,
    [Section] VARCHAR(12) NOT NULL,
    [IsTotal] BIT NOT NULL CONSTRAINT [DF_LineCatalogItem_IsTotal] DEFAULT 0,
    [TotalFormula] NVARCHAR(500) NULL,
    [IsRequired] BIT NOT NULL CONSTRAINT [DF_LineCatalogItem_IsRequired] DEFAULT 0,
    [CreatedAt] DATETIME2(3) NOT NULL CONSTRAINT [DF_LineCatalogItem_CreatedAt] DEFAULT SYSUTCDATETIME(),
    [CreatedBy] BIGINT NULL,
    [UpdatedAt] DATETIME2(3) NULL,
    [UpdatedBy] BIGINT NULL,
    [RowVersion] ROWVERSION NOT NULL,
    CONSTRAINT [PK_LineCatalogItem] PRIMARY KEY CLUSTERED ([LineCatalogItemId]),
    CONSTRAINT [UQ_LineCatalogItem_Tenant] UNIQUE ([TenantId], [LineCatalogItemId]),
    CONSTRAINT [UQ_LineCatalogItem_Code] UNIQUE ([TenantId], [Code]),
    CONSTRAINT [CK_LineCatalogItem_1] CHECK (IsTotal = 0 OR TotalFormula IS NOT NULL),
    CONSTRAINT [CK_LineCatalogItem_2] CHECK (IsTotal = 1 OR TotalFormula IS NULL),
    CONSTRAINT [CK_LineCatalogItem_3] CHECK (NameEn IS NOT NULL),
    CONSTRAINT [CK_LineCatalogItem_4] CHECK (Code NOT LIKE '%[^A-Z0-9_]%' AND Code NOT LIKE '[0-9_]%'),
    CONSTRAINT [CK_LineCatalogItem_5] CHECK (IsLocked = 0 OR (IsSystem = 1 AND IsActive = 1)),
    CONSTRAINT [CK_LineCatalogItem_Section] CHECK ([Section] IS NULL OR [Section] IN ('BS_ASSET', 'BS_LIABILITY', 'BS_EQUITY', 'IS', 'CF'))
);
GO
-- الأسماء البديلة للبند (Aliases) للصق والمطابقة -- جدول جديد للأسماء البديلة (FR-FIN-003)
CREATE TABLE [fin].[LineCatalogItemAlias] (
    [TenantId] INT NOT NULL,
    [LineCatalogItemAliasId] INT IDENTITY(1,1) NOT NULL,
    [LineCatalogItemId] INT NOT NULL,
    [Alias] NVARCHAR(200) NOT NULL,
    [CreatedAt] DATETIME2(3) NOT NULL CONSTRAINT [DF_LineCatalogItemAlias_CreatedAt] DEFAULT SYSUTCDATETIME(),
    [CreatedBy] BIGINT NULL,
    [UpdatedAt] DATETIME2(3) NULL,
    [UpdatedBy] BIGINT NULL,
    [RowVersion] ROWVERSION NOT NULL,
    CONSTRAINT [PK_LineCatalogItemAlias] PRIMARY KEY CLUSTERED ([LineCatalogItemAliasId]),
    CONSTRAINT [UQ_LineCatalogItemAlias_Tenant] UNIQUE ([TenantId], [LineCatalogItemAliasId]),
    CONSTRAINT [UQ_LineCatalogItemAlias_Alias] UNIQUE ([TenantId], [Alias]),
    CONSTRAINT [CK_LineCatalogItemAlias_1] CHECK (Alias <> '')
);
GO
-- رأس قائمة مالية؛ سري جدًا (FR-FIN-002/005/006، BR-FIN-001..004، §8)
CREATE TABLE [fin].[FinancialStatement] (
    [TenantId] INT NOT NULL,
    [FinancialStatementId] BIGINT IDENTITY(1,1) NOT NULL,
    [CompanyId] BIGINT NOT NULL,
    [PeriodType] VARCHAR(10) NOT NULL,
    [PeriodStart] DATE NULL,
    [PeriodEnd] DATE NOT NULL,
    [FiscalYear] INT NOT NULL,
    [Basis] VARCHAR(12) NOT NULL,
    [Assurance] VARCHAR(10) NOT NULL,
    [CurrencyId] INT NOT NULL,
    [UnitScale] INT NOT NULL CONSTRAINT [DF_FinancialStatement_UnitScale] DEFAULT 1,
    [AccountingStandard] NVARCHAR(100) NULL,
    [VersionNo] INT NOT NULL CONSTRAINT [DF_FinancialStatement_VersionNo] DEFAULT 1,
    [VersionReason] VARCHAR(10) NOT NULL CONSTRAINT [DF_FinancialStatement_VersionReason] DEFAULT 'ORIGINAL',
    [SupersedesId] BIGINT NULL,
    [Status] VARCHAR(10) NOT NULL CONSTRAINT [DF_FinancialStatement_Status] DEFAULT 'DRAFT',
    [EntryMethod] VARCHAR(10) NOT NULL,
    [BalanceReason] NVARCHAR(500) NULL,
    [SourceDocumentId] BIGINT NULL,
    [PreparedBy] BIGINT NULL,
    [PreparedOn] DATETIME2(3) NULL,
    [ApprovedBy] BIGINT NULL,
    [ApprovedOn] DATETIME2(3) NULL,
    [PublicId] UNIQUEIDENTIFIER NOT NULL CONSTRAINT [DF_FinancialStatement_PublicId] DEFAULT NEWSEQUENTIALID(),
    [CreatedAt] DATETIME2(3) NOT NULL CONSTRAINT [DF_FinancialStatement_CreatedAt] DEFAULT SYSUTCDATETIME(),
    [CreatedBy] BIGINT NULL,
    [UpdatedAt] DATETIME2(3) NULL,
    [UpdatedBy] BIGINT NULL,
    [RowVersion] ROWVERSION NOT NULL,
    CONSTRAINT [PK_FinancialStatement] PRIMARY KEY CLUSTERED ([FinancialStatementId]),
    CONSTRAINT [UQ_FinancialStatement_Tenant] UNIQUE ([TenantId], [FinancialStatementId]),
    CONSTRAINT [UQ_FinancialStatement_PublicId] UNIQUE ([PublicId]),
    CONSTRAINT [UQ_FinancialStatement_CompanyId_PeriodType_PeriodEnd_Basis_Assurance_VersionNo] UNIQUE ([TenantId], [CompanyId], [PeriodType], [PeriodEnd], [Basis], [Assurance], [VersionNo]),
    CONSTRAINT [CK_FinancialStatement_1] CHECK (UnitScale IN (1,1000,1000000)),
    CONSTRAINT [CK_FinancialStatement_2] CHECK (PeriodStart IS NULL OR PeriodEnd >= PeriodStart),
    CONSTRAINT [CK_FinancialStatement_3] CHECK (FiscalYear BETWEEN 1900 AND 2200),
    CONSTRAINT [CK_FinancialStatement_4] CHECK (VersionNo >= 1),
    CONSTRAINT [CK_FinancialStatement_5] CHECK (VersionReason <> 'ORIGINAL' OR SupersedesId IS NULL),
    CONSTRAINT [CK_FinancialStatement_6] CHECK (SupersedesId IS NULL OR (VersionNo > 1 AND VersionReason <> 'ORIGINAL' AND SupersedesId <> FinancialStatementId)),
    CONSTRAINT [CK_FinancialStatement_7] CHECK (Status NOT IN ('SUBMITTED','APPROVED','SUPERSEDED') OR (PreparedBy IS NOT NULL AND PreparedOn IS NOT NULL)),
    CONSTRAINT [CK_FinancialStatement_8] CHECK (Status NOT IN ('APPROVED','SUPERSEDED') OR (ApprovedBy IS NOT NULL AND ApprovedOn IS NOT NULL)),
    CONSTRAINT [CK_FinancialStatement_PeriodType] CHECK ([PeriodType] IS NULL OR [PeriodType] IN ('ANNUAL', 'SEMIANNUAL', 'QUARTERLY', 'MONTHLY')),
    CONSTRAINT [CK_FinancialStatement_Basis] CHECK ([Basis] IS NULL OR [Basis] IN ('STANDALONE', 'CONSOLIDATED')),
    CONSTRAINT [CK_FinancialStatement_Assurance] CHECK ([Assurance] IS NULL OR [Assurance] IN ('AUDITED', 'REVIEWED', 'MANAGEMENT')),
    CONSTRAINT [CK_FinancialStatement_VersionReason] CHECK ([VersionReason] IS NULL OR [VersionReason] IN ('ORIGINAL', 'RESTATED', 'CORRECTION')),
    CONSTRAINT [CK_FinancialStatement_Status] CHECK ([Status] IS NULL OR [Status] IN ('DRAFT', 'SUBMITTED', 'APPROVED', 'SUPERSEDED', 'REJECTED')),
    CONSTRAINT [CK_FinancialStatement_EntryMethod] CHECK ([EntryMethod] IS NULL OR [EntryMethod] IN ('MANUAL', 'PASTE'))
);
GO
-- سطر قائمة؛ بعملة الرأس والمخزَّن = المُدخل x UnitScale؛ Variance مشتق؛ سري جدًا (BR-FIN-001/002)
CREATE TABLE [fin].[StatementLine] (
    [TenantId] INT NOT NULL,
    [StatementLineId] BIGINT IDENTITY(1,1) NOT NULL,
    [StatementId] BIGINT NOT NULL,
    [LineCatalogItemId] INT NOT NULL,
    [EnteredAmount] DECIMAL(19,4) NULL,
    [ComputedAmount] DECIMAL(19,4) NULL,
    [CreatedAt] DATETIME2(3) NOT NULL CONSTRAINT [DF_StatementLine_CreatedAt] DEFAULT SYSUTCDATETIME(),
    [CreatedBy] BIGINT NULL,
    [UpdatedAt] DATETIME2(3) NULL,
    [UpdatedBy] BIGINT NULL,
    [RowVersion] ROWVERSION NOT NULL,
    CONSTRAINT [PK_StatementLine] PRIMARY KEY CLUSTERED ([StatementLineId]),
    CONSTRAINT [UQ_StatementLine_Tenant] UNIQUE ([TenantId], [StatementLineId]),
    CONSTRAINT [UQ_StatementLine_StatementId_LineCatalogItemId] UNIQUE ([TenantId], [StatementId], [LineCatalogItemId])
);
GO
-- رصيد شهري لحساب بعملة الحساب (FR-FIN-008، BR-FIN-005/006، V-FIN-02)
CREATE TABLE [fin].[AccountMonthlyStat] (
    [TenantId] INT NOT NULL,
    [AccountMonthlyStatId] BIGINT IDENTITY(1,1) NOT NULL,
    [BankAccountId] BIGINT NOT NULL,
    [MonthEnd] DATE NOT NULL,
    [AvgDailyBalance] DECIMAL(19,4) NOT NULL,
    [MinBalance] DECIMAL(19,4) NULL,
    [EndBalance] DECIMAL(19,4) NULL,
    [SourceKind] VARCHAR(14) NOT NULL,
    [SourceRef] NVARCHAR(100) NULL,
    [DocumentId] BIGINT NULL,
    [Note] NVARCHAR(500) NULL,
    [Status] VARCHAR(10) NOT NULL CONSTRAINT [DF_AccountMonthlyStat_Status] DEFAULT 'DRAFT',
    [PublicId] UNIQUEIDENTIFIER NOT NULL CONSTRAINT [DF_AccountMonthlyStat_PublicId] DEFAULT NEWSEQUENTIALID(),
    [CreatedAt] DATETIME2(3) NOT NULL CONSTRAINT [DF_AccountMonthlyStat_CreatedAt] DEFAULT SYSUTCDATETIME(),
    [CreatedBy] BIGINT NULL,
    [UpdatedAt] DATETIME2(3) NULL,
    [UpdatedBy] BIGINT NULL,
    [RowVersion] ROWVERSION NOT NULL,
    CONSTRAINT [PK_AccountMonthlyStat] PRIMARY KEY CLUSTERED ([AccountMonthlyStatId]),
    CONSTRAINT [UQ_AccountMonthlyStat_Tenant] UNIQUE ([TenantId], [AccountMonthlyStatId]),
    CONSTRAINT [UQ_AccountMonthlyStat_PublicId] UNIQUE ([PublicId]),
    CONSTRAINT [UQ_AccountMonthlyStat_BankAccountId_MonthEnd] UNIQUE ([TenantId], [BankAccountId], [MonthEnd]),
    CONSTRAINT [CK_AccountMonthlyStat_SourceKind] CHECK ([SourceKind] IS NULL OR [SourceKind] IN ('BANK_STATEMENT', 'BANK_NOTICE', 'INTERNAL_CALC')),
    CONSTRAINT [CK_AccountMonthlyStat_Status] CHECK ([Status] IS NULL OR [Status] IN ('DRAFT', 'CONFIRMED'))
);
GO
-- مبلغ محوَّل للبنك في شهر؛ تجميع سنوي آلي (FR-FIN-009/010، BR-FIN-007/008)
CREATE TABLE [fin].[BankFlowEntry] (
    [TenantId] INT NOT NULL,
    [BankFlowEntryId] BIGINT IDENTITY(1,1) NOT NULL,
    [CompanyId] BIGINT NOT NULL,
    [InstitutionId] BIGINT NOT NULL,
    [FacilityId] BIGINT NULL,
    [MonthEnd] DATE NOT NULL,
    [FlowKindId] INT NOT NULL,
    [Amount] DECIMAL(19,4) NOT NULL,
    [CurrencyId] INT NOT NULL,
    [BasisNote] NVARCHAR(500) NULL,
    [DocumentId] BIGINT NULL,
    [PublicId] UNIQUEIDENTIFIER NOT NULL CONSTRAINT [DF_BankFlowEntry_PublicId] DEFAULT NEWSEQUENTIALID(),
    [CreatedAt] DATETIME2(3) NOT NULL CONSTRAINT [DF_BankFlowEntry_CreatedAt] DEFAULT SYSUTCDATETIME(),
    [CreatedBy] BIGINT NULL,
    [UpdatedAt] DATETIME2(3) NULL,
    [UpdatedBy] BIGINT NULL,
    [RowVersion] ROWVERSION NOT NULL,
    CONSTRAINT [PK_BankFlowEntry] PRIMARY KEY CLUSTERED ([BankFlowEntryId]),
    CONSTRAINT [UQ_BankFlowEntry_Tenant] UNIQUE ([TenantId], [BankFlowEntryId]),
    CONSTRAINT [UQ_BankFlowEntry_PublicId] UNIQUE ([PublicId]),
    CONSTRAINT [UQ_BankFlowEntry_CompanyId_InstitutionId_FacilityId_MonthEnd_FlowKindId] UNIQUE ([TenantId], [CompanyId], [InstitutionId], [FacilityId], [MonthEnd], [FlowKindId]),
    CONSTRAINT [CK_BankFlowEntry_1] CHECK (Amount >= 0)
);
GO
-- صيغة مقياس: قالب أو نسخة اتفاقية بإصدارات؛ لا تُنفَّذ نصًا (FR-FIN-011، BR-FIN-009، §12)
CREATE TABLE [fin].[MeasureFormula] (
    [TenantId] INT NOT NULL,
    [MeasureFormulaId] BIGINT IDENTITY(1,1) NOT NULL,
    [Code] VARCHAR(60) NOT NULL,
    [NameAr] NVARCHAR(200) NOT NULL,
    [NameEn] NVARCHAR(200) NULL,
    [Scope] VARCHAR(13) NOT NULL,
    [FacilityId] BIGINT NULL,
    [BaseTemplateId] BIGINT NULL,
    [Expression] NVARCHAR(2000) NOT NULL,
    [InputKinds] VARCHAR(40) NOT NULL,
    [ResultUnit] VARCHAR(10) NOT NULL,
    [DefinitionNote] NVARCHAR(1000) NULL,
    [VersionNo] INT NOT NULL CONSTRAINT [DF_MeasureFormula_VersionNo] DEFAULT 1,
    [Status] VARCHAR(10) NOT NULL CONSTRAINT [DF_MeasureFormula_Status] DEFAULT 'DRAFT',
    [ApprovedBy] BIGINT NULL,
    [ApprovedOn] DATETIME2(3) NULL,
    [SourceDocumentId] BIGINT NULL,
    [SourcePage] VARCHAR(40) NULL,
    [ReadFromScan] BIT NOT NULL CONSTRAINT [DF_MeasureFormula_ReadFromScan] DEFAULT 0,
    [OriginalText] NVARCHAR(2000) NULL,
    [NoSourceReason] NVARCHAR(300) NULL,
    [Confidence] VARCHAR(26) NOT NULL CONSTRAINT [DF_MeasureFormula_Confidence] DEFAULT 'ENTERED_NO_DOCUMENT',
    [VerifiedBy] BIGINT NULL,
    [VerifiedOn] DATETIME2(3) NULL,
    [ConflictId] BIGINT NULL,
    [CreatedAt] DATETIME2(3) NOT NULL CONSTRAINT [DF_MeasureFormula_CreatedAt] DEFAULT SYSUTCDATETIME(),
    [CreatedBy] BIGINT NULL,
    [UpdatedAt] DATETIME2(3) NULL,
    [UpdatedBy] BIGINT NULL,
    [RowVersion] ROWVERSION NOT NULL,
    CONSTRAINT [PK_MeasureFormula] PRIMARY KEY CLUSTERED ([MeasureFormulaId]),
    CONSTRAINT [UQ_MeasureFormula_Tenant] UNIQUE ([TenantId], [MeasureFormulaId]),
    CONSTRAINT [UQ_MeasureFormula_Code_FacilityId_VersionNo] UNIQUE ([TenantId], [Code], [FacilityId], [VersionNo]),
    CONSTRAINT [CK_MeasureFormula_1] CHECK (Scope <> 'TEMPLATE' OR FacilityId IS NULL),
    CONSTRAINT [CK_MeasureFormula_2] CHECK (Scope <> 'FACILITY_COPY' OR FacilityId IS NOT NULL),
    CONSTRAINT [CK_MeasureFormula_3] CHECK (Scope = 'FACILITY_COPY' OR BaseTemplateId IS NULL),
    CONSTRAINT [CK_MeasureFormula_4] CHECK (BaseTemplateId IS NULL OR BaseTemplateId <> MeasureFormulaId),
    CONSTRAINT [CK_MeasureFormula_5] CHECK (InputKinds <> ''),
    CONSTRAINT [CK_MeasureFormula_6] CHECK (VersionNo >= 1),
    CONSTRAINT [CK_MeasureFormula_7] CHECK (Code NOT LIKE '%[^A-Z0-9_]%'),
    CONSTRAINT [CK_MeasureFormula_8] CHECK (Status NOT IN ('APPROVED','SUPERSEDED') OR (ApprovedBy IS NOT NULL AND ApprovedOn IS NOT NULL)),
    CONSTRAINT [CK_MeasureFormula_9] CHECK (SourceDocumentId IS NOT NULL AND SourcePage IS NOT NULL OR (SourceDocumentId IS NULL AND Confidence = 'ENTERED_NO_DOCUMENT')),
    CONSTRAINT [CK_MeasureFormula_10] CHECK (Confidence <> 'CONFIRMED_AGAINST_ORIGINAL' OR (VerifiedBy IS NOT NULL AND VerifiedOn IS NOT NULL)),
    CONSTRAINT [CK_MeasureFormula_Scope] CHECK ([Scope] IS NULL OR [Scope] IN ('TEMPLATE', 'FACILITY_COPY')),
    CONSTRAINT [CK_MeasureFormula_ResultUnit] CHECK ([ResultUnit] IS NULL OR [ResultUnit] IN ('RATIO', 'AMOUNT', 'PERCENT')),
    CONSTRAINT [CK_MeasureFormula_Status] CHECK ([Status] IS NULL OR [Status] IN ('DRAFT', 'APPROVED', 'SUPERSEDED')),
    CONSTRAINT [CK_MeasureFormula_Confidence] CHECK ([Confidence] IS NULL OR [Confidence] IN ('CONFIRMED_AGAINST_ORIGINAL', 'READ_FROM_SCAN_UNVERIFIED', 'ENTERED_NO_DOCUMENT'))
);
GO

-- ===== schema wfl =====
-- تعريف نوع الطلب (FR-REQ-001، BR-REQ-001، V-REQ-01)؛ الأنواع الجديدة بلا كود (FR-REQ-021)
CREATE TABLE [wfl].[RequestType] (
    [TenantId] INT NOT NULL,
    [RequestTypeId] INT IDENTITY(1,1) NOT NULL,
    [Code] VARCHAR(40) NOT NULL,
    [NameAr] NVARCHAR(200) NOT NULL,
    [NameEn] NVARCHAR(200) NOT NULL,
    [Description] NVARCHAR(500) NULL,
    [Category] VARCHAR(10) NOT NULL,
    [ParentEntityType] VARCHAR(40) NULL,
    [DefaultTemplateKey] VARCHAR(60) NOT NULL,
    [NumberSequenceKey] VARCHAR(50) NOT NULL,
    [AmountFieldKey] VARCHAR(60) NULL,
    [CurrencyFieldKey] VARCHAR(60) NULL,
    [ProductFieldKey] VARCHAR(60) NULL,
    [ConsumesCreditLimit] BIT NOT NULL CONSTRAINT [DF_RequestType_ConsumesCreditLimit] DEFAULT 0,
    [LimitCheckMode] VARCHAR(18) NOT NULL CONSTRAINT [DF_RequestType_LimitCheckMode] DEFAULT 'NONE',
    [RequiresSignedOriginal] BIT NOT NULL CONSTRAINT [DF_RequestType_RequiresSignedOriginal] DEFAULT 0,
    [IsActive] BIT NOT NULL CONSTRAINT [DF_RequestType_IsActive] DEFAULT 0,
    [SortOrder] INT NOT NULL CONSTRAINT [DF_RequestType_SortOrder] DEFAULT 0,
    [SeedKey] VARCHAR(80) NULL,
    [PublicId] UNIQUEIDENTIFIER NOT NULL CONSTRAINT [DF_RequestType_PublicId] DEFAULT NEWSEQUENTIALID(),
    [CreatedAt] DATETIME2(3) NOT NULL CONSTRAINT [DF_RequestType_CreatedAt] DEFAULT SYSUTCDATETIME(),
    [CreatedBy] BIGINT NULL,
    [UpdatedAt] DATETIME2(3) NULL,
    [UpdatedBy] BIGINT NULL,
    [RowVersion] ROWVERSION NOT NULL,
    CONSTRAINT [PK_RequestType] PRIMARY KEY CLUSTERED ([RequestTypeId]),
    CONSTRAINT [UQ_RequestType_Tenant] UNIQUE ([TenantId], [RequestTypeId]),
    CONSTRAINT [UQ_RequestType_PublicId] UNIQUE ([PublicId]),
    CONSTRAINT [UQ_RequestType_Code] UNIQUE ([TenantId], [Code]),
    CONSTRAINT [CK_RequestType_1] CHECK (Category <> 'CHILD' OR ParentEntityType IS NOT NULL),
    CONSTRAINT [CK_RequestType_2] CHECK (ConsumesCreditLimit = 1 OR LimitCheckMode = 'NONE'),
    CONSTRAINT [CK_RequestType_Category] CHECK ([Category] IS NULL OR [Category] IN ('PURCHASE', 'SALES', 'TREASURY', 'GENERAL', 'CHILD')),
    CONSTRAINT [CK_RequestType_LimitCheckMode] CHECK ([LimitCheckMode] IS NULL OR [LimitCheckMode] IN ('NONE', 'ADVISORY', 'REQUIRED_SELECTION'))
);
GO
-- جمهور النوع: من يحق له الطلب؛ غياب الصفوف = لا أحد (فشل مغلق) (FR-REQ-007)
CREATE TABLE [wfl].[RequestTypeAudience] (
    [TenantId] INT NOT NULL,
    [RequestTypeAudienceId] INT IDENTITY(1,1) NOT NULL,
    [RequestTypeId] INT NOT NULL,
    [SubjectKind] VARCHAR(10) NOT NULL,
    [RoleId] BIGINT NULL,
    [DepartmentId] BIGINT NULL,
    [UserId] BIGINT NULL,
    [SubjectId] AS (CASE WHEN RoleId IS NOT NULL THEN RoleId WHEN DepartmentId IS NOT NULL THEN DepartmentId ELSE UserId END) PERSISTED,
    [CreatedAt] DATETIME2(3) NOT NULL CONSTRAINT [DF_RequestTypeAudience_CreatedAt] DEFAULT SYSUTCDATETIME(),
    [CreatedBy] BIGINT NULL,
    [UpdatedAt] DATETIME2(3) NULL,
    [UpdatedBy] BIGINT NULL,
    [RowVersion] ROWVERSION NOT NULL,
    CONSTRAINT [PK_RequestTypeAudience] PRIMARY KEY CLUSTERED ([RequestTypeAudienceId]),
    CONSTRAINT [UQ_RequestTypeAudience_Tenant] UNIQUE ([TenantId], [RequestTypeAudienceId]),
    CONSTRAINT [CK_RequestTypeAudience_1] CHECK ((SubjectKind = 'ROLE' AND RoleId IS NOT NULL AND DepartmentId IS NULL AND UserId IS NULL) OR (SubjectKind = 'DEPARTMENT' AND DepartmentId IS NOT NULL AND RoleId IS NULL AND UserId IS NULL) OR (SubjectKind = 'USER' AND UserId IS NOT NULL AND RoleId IS NULL AND DepartmentId IS NULL)),
    CONSTRAINT [CK_RequestTypeAudience_SubjectKind] CHECK ([SubjectKind] IS NULL OR [SubjectKind] IN ('ROLE', 'DEPARTMENT', 'USER'))
);
GO
-- المرحلة الظاهرة للطالب: DRAFT · IN_APPROVAL · RETURNED · AWAITING_REQUESTER · IN_PROGRESS · COMPLETED · REJECTED · CANCELLED (BR-WFL-011، D-6)
CREATE TABLE [wfl].[ExternalPhase] (
    [TenantId] INT NOT NULL,
    [ExternalPhaseId] INT IDENTITY(1,1) NOT NULL,
    [Code] VARCHAR(80) NOT NULL,
    [NameAr] NVARCHAR(200) NOT NULL,
    [NameEn] NVARCHAR(200) NULL,
    [Description] NVARCHAR(500) NULL,
    [IsActive] BIT NOT NULL CONSTRAINT [DF_ExternalPhase_IsActive] DEFAULT 1,
    [IsSystem] BIT NOT NULL CONSTRAINT [DF_ExternalPhase_IsSystem] DEFAULT 0,
    [IsLocked] BIT NOT NULL CONSTRAINT [DF_ExternalPhase_IsLocked] DEFAULT 0,
    [SortOrder] INT NOT NULL CONSTRAINT [DF_ExternalPhase_SortOrder] DEFAULT 0,
    [SeedKey] VARCHAR(80) NULL,
    [ExternalCode] VARCHAR(80) NULL,
    [ColorKey] VARCHAR(30) NULL,
    [RequiresRequesterAction] BIT NOT NULL CONSTRAINT [DF_ExternalPhase_RequiresRequesterAction] DEFAULT 0,
    [IsFinal] BIT NOT NULL CONSTRAINT [DF_ExternalPhase_IsFinal] DEFAULT 0,
    [CreatedAt] DATETIME2(3) NOT NULL CONSTRAINT [DF_ExternalPhase_CreatedAt] DEFAULT SYSUTCDATETIME(),
    [CreatedBy] BIGINT NULL,
    [UpdatedAt] DATETIME2(3) NULL,
    [UpdatedBy] BIGINT NULL,
    [RowVersion] ROWVERSION NOT NULL,
    CONSTRAINT [PK_ExternalPhase] PRIMARY KEY CLUSTERED ([ExternalPhaseId]),
    CONSTRAINT [UQ_ExternalPhase_Tenant] UNIQUE ([TenantId], [ExternalPhaseId]),
    CONSTRAINT [UQ_ExternalPhase_Code] UNIQUE ([TenantId], [Code]),
    CONSTRAINT [CK_ExternalPhase_1] CHECK (RequiresRequesterAction = 0 OR IsFinal = 0)
);
GO
-- نسخة قالب دورة عمل؛ المنشورة ثابتة (FR-WFL-001/028، BR-WFL-019، AC-WFL-6)
CREATE TABLE [wfl].[WorkflowTemplate] (
    [TenantId] INT NOT NULL,
    [WorkflowTemplateId] INT IDENTITY(1,1) NOT NULL,
    [RequestTypeId] INT NOT NULL,
    [TemplateKey] VARCHAR(60) NOT NULL,
    [VersionNo] INT NOT NULL,
    [Status] VARCHAR(10) NOT NULL CONSTRAINT [DF_WorkflowTemplate_Status] DEFAULT 'DRAFT',
    [IsCurrent] BIT NOT NULL CONSTRAINT [DF_WorkflowTemplate_IsCurrent] DEFAULT 0,
    [NameAr] NVARCHAR(200) NULL,
    [NameEn] NVARCHAR(200) NULL,
    [NumberOnStageKey] VARCHAR(40) NULL,
    [ResetApprovalsOnResubmit] BIT NOT NULL CONSTRAINT [DF_WorkflowTemplate_ResetApprovalsOnResubmit] DEFAULT 1,
    [AutoReassignOnOverdue] BIT NOT NULL CONSTRAINT [DF_WorkflowTemplate_AutoReassignOnOverdue] DEFAULT 0,
    [SodAllowSamePerson] BIT NOT NULL CONSTRAINT [DF_WorkflowTemplate_SodAllowSamePerson] DEFAULT 0,
    [ChangeNote] NVARCHAR(MAX) NULL,
    [PublishedAt] DATETIME2(3) NULL,
    [PublishedBy] BIGINT NULL,
    [RetiredAt] DATETIME2(3) NULL,
    [IsTenantModified] BIT NOT NULL CONSTRAINT [DF_WorkflowTemplate_IsTenantModified] DEFAULT 0,
    [SourceSeedVersion] INT NULL,
    [SeedKey] VARCHAR(80) NULL,
    [PublicId] UNIQUEIDENTIFIER NOT NULL CONSTRAINT [DF_WorkflowTemplate_PublicId] DEFAULT NEWSEQUENTIALID(),
    [CreatedAt] DATETIME2(3) NOT NULL CONSTRAINT [DF_WorkflowTemplate_CreatedAt] DEFAULT SYSUTCDATETIME(),
    [CreatedBy] BIGINT NULL,
    [UpdatedAt] DATETIME2(3) NULL,
    [UpdatedBy] BIGINT NULL,
    [RowVersion] ROWVERSION NOT NULL,
    CONSTRAINT [PK_WorkflowTemplate] PRIMARY KEY CLUSTERED ([WorkflowTemplateId]),
    CONSTRAINT [UQ_WorkflowTemplate_Tenant] UNIQUE ([TenantId], [WorkflowTemplateId]),
    CONSTRAINT [UQ_WorkflowTemplate_Scope_RequestTypeId] UNIQUE ([TenantId], [RequestTypeId], [WorkflowTemplateId]),
    CONSTRAINT [UQ_WorkflowTemplate_PublicId] UNIQUE ([PublicId]),
    CONSTRAINT [UQ_WorkflowTemplate_TemplateKey_VersionNo] UNIQUE ([TenantId], [TemplateKey], [VersionNo]),
    CONSTRAINT [CK_WorkflowTemplate_1] CHECK (VersionNo >= 1),
    CONSTRAINT [CK_WorkflowTemplate_2] CHECK (IsCurrent = 0 OR Status = 'PUBLISHED'),
    CONSTRAINT [CK_WorkflowTemplate_3] CHECK (Status <> 'PUBLISHED' OR PublishedAt IS NOT NULL),
    CONSTRAINT [CK_WorkflowTemplate_4] CHECK (Status <> 'DRAFT' OR PublishedAt IS NULL),
    CONSTRAINT [CK_WorkflowTemplate_5] CHECK ((Status = 'RETIRED' AND RetiredAt IS NOT NULL) OR (Status <> 'RETIRED' AND RetiredAt IS NULL)),
    CONSTRAINT [CK_WorkflowTemplate_6] CHECK (IsTenantModified = 0 OR SeedKey IS NULL),
    CONSTRAINT [CK_WorkflowTemplate_7] CHECK (SeedKey IS NULL OR SourceSeedVersion IS NOT NULL),
    CONSTRAINT [CK_WorkflowTemplate_8] CHECK (NameAr IS NOT NULL OR NameEn IS NOT NULL),
    CONSTRAINT [CK_WorkflowTemplate_Status] CHECK ([Status] IS NULL OR [Status] IN ('DRAFT', 'PUBLISHED', 'RETIRED'))
);
GO
-- مرحلة في نسخة قالب (FR-WFL-003/004/005، BR-WFL-002/010/012)؛ حذف فعلي لمسودة النسخة فقط
CREATE TABLE [wfl].[WorkflowStage] (
    [TenantId] INT NOT NULL,
    [WorkflowStageId] INT IDENTITY(1,1) NOT NULL,
    [TemplateId] INT NOT NULL,
    [StageKey] VARCHAR(40) NOT NULL,
    [NameAr] NVARCHAR(200) NOT NULL,
    [NameEn] NVARCHAR(200) NOT NULL,
    [Kind] VARCHAR(14) NOT NULL,
    [SeqNo] INT NOT NULL CONSTRAINT [DF_WorkflowStage_SeqNo] DEFAULT 0,
    [ExternalPhaseId] INT NOT NULL,
    [AssigneeRule] VARCHAR(17) NULL,
    [AssigneeRoleId] BIGINT NULL,
    [PoolPermissionId] INT NULL,
    [AssigneeUserId] BIGINT NULL,
    [AssigneeDepartmentId] BIGINT NULL,
    [FallbackRoleId] BIGINT NULL,
    [ApprovalMode] VARCHAR(10) NOT NULL CONSTRAINT [DF_WorkflowStage_ApprovalMode] DEFAULT 'NONE',
    [SlaHours] DECIMAL(7,2) NULL,
    [ClaimSlaHours] DECIMAL(7,2) NULL,
    [SlaMode] VARCHAR(10) NOT NULL CONSTRAINT [DF_WorkflowStage_SlaMode] DEFAULT 'BUSINESS',
    [IsTerminal] BIT NOT NULL CONSTRAINT [DF_WorkflowStage_IsTerminal] DEFAULT 0,
    [TerminalOutcome] VARCHAR(10) NULL,
    [AllowRequesterCancel] BIT NOT NULL CONSTRAINT [DF_WorkflowStage_AllowRequesterCancel] DEFAULT 0,
    [AllowReturn] BIT NOT NULL CONSTRAINT [DF_WorkflowStage_AllowReturn] DEFAULT 0,
    [RequiresComment] BIT NOT NULL CONSTRAINT [DF_WorkflowStage_RequiresComment] DEFAULT 0,
    [IsReservationPoint] BIT NOT NULL CONSTRAINT [DF_WorkflowStage_IsReservationPoint] DEFAULT 0,
    [SodAllowSamePerson] BIT NULL,
    [SubStatusSetJson] NVARCHAR(MAX) NULL,
    [EditableFieldKeysJson] NVARCHAR(MAX) NULL,
    [CreatedAt] DATETIME2(3) NOT NULL CONSTRAINT [DF_WorkflowStage_CreatedAt] DEFAULT SYSUTCDATETIME(),
    [CreatedBy] BIGINT NULL,
    [UpdatedAt] DATETIME2(3) NULL,
    [UpdatedBy] BIGINT NULL,
    [RowVersion] ROWVERSION NOT NULL,
    CONSTRAINT [PK_WorkflowStage] PRIMARY KEY CLUSTERED ([WorkflowStageId]),
    CONSTRAINT [UQ_WorkflowStage_Tenant] UNIQUE ([TenantId], [WorkflowStageId]),
    CONSTRAINT [UQ_WorkflowStage_Scope_TemplateId] UNIQUE ([TenantId], [TemplateId], [WorkflowStageId]),
    CONSTRAINT [UQ_WorkflowStage_TemplateId_StageKey] UNIQUE ([TenantId], [TemplateId], [StageKey]),
    CONSTRAINT [CK_WorkflowStage_1] CHECK ((Kind = 'TERMINAL' AND IsTerminal = 1) OR (Kind <> 'TERMINAL' AND IsTerminal = 0)),
    CONSTRAINT [CK_WorkflowStage_2] CHECK ((IsTerminal = 1 AND TerminalOutcome IS NOT NULL) OR (IsTerminal = 0 AND TerminalOutcome IS NULL)),
    CONSTRAINT [CK_WorkflowStage_3] CHECK ((Kind = 'APPROVAL' AND ApprovalMode <> 'NONE') OR (Kind <> 'APPROVAL' AND ApprovalMode = 'NONE')),
    CONSTRAINT [CK_WorkflowStage_4] CHECK (SlaHours IS NULL OR SlaHours > 0),
    CONSTRAINT [CK_WorkflowStage_5] CHECK (ClaimSlaHours IS NULL OR (ClaimSlaHours > 0 AND Kind = 'TREASURY_QUEUE')),
    CONSTRAINT [CK_WorkflowStage_6] CHECK (IsReservationPoint = 0 OR Kind = 'APPROVAL'),
    CONSTRAINT [CK_WorkflowStage_7] CHECK (Kind <> 'TREASURY_QUEUE' OR (AssigneeRule IS NOT NULL AND AssigneeRule = 'ROLE' AND (AssigneeRoleId IS NOT NULL OR PoolPermissionId IS NOT NULL))),
    CONSTRAINT [CK_WorkflowStage_8] CHECK ((AssigneeRoleId IS NULL AND PoolPermissionId IS NULL) OR AssigneeRule = 'ROLE'),
    CONSTRAINT [CK_WorkflowStage_9] CHECK (AssigneeRoleId IS NULL OR PoolPermissionId IS NULL),
    CONSTRAINT [CK_WorkflowStage_10] CHECK (AssigneeUserId IS NULL OR AssigneeRule = 'USER'),
    CONSTRAINT [CK_WorkflowStage_11] CHECK (AssigneeDepartmentId IS NULL OR AssigneeRule = 'DEPARTMENT'),
    CONSTRAINT [CK_WorkflowStage_12] CHECK (AssigneeRule <> 'USER' OR AssigneeUserId IS NOT NULL),
    CONSTRAINT [CK_WorkflowStage_13] CHECK (AssigneeRule <> 'DEPARTMENT' OR AssigneeDepartmentId IS NOT NULL),
    CONSTRAINT [CK_WorkflowStage_14] CHECK (AssigneeRule <> 'ROLE' OR AssigneeRoleId IS NOT NULL OR PoolPermissionId IS NOT NULL),
    CONSTRAINT [CK_WorkflowStage_Kind] CHECK ([Kind] IS NULL OR [Kind] IN ('DRAFT', 'TASK', 'APPROVAL', 'TREASURY_QUEUE', 'TERMINAL')),
    CONSTRAINT [CK_WorkflowStage_AssigneeRule] CHECK ([AssigneeRule] IS NULL OR [AssigneeRule] IN ('ROLE', 'USER', 'DEPARTMENT', 'REQUESTER', 'REQUESTER_MANAGER', 'CLAIMER')),
    CONSTRAINT [CK_WorkflowStage_ApprovalMode] CHECK ([ApprovalMode] IS NULL OR [ApprovalMode] IN ('NONE', 'ANY', 'ALL')),
    CONSTRAINT [CK_WorkflowStage_SlaMode] CHECK ([SlaMode] IS NULL OR [SlaMode] IN ('BUSINESS', 'CALENDAR')),
    CONSTRAINT [CK_WorkflowStage_TerminalOutcome] CHECK ([TerminalOutcome] IS NULL OR [TerminalOutcome] IN ('COMPLETED', 'REJECTED', 'CANCELLED')),
    CONSTRAINT [CK_WorkflowStage_SubStatusSetJson_json] CHECK ([SubStatusSetJson] IS NULL OR ISJSON([SubStatusSetJson]) = 1),
    CONSTRAINT [CK_WorkflowStage_EditableFieldKeysJson_json] CHECK ([EditableFieldKeysJson] IS NULL OR ISJSON([EditableFieldKeysJson]) = 1)
);
GO
-- خانة موافقة في مرحلة APPROVAL؛ ALL = كل الخانات، ودور بشخصين يلزمان معًا = خانتان (FR-WFL-007/041، BR-WFL-003/004)
CREATE TABLE [wfl].[StageApprover] (
    [TenantId] INT NOT NULL,
    [StageApproverId] INT IDENTITY(1,1) NOT NULL,
    [StageId] INT NOT NULL,
    [SlotKey] VARCHAR(30) NOT NULL,
    [LabelAr] NVARCHAR(200) NULL,
    [LabelEn] NVARCHAR(200) NULL,
    [WorkflowRole] VARCHAR(10) NOT NULL CONSTRAINT [DF_StageApprover_WorkflowRole] DEFAULT 'APPROVER',
    [SubjectRule] VARCHAR(17) NOT NULL,
    [RoleId] BIGINT NULL,
    [UserId] BIGINT NULL,
    [DepartmentId] BIGINT NULL,
    [FallbackRoleId] BIGINT NULL,
    [AutoCompleteBySubmitter] BIT NOT NULL CONSTRAINT [DF_StageApprover_AutoCompleteBySubmitter] DEFAULT 0,
    [AllowDelegation] BIT NOT NULL CONSTRAINT [DF_StageApprover_AllowDelegation] DEFAULT 1,
    [CreatedAt] DATETIME2(3) NOT NULL CONSTRAINT [DF_StageApprover_CreatedAt] DEFAULT SYSUTCDATETIME(),
    [CreatedBy] BIGINT NULL,
    [UpdatedAt] DATETIME2(3) NULL,
    [UpdatedBy] BIGINT NULL,
    [RowVersion] ROWVERSION NOT NULL,
    CONSTRAINT [PK_StageApprover] PRIMARY KEY CLUSTERED ([StageApproverId]),
    CONSTRAINT [UQ_StageApprover_Tenant] UNIQUE ([TenantId], [StageApproverId]),
    CONSTRAINT [UQ_StageApprover_StageId_SlotKey] UNIQUE ([TenantId], [StageId], [SlotKey]),
    CONSTRAINT [CK_StageApprover_1] CHECK (SubjectRule <> 'ROLE' OR RoleId IS NOT NULL),
    CONSTRAINT [CK_StageApprover_2] CHECK (SubjectRule <> 'USER' OR UserId IS NOT NULL),
    CONSTRAINT [CK_StageApprover_3] CHECK (RoleId IS NULL OR SubjectRule = 'ROLE'),
    CONSTRAINT [CK_StageApprover_4] CHECK (UserId IS NULL OR SubjectRule = 'USER'),
    CONSTRAINT [CK_StageApprover_5] CHECK (DepartmentId IS NULL OR SubjectRule = 'DEPARTMENT_HEAD'),
    CONSTRAINT [CK_StageApprover_6] CHECK (AutoCompleteBySubmitter = 0 OR SubjectRule = 'REQUESTER'),
    CONSTRAINT [CK_StageApprover_7] CHECK (LabelAr IS NOT NULL OR LabelEn IS NOT NULL),
    CONSTRAINT [CK_StageApprover_WorkflowRole] CHECK ([WorkflowRole] IS NULL OR [WorkflowRole] IN ('CREATOR', 'AUDITOR', 'APPROVER', 'OTHER')),
    CONSTRAINT [CK_StageApprover_SubjectRule] CHECK ([SubjectRule] IS NULL OR [SubjectRule] IN ('REQUESTER', 'REQUESTER_MANAGER', 'ROLE', 'USER', 'DEPARTMENT_HEAD'))
);
GO
-- انتقال بين مرحلتين بشرط وأولوية؛ دورة خطية بتفرع شرطي بسيط (FR-WFL-006، BR-WFL-001، D-8)
CREATE TABLE [wfl].[WorkflowTransition] (
    [TenantId] INT NOT NULL,
    [WorkflowTransitionId] INT IDENTITY(1,1) NOT NULL,
    [TemplateId] INT NOT NULL,
    [FromStageId] INT NOT NULL,
    [Action] VARCHAR(10) NOT NULL,
    [ToStageId] INT NOT NULL,
    [Priority] INT NOT NULL CONSTRAINT [DF_WorkflowTransition_Priority] DEFAULT 1,
    [ConditionJson] NVARCHAR(MAX) NULL,
    [ResumeStageId] INT NULL,
    [LabelAr] NVARCHAR(200) NULL,
    [LabelEn] NVARCHAR(200) NULL,
    [RequiresComment] BIT NOT NULL CONSTRAINT [DF_WorkflowTransition_RequiresComment] DEFAULT 0,
    [CreatedAt] DATETIME2(3) NOT NULL CONSTRAINT [DF_WorkflowTransition_CreatedAt] DEFAULT SYSUTCDATETIME(),
    [CreatedBy] BIGINT NULL,
    [UpdatedAt] DATETIME2(3) NULL,
    [UpdatedBy] BIGINT NULL,
    [RowVersion] ROWVERSION NOT NULL,
    CONSTRAINT [PK_WorkflowTransition] PRIMARY KEY CLUSTERED ([WorkflowTransitionId]),
    CONSTRAINT [UQ_WorkflowTransition_Tenant] UNIQUE ([TenantId], [WorkflowTransitionId]),
    CONSTRAINT [UQ_WorkflowTransition_FromStageId_Action_Priority] UNIQUE ([TenantId], [FromStageId], [Action], [Priority]),
    CONSTRAINT [CK_WorkflowTransition_1] CHECK (Priority >= 1),
    CONSTRAINT [CK_WorkflowTransition_2] CHECK (FromStageId <> ToStageId),
    CONSTRAINT [CK_WorkflowTransition_3] CHECK (ResumeStageId IS NULL OR Action IN ('RETURN','RESUBMIT')),
    CONSTRAINT [CK_WorkflowTransition_4] CHECK (Action NOT IN ('RETURN','REJECT') OR RequiresComment = 1),
    CONSTRAINT [CK_WorkflowTransition_Action] CHECK ([Action] IS NULL OR [Action] IN ('SUBMIT', 'APPROVE', 'COMPLETE', 'RETURN', 'REJECT', 'CANCEL', 'RESUBMIT')),
    CONSTRAINT [CK_WorkflowTransition_ConditionJson_json] CHECK ([ConditionJson] IS NULL OR ISJSON([ConditionJson]) = 1)
);
GO
-- خطاف مسجَّل بالكود على مرحلة: مفتاح ومعاملات لا كود (FR-WFL-021، BR-WFL-015، §5.4)
CREATE TABLE [wfl].[WorkflowStageHook] (
    [TenantId] INT NOT NULL,
    [WorkflowStageHookId] INT IDENTITY(1,1) NOT NULL,
    [StageId] INT NOT NULL,
    [TriggerKind] VARCHAR(10) NOT NULL,
    [ActionFilter] VARCHAR(10) NULL,
    [HookKey] VARCHAR(60) NOT NULL,
    [ParamsJson] NVARCHAR(MAX) NULL,
    [ExecMode] VARCHAR(12) NOT NULL CONSTRAINT [DF_WorkflowStageHook_ExecMode] DEFAULT 'SYNC_TX',
    [OnFailure] VARCHAR(10) NOT NULL CONSTRAINT [DF_WorkflowStageHook_OnFailure] DEFAULT 'BLOCK',
    [SeqNo] INT NOT NULL CONSTRAINT [DF_WorkflowStageHook_SeqNo] DEFAULT 1,
    [CreatedAt] DATETIME2(3) NOT NULL CONSTRAINT [DF_WorkflowStageHook_CreatedAt] DEFAULT SYSUTCDATETIME(),
    [CreatedBy] BIGINT NULL,
    [UpdatedAt] DATETIME2(3) NULL,
    [UpdatedBy] BIGINT NULL,
    [RowVersion] ROWVERSION NOT NULL,
    CONSTRAINT [PK_WorkflowStageHook] PRIMARY KEY CLUSTERED ([WorkflowStageHookId]),
    CONSTRAINT [UQ_WorkflowStageHook_Tenant] UNIQUE ([TenantId], [WorkflowStageHookId]),
    CONSTRAINT [UQ_WorkflowStageHook_StageId_TriggerKind_ActionFilter_HookKey] UNIQUE ([TenantId], [StageId], [TriggerKind], [ActionFilter], [HookKey]),
    CONSTRAINT [CK_WorkflowStageHook_1] CHECK ((TriggerKind = 'ON_ACTION' AND ActionFilter IS NOT NULL) OR (TriggerKind <> 'ON_ACTION' AND ActionFilter IS NULL)),
    CONSTRAINT [CK_WorkflowStageHook_2] CHECK (HookKey LIKE '%.%'),
    CONSTRAINT [CK_WorkflowStageHook_TriggerKind] CHECK ([TriggerKind] IS NULL OR [TriggerKind] IN ('ON_ENTER', 'ON_EXIT', 'ON_ACTION')),
    CONSTRAINT [CK_WorkflowStageHook_ActionFilter] CHECK ([ActionFilter] IS NULL OR [ActionFilter] IN ('SUBMIT', 'APPROVE', 'COMPLETE', 'RETURN', 'REJECT', 'CANCEL', 'RESUBMIT')),
    CONSTRAINT [CK_WorkflowStageHook_ExecMode] CHECK ([ExecMode] IS NULL OR [ExecMode] IN ('SYNC_TX', 'AFTER_COMMIT')),
    CONSTRAINT [CK_WorkflowStageHook_OnFailure] CHECK ([OnFailure] IS NULL OR [OnFailure] IN ('BLOCK', 'WARN')),
    CONSTRAINT [CK_WorkflowStageHook_ParamsJson_json] CHECK ([ParamsJson] IS NULL OR ISJSON([ParamsJson]) = 1)
);
GO
-- حقل في نسخة قالب يولّد النموذج بلا كود واجهة (FR-REQ-002..005، BR-REQ-003/004)
CREATE TABLE [wfl].[TemplateField] (
    [TenantId] INT NOT NULL,
    [TemplateFieldId] INT IDENTITY(1,1) NOT NULL,
    [TemplateId] INT NOT NULL,
    [FieldKey] VARCHAR(60) NOT NULL,
    [LabelAr] NVARCHAR(200) NOT NULL,
    [LabelEn] NVARCHAR(200) NOT NULL,
    [HelpAr] NVARCHAR(500) NULL,
    [HelpEn] NVARCHAR(500) NULL,
    [SectionKey] VARCHAR(40) NULL,
    [SeqNo] INT NOT NULL CONSTRAINT [DF_TemplateField_SeqNo] DEFAULT 0,
    [DataType] VARCHAR(15) NOT NULL,
    [ConfigJson] NVARCHAR(MAX) NULL,
    [IsRequired] BIT NOT NULL CONSTRAINT [DF_TemplateField_IsRequired] DEFAULT 0,
    [RequiredWhenJson] NVARCHAR(MAX) NULL,
    [VisibleWhenJson] NVARCHAR(MAX) NULL,
    [VisibleStagesJson] NVARCHAR(MAX) NULL,
    [EditableStagesJson] NVARCHAR(MAX) NULL,
    [Sensitivity] VARCHAR(12) NOT NULL CONSTRAINT [DF_TemplateField_Sensitivity] DEFAULT 'NORMAL',
    [IndexRole] VARCHAR(17) NOT NULL CONSTRAINT [DF_TemplateField_IndexRole] DEFAULT 'NONE',
    [KeepWhenHidden] BIT NOT NULL CONSTRAINT [DF_TemplateField_KeepWhenHidden] DEFAULT 0,
    [ValidationJson] NVARCHAR(MAX) NULL,
    [CreatedAt] DATETIME2(3) NOT NULL CONSTRAINT [DF_TemplateField_CreatedAt] DEFAULT SYSUTCDATETIME(),
    [CreatedBy] BIGINT NULL,
    [UpdatedAt] DATETIME2(3) NULL,
    [UpdatedBy] BIGINT NULL,
    [RowVersion] ROWVERSION NOT NULL,
    CONSTRAINT [PK_TemplateField] PRIMARY KEY CLUSTERED ([TemplateFieldId]),
    CONSTRAINT [UQ_TemplateField_Tenant] UNIQUE ([TenantId], [TemplateFieldId]),
    CONSTRAINT [UQ_TemplateField_TemplateId_FieldKey] UNIQUE ([TenantId], [TemplateId], [FieldKey]),
    CONSTRAINT [CK_TemplateField_1] CHECK (IndexRole <> 'AMOUNT' OR DataType = 'AMOUNT'),
    CONSTRAINT [CK_TemplateField_2] CHECK (IndexRole <> 'TITLE' OR DataType = 'TEXT'),
    CONSTRAINT [CK_TemplateField_3] CHECK (IndexRole <> 'REQUIRED_BY_DATE' OR DataType = 'DATE'),
    CONSTRAINT [CK_TemplateField_4] CHECK (Sensitivity <> 'RESTRICTED' OR IndexRole = 'NONE'),
    CONSTRAINT [CK_TemplateField_DataType] CHECK ([DataType] IS NULL OR [DataType] IN ('TEXT', 'LONGTEXT', 'INTEGER', 'DECIMAL', 'AMOUNT', 'PERCENT', 'DATE', 'BOOLEAN', 'LIST', 'MULTILIST', 'CATALOG_REF', 'USER_REF', 'EXTERNAL_REF', 'FILE_SLOT', 'TABLE', 'MODULE_FORM', 'LIMIT_SELECTION')),
    CONSTRAINT [CK_TemplateField_Sensitivity] CHECK ([Sensitivity] IS NULL OR [Sensitivity] IN ('NORMAL', 'CONFIDENTIAL', 'RESTRICTED')),
    CONSTRAINT [CK_TemplateField_IndexRole] CHECK ([IndexRole] IS NULL OR [IndexRole] IN ('NONE', 'TITLE', 'AMOUNT', 'CURRENCY', 'COUNTERPARTY_NAME', 'COUNTERPARTY_CODE', 'PRODUCT', 'REQUIRED_BY_DATE')),
    CONSTRAINT [CK_TemplateField_ConfigJson_json] CHECK ([ConfigJson] IS NULL OR ISJSON([ConfigJson]) = 1),
    CONSTRAINT [CK_TemplateField_RequiredWhenJson_json] CHECK ([RequiredWhenJson] IS NULL OR ISJSON([RequiredWhenJson]) = 1),
    CONSTRAINT [CK_TemplateField_VisibleWhenJson_json] CHECK ([VisibleWhenJson] IS NULL OR ISJSON([VisibleWhenJson]) = 1),
    CONSTRAINT [CK_TemplateField_VisibleStagesJson_json] CHECK ([VisibleStagesJson] IS NULL OR ISJSON([VisibleStagesJson]) = 1),
    CONSTRAINT [CK_TemplateField_EditableStagesJson_json] CHECK ([EditableStagesJson] IS NULL OR ISJSON([EditableStagesJson]) = 1),
    CONSTRAINT [CK_TemplateField_ValidationJson_json] CHECK ([ValidationJson] IS NULL OR ISJSON([ValidationJson]) = 1)
);
GO
-- قاعدة مرفق على نسخة قالب (FR-REQ-006، BR-REQ-005، FR-WFL-024/025)
CREATE TABLE [wfl].[TemplateAttachmentRule] (
    [TenantId] INT NOT NULL,
    [TemplateAttachmentRuleId] INT IDENTITY(1,1) NOT NULL,
    [TemplateId] INT NOT NULL,
    [SlotKey] VARCHAR(40) NOT NULL,
    [LabelAr] NVARCHAR(200) NULL,
    [LabelEn] NVARCHAR(200) NULL,
    [DocumentTypeId] INT NOT NULL,
    [MinCount] INT NOT NULL CONSTRAINT [DF_TemplateAttachmentRule_MinCount] DEFAULT 0,
    [MaxCount] INT NULL,
    [RequiredBeforeStageKey] VARCHAR(40) NULL,
    [RequiredWhenJson] NVARCHAR(MAX) NULL,
    [VisibleToRequester] BIT NOT NULL CONSTRAINT [DF_TemplateAttachmentRule_VisibleToRequester] DEFAULT 0,
    [CreatedAt] DATETIME2(3) NOT NULL CONSTRAINT [DF_TemplateAttachmentRule_CreatedAt] DEFAULT SYSUTCDATETIME(),
    [CreatedBy] BIGINT NULL,
    [UpdatedAt] DATETIME2(3) NULL,
    [UpdatedBy] BIGINT NULL,
    [RowVersion] ROWVERSION NOT NULL,
    CONSTRAINT [PK_TemplateAttachmentRule] PRIMARY KEY CLUSTERED ([TemplateAttachmentRuleId]),
    CONSTRAINT [UQ_TemplateAttachmentRule_Tenant] UNIQUE ([TenantId], [TemplateAttachmentRuleId]),
    CONSTRAINT [UQ_TemplateAttachmentRule_TemplateId_SlotKey] UNIQUE ([TenantId], [TemplateId], [SlotKey]),
    CONSTRAINT [CK_TemplateAttachmentRule_1] CHECK (MinCount >= 0),
    CONSTRAINT [CK_TemplateAttachmentRule_2] CHECK (MaxCount IS NULL OR (MaxCount >= 1 AND MaxCount >= MinCount)),
    CONSTRAINT [CK_TemplateAttachmentRule_3] CHECK (MinCount = 0 OR RequiredBeforeStageKey IS NOT NULL),
    CONSTRAINT [CK_TemplateAttachmentRule_4] CHECK (LabelAr IS NOT NULL OR LabelEn IS NOT NULL),
    CONSTRAINT [CK_TemplateAttachmentRule_RequiredWhenJson_json] CHECK ([RequiredWhenJson] IS NULL OR ISJSON([RequiredWhenJson]) = 1)
);
GO
-- الطلب: أكثر الجداول ازدحامًا؛ الحالة الداخلية منفصلة عن المرحلة الظاهرة (FR-WFL-001، FR-REQ-009، D-6، BR-REQ-002/003)
CREATE TABLE [wfl].[Request] (
    [TenantId] INT NOT NULL,
    [RequestId] BIGINT IDENTITY(1,1) NOT NULL,
    [DraftRef] VARCHAR(20) NOT NULL,
    [RequestNo] NVARCHAR(40) NULL,
    [NumberYear] SMALLINT NULL,
    [NumberSeq] INT NULL,
    [RequestTypeId] INT NOT NULL,
    [TemplateId] INT NOT NULL,
    [CompanyId] BIGINT NOT NULL,
    [DepartmentId] BIGINT NULL,
    [RequesterUserId] BIGINT NOT NULL,
    [CreatedByUserId] BIGINT NOT NULL,
    [SubmittedByUserId] BIGINT NULL,
    [Title] NVARCHAR(200) NULL,
    [Status] VARCHAR(14) NOT NULL CONSTRAINT [DF_Request_Status] DEFAULT 'DRAFT',
    [CurrentStageId] INT NULL,
    [CurrentStageInstanceId] BIGINT NULL,
    [ExternalPhaseId] INT NOT NULL,
    [SubStatusKey] VARCHAR(40) NULL,
    [AssigneeUserId] BIGINT NULL,
    [QueueEnteredAt] DATETIME2(3) NULL,
    [ClaimedAt] DATETIME2(3) NULL,
    [DueAt] DATETIME2(3) NULL,
    [SlaState] VARCHAR(10) NOT NULL CONSTRAINT [DF_Request_SlaState] DEFAULT 'NONE',
    [Priority] VARCHAR(10) NOT NULL CONSTRAINT [DF_Request_Priority] DEFAULT 'NORMAL',
    [UrgentReason] NVARCHAR(500) NULL,
    [RequiredByDate] DATE NULL,
    [CycleNo] INT NOT NULL CONSTRAINT [DF_Request_CycleNo] DEFAULT 1,
    [SubmittedAt] DATETIME2(3) NULL,
    [CompletedAt] DATETIME2(3) NULL,
    [ReadyToCloseAt] DATETIME2(3) NULL,
    [ClosedByUserId] BIGINT NULL,
    [ClosedAt] DATETIME2(3) NULL,
    [OutcomeReason] NVARCHAR(500) NULL,
    [Amount] DECIMAL(19,4) NULL,
    [CurrencyId] INT NULL,
    [ProductId] INT NULL,
    [CounterpartyName] NVARCHAR(200) NULL,
    [CounterpartyCode] NVARCHAR(60) NULL,
    [SearchText] NVARCHAR(MAX) NULL,
    [FormDataJson] NVARCHAR(MAX) NULL,
    [ParentEntityType] VARCHAR(40) NULL,
    [ParentEntityId] BIGINT NULL,
    [ParentRequestId] BIGINT NULL,
    [CopiedFromRequestId] BIGINT NULL,
    [LcId] BIGINT NULL,
    [FacilityId] BIGINT NULL,
    [LimitId] BIGINT NULL,
    [LimitProductLineId] BIGINT NULL,
    [InstitutionId] BIGINT NULL,
    [ExecutionChannel] VARCHAR(18) NULL,
    [ReservationId] BIGINT NULL,
    [ReservedAmount] DECIMAL(19,4) NULL,
    [ReservationState] VARCHAR(10) NOT NULL CONSTRAINT [DF_Request_ReservationState] DEFAULT 'NONE',
    [HasSodException] BIT NOT NULL CONSTRAINT [DF_Request_HasSodException] DEFAULT 0,
    [ArchivedAt] DATETIME2(3) NULL,
    [PublicId] UNIQUEIDENTIFIER NOT NULL CONSTRAINT [DF_Request_PublicId] DEFAULT NEWSEQUENTIALID(),
    [CreatedAt] DATETIME2(3) NOT NULL CONSTRAINT [DF_Request_CreatedAt] DEFAULT SYSUTCDATETIME(),
    [CreatedBy] BIGINT NULL,
    [UpdatedAt] DATETIME2(3) NULL,
    [UpdatedBy] BIGINT NULL,
    [RowVersion] ROWVERSION NOT NULL,
    CONSTRAINT [PK_Request] PRIMARY KEY CLUSTERED ([RequestId]),
    CONSTRAINT [UQ_Request_Tenant] UNIQUE ([TenantId], [RequestId]),
    CONSTRAINT [UQ_Request_Scope_CompanyId] UNIQUE ([TenantId], [CompanyId], [RequestId]),
    CONSTRAINT [UQ_Request_PublicId] UNIQUE ([PublicId]),
    CONSTRAINT [UQ_Request_DraftRef] UNIQUE ([TenantId], [DraftRef]),
    CONSTRAINT [CK_Request_1] CHECK ((RequestNo IS NULL AND NumberYear IS NULL AND NumberSeq IS NULL) OR (RequestNo IS NOT NULL AND NumberYear IS NOT NULL AND NumberSeq IS NOT NULL)),
    CONSTRAINT [CK_Request_2] CHECK (DraftRef LIKE 'D-%'),
    CONSTRAINT [CK_Request_3] CHECK (Status NOT IN ('ACTIVE','AWAITING_CLOSE','COMPLETED','REJECTED') OR SubmittedAt IS NOT NULL),
    CONSTRAINT [CK_Request_4] CHECK ((Status IN ('DRAFT','ACTIVE','AWAITING_CLOSE') AND CompletedAt IS NULL) OR (Status IN ('COMPLETED','REJECTED','CANCELLED') AND CompletedAt IS NOT NULL)),
    CONSTRAINT [CK_Request_5] CHECK (CompletedAt IS NULL OR SubmittedAt IS NULL OR CompletedAt >= SubmittedAt),
    CONSTRAINT [CK_Request_6] CHECK (Status <> 'ACTIVE' OR (CurrentStageInstanceId IS NOT NULL AND CurrentStageId IS NOT NULL)),
    CONSTRAINT [CK_Request_7] CHECK (Status <> 'COMPLETED' OR RequestNo IS NOT NULL),
    CONSTRAINT [CK_Request_8] CHECK (ArchivedAt IS NULL OR Status = 'DRAFT'),
    CONSTRAINT [CK_Request_9] CHECK (Status <> 'AWAITING_CLOSE' OR (ReadyToCloseAt IS NOT NULL AND CurrentStageInstanceId IS NOT NULL)),
    CONSTRAINT [CK_Request_10] CHECK (ReadyToCloseAt IS NULL OR Status IN ('AWAITING_CLOSE','COMPLETED')),
    CONSTRAINT [CK_Request_11] CHECK (Status <> 'COMPLETED' OR (ClosedByUserId IS NOT NULL AND ClosedAt IS NOT NULL AND ClosedAt = CompletedAt)),
    CONSTRAINT [CK_Request_12] CHECK (ClosedByUserId IS NULL OR Status = 'COMPLETED'),
    CONSTRAINT [CK_Request_13] CHECK (Priority <> 'URGENT' OR UrgentReason IS NOT NULL),
    CONSTRAINT [CK_Request_14] CHECK (CycleNo >= 1),
    CONSTRAINT [CK_Request_15] CHECK (Amount IS NULL OR CurrencyId IS NOT NULL),
    CONSTRAINT [CK_Request_16] CHECK (SlaState NOT IN ('ON_TRACK','AT_RISK','OVERDUE') OR DueAt IS NOT NULL),
    CONSTRAINT [CK_Request_17] CHECK ((ReservationState = 'NONE' AND ReservationId IS NULL AND ReservedAmount IS NULL) OR (ReservationState <> 'NONE' AND ReservationId IS NOT NULL AND ReservedAmount IS NOT NULL)),
    CONSTRAINT [CK_Request_18] CHECK (ReservedAmount IS NULL OR (ReservedAmount > 0 AND CurrencyId IS NOT NULL)),
    CONSTRAINT [CK_Request_19] CHECK (LimitId IS NULL OR FacilityId IS NOT NULL),
    CONSTRAINT [CK_Request_20] CHECK (LimitProductLineId IS NULL OR LimitId IS NOT NULL),
    CONSTRAINT [CK_Request_21] CHECK ((ParentEntityType IS NULL AND ParentEntityId IS NULL) OR (ParentEntityType IS NOT NULL AND ParentEntityId IS NOT NULL)),
    CONSTRAINT [CK_Request_22] CHECK (ParentRequestId IS NULL OR ParentRequestId <> RequestId),
    CONSTRAINT [CK_Request_23] CHECK (CopiedFromRequestId IS NULL OR CopiedFromRequestId <> RequestId),
    CONSTRAINT [CK_Request_Status] CHECK ([Status] IS NULL OR [Status] IN ('DRAFT', 'ACTIVE', 'AWAITING_CLOSE', 'COMPLETED', 'REJECTED', 'CANCELLED')),
    CONSTRAINT [CK_Request_SlaState] CHECK ([SlaState] IS NULL OR [SlaState] IN ('ON_TRACK', 'AT_RISK', 'OVERDUE', 'PAUSED', 'NONE')),
    CONSTRAINT [CK_Request_Priority] CHECK ([Priority] IS NULL OR [Priority] IN ('NORMAL', 'URGENT')),
    CONSTRAINT [CK_Request_ExecutionChannel] CHECK ([ExecutionChannel] IS NULL OR [ExecutionChannel] IN ('BANK_PORTAL', 'MANUAL_FORM', 'DIRECT_INTEGRATION')),
    CONSTRAINT [CK_Request_ReservationState] CHECK ([ReservationState] IS NULL OR [ReservationState] IN ('NONE', 'RESERVED', 'CONVERTED', 'RELEASED', 'LOST')),
    CONSTRAINT [CK_Request_FormDataJson_json] CHECK ([FormDataJson] IS NULL OR ISJSON([FormDataJson]) = 1)
);
GO
-- تعليق ظاهر للطالب أو داخلي؛ غير قابل للتعديل (سحب مع بقاء الأصل) (FR-REQ-017، BR-REQ-014)
CREATE TABLE [wfl].[RequestComment] (
    [TenantId] INT NOT NULL,
    [RequestCommentId] BIGINT IDENTITY(1,1) NOT NULL,
    [RequestId] BIGINT NOT NULL,
    [StageInstanceId] BIGINT NULL,
    [Visibility] VARCHAR(17) NOT NULL CONSTRAINT [DF_RequestComment_Visibility] DEFAULT 'INTERNAL',
    [Body] NVARCHAR(4000) NOT NULL,
    [AuthorUserId] BIGINT NOT NULL,
    [ParentCommentId] BIGINT NULL,
    [RetractedAt] DATETIME2(3) NULL,
    [RetractedBy] BIGINT NULL,
    [CreatedAt] DATETIME2(3) NOT NULL CONSTRAINT [DF_RequestComment_CreatedAt] DEFAULT SYSUTCDATETIME(),
    [CreatedBy] BIGINT NULL,
    [UpdatedAt] DATETIME2(3) NULL,
    [UpdatedBy] BIGINT NULL,
    [RowVersion] ROWVERSION NOT NULL,
    CONSTRAINT [PK_RequestComment] PRIMARY KEY CLUSTERED ([RequestCommentId]),
    CONSTRAINT [UQ_RequestComment_Tenant] UNIQUE ([TenantId], [RequestCommentId]),
    CONSTRAINT [UQ_RequestComment_Scope_RequestId] UNIQUE ([TenantId], [RequestId], [RequestCommentId]),
    CONSTRAINT [CK_RequestComment_1] CHECK (ParentCommentId IS NULL OR ParentCommentId <> RequestCommentId),
    CONSTRAINT [CK_RequestComment_2] CHECK ((RetractedAt IS NULL AND RetractedBy IS NULL) OR (RetractedAt IS NOT NULL AND RetractedBy IS NOT NULL)),
    CONSTRAINT [CK_RequestComment_Visibility] CHECK ([Visibility] IS NULL OR [Visibility] IN ('INTERNAL', 'REQUESTER_VISIBLE'))
);
GO
-- ربط مستند بطلب ينشئ DocumentLink (EntityType=Request) (FR-REQ-006، BR-REQ-005)
CREATE TABLE [wfl].[RequestAttachment] (
    [TenantId] INT NOT NULL,
    [RequestAttachmentId] BIGINT IDENTITY(1,1) NOT NULL,
    [RequestId] BIGINT NOT NULL,
    [DocumentId] BIGINT NOT NULL,
    [SlotKey] VARCHAR(40) NULL,
    [StageInstanceId] BIGINT NULL,
    [Visibility] VARCHAR(17) NOT NULL CONSTRAINT [DF_RequestAttachment_Visibility] DEFAULT 'INTERNAL',
    [IsActive] BIT NOT NULL CONSTRAINT [DF_RequestAttachment_IsActive] DEFAULT 1,
    [CreatedAt] DATETIME2(3) NOT NULL CONSTRAINT [DF_RequestAttachment_CreatedAt] DEFAULT SYSUTCDATETIME(),
    [CreatedBy] BIGINT NULL,
    [UpdatedAt] DATETIME2(3) NULL,
    [UpdatedBy] BIGINT NULL,
    [RowVersion] ROWVERSION NOT NULL,
    CONSTRAINT [PK_RequestAttachment] PRIMARY KEY CLUSTERED ([RequestAttachmentId]),
    CONSTRAINT [UQ_RequestAttachment_Tenant] UNIQUE ([TenantId], [RequestAttachmentId]),
    CONSTRAINT [UQ_RequestAttachment_RequestId_DocumentId] UNIQUE ([TenantId], [RequestId], [DocumentId]),
    CONSTRAINT [CK_RequestAttachment_Visibility] CHECK ([Visibility] IS NULL OR [Visibility] IN ('INTERNAL', 'REQUESTER_VISIBLE'))
);
GO
-- مرجع خارجي بنص حر؛ تعديل بالإحلال ويبقى التاريخ؛ بلا تحقق خارجي (FR-REQ-010، X-DAT-7، BR-REQ-006)
CREATE TABLE [wfl].[RequestExternalRef] (
    [TenantId] INT NOT NULL,
    [RequestExternalRefId] BIGINT IDENTITY(1,1) NOT NULL,
    [RequestId] BIGINT NOT NULL,
    [SystemCode] NVARCHAR(40) NOT NULL,
    [RefType] NVARCHAR(60) NOT NULL,
    [RefValue] NVARCHAR(100) NOT NULL,
    [NormalizedValue] NVARCHAR(100) NOT NULL,
    [EnteredAtStageKey] VARCHAR(40) NULL,
    [IsActive] BIT NOT NULL CONSTRAINT [DF_RequestExternalRef_IsActive] DEFAULT 1,
    [SupersededById] BIGINT NULL,
    [EnteredBy] BIGINT NULL,
    [EnteredAt] DATETIME2(3) NOT NULL CONSTRAINT [DF_RequestExternalRef_EnteredAt] DEFAULT SYSUTCDATETIME(),
    [CreatedAt] DATETIME2(3) NOT NULL CONSTRAINT [DF_RequestExternalRef_CreatedAt] DEFAULT SYSUTCDATETIME(),
    [CreatedBy] BIGINT NULL,
    [UpdatedAt] DATETIME2(3) NULL,
    [UpdatedBy] BIGINT NULL,
    [RowVersion] ROWVERSION NOT NULL,
    CONSTRAINT [PK_RequestExternalRef] PRIMARY KEY CLUSTERED ([RequestExternalRefId]),
    CONSTRAINT [UQ_RequestExternalRef_Tenant] UNIQUE ([TenantId], [RequestExternalRefId]),
    CONSTRAINT [UQ_RequestExternalRef_Scope_RequestId] UNIQUE ([TenantId], [RequestId], [RequestExternalRefId]),
    CONSTRAINT [CK_RequestExternalRef_1] CHECK (IsActive = 0 OR SupersededById IS NULL),
    CONSTRAINT [CK_RequestExternalRef_2] CHECK (SupersededById IS NULL OR SupersededById <> RequestExternalRefId)
);
GO
-- دخول طلب إلى مرحلة؛ مصدر مقاييس الأزمنة والسحب والـ SLA (BR-WFL-002/007/012، §8)
CREATE TABLE [wfl].[RequestStageInstance] (
    [TenantId] INT NOT NULL,
    [RequestStageInstanceId] BIGINT IDENTITY(1,1) NOT NULL,
    [RequestId] BIGINT NOT NULL,
    [TemplateId] INT NOT NULL,
    [StageId] INT NOT NULL,
    [CycleNo] INT NOT NULL CONSTRAINT [DF_RequestStageInstance_CycleNo] DEFAULT 1,
    [Status] VARCHAR(17) NOT NULL,
    [EnteredAt] DATETIME2(3) NOT NULL,
    [QueuedAt] DATETIME2(3) NULL,
    [ClaimedAt] DATETIME2(3) NULL,
    [ExitedAt] DATETIME2(3) NULL,
    [ExitAction] VARCHAR(10) NULL,
    [AssigneeUserId] BIGINT NULL,
    [DueAt] DATETIME2(3) NULL,
    [ClaimDueAt] DATETIME2(3) NULL,
    [SlaPausedSeconds] INT NOT NULL CONSTRAINT [DF_RequestStageInstance_SlaPausedSeconds] DEFAULT 0,
    [SlaState] VARCHAR(10) NOT NULL CONSTRAINT [DF_RequestStageInstance_SlaState] DEFAULT 'NONE',
    [SlaMet] BIT NULL,
    [ReleaseCount] INT NOT NULL CONSTRAINT [DF_RequestStageInstance_ReleaseCount] DEFAULT 0,
    [ReassignCount] INT NOT NULL CONSTRAINT [DF_RequestStageInstance_ReassignCount] DEFAULT 0,
    [ResumeStageId] INT NULL,
    [CreatedAt] DATETIME2(3) NOT NULL CONSTRAINT [DF_RequestStageInstance_CreatedAt] DEFAULT SYSUTCDATETIME(),
    [CreatedBy] BIGINT NULL,
    [UpdatedAt] DATETIME2(3) NULL,
    [UpdatedBy] BIGINT NULL,
    [RowVersion] ROWVERSION NOT NULL,
    CONSTRAINT [PK_RequestStageInstance] PRIMARY KEY CLUSTERED ([RequestStageInstanceId]),
    CONSTRAINT [UQ_RequestStageInstance_Tenant] UNIQUE ([TenantId], [RequestStageInstanceId]),
    CONSTRAINT [UQ_RequestStageInstance_Scope_RequestId] UNIQUE ([TenantId], [RequestId], [RequestStageInstanceId]),
    CONSTRAINT [CK_RequestStageInstance_1] CHECK ((ExitedAt IS NULL AND ExitAction IS NULL AND Status IN ('QUEUED','CLAIMED','AWAITING_APPROVAL')) OR (ExitedAt IS NOT NULL AND ExitAction IS NOT NULL AND Status IN ('DONE','RETURNED','REJECTED','CANCELLED'))),
    CONSTRAINT [CK_RequestStageInstance_2] CHECK (Status <> 'RETURNED' OR ExitAction = 'RETURN'),
    CONSTRAINT [CK_RequestStageInstance_3] CHECK (Status <> 'REJECTED' OR ExitAction = 'REJECT'),
    CONSTRAINT [CK_RequestStageInstance_4] CHECK (Status <> 'CANCELLED' OR ExitAction = 'CANCEL'),
    CONSTRAINT [CK_RequestStageInstance_5] CHECK (Status <> 'QUEUED' OR AssigneeUserId IS NULL),
    CONSTRAINT [CK_RequestStageInstance_6] CHECK (Status <> 'CLAIMED' OR AssigneeUserId IS NOT NULL),
    CONSTRAINT [CK_RequestStageInstance_7] CHECK (ClaimedAt IS NULL OR QueuedAt IS NOT NULL),
    CONSTRAINT [CK_RequestStageInstance_8] CHECK (ExitedAt IS NULL OR ExitedAt >= EnteredAt),
    CONSTRAINT [CK_RequestStageInstance_9] CHECK (QueuedAt IS NULL OR QueuedAt >= EnteredAt),
    CONSTRAINT [CK_RequestStageInstance_10] CHECK (ClaimedAt IS NULL OR QueuedAt IS NULL OR ClaimedAt >= QueuedAt),
    CONSTRAINT [CK_RequestStageInstance_11] CHECK (SlaPausedSeconds >= 0 AND ReleaseCount >= 0 AND ReassignCount >= 0),
    CONSTRAINT [CK_RequestStageInstance_12] CHECK (CycleNo >= 1),
    CONSTRAINT [CK_RequestStageInstance_Status] CHECK ([Status] IS NULL OR [Status] IN ('QUEUED', 'CLAIMED', 'AWAITING_APPROVAL', 'DONE', 'RETURNED', 'REJECTED', 'CANCELLED')),
    CONSTRAINT [CK_RequestStageInstance_ExitAction] CHECK ([ExitAction] IS NULL OR [ExitAction] IN ('SUBMIT', 'APPROVE', 'COMPLETE', 'RETURN', 'REJECT', 'CANCEL', 'RESUBMIT')),
    CONSTRAINT [CK_RequestStageInstance_SlaState] CHECK ([SlaState] IS NULL OR [SlaState] IN ('ON_TRACK', 'AT_RISK', 'OVERDUE', 'PAUSED', 'NONE'))
);
GO
-- خانة موافقة تُنشأ لكل دخول ودورة؛ الدورة الجديدة بخانات جديدة (BR-WFL-003، FR-WFL-007/008/011)
CREATE TABLE [wfl].[RequestApproval] (
    [TenantId] INT NOT NULL,
    [RequestApprovalId] BIGINT IDENTITY(1,1) NOT NULL,
    [RequestId] BIGINT NOT NULL,
    [StageInstanceId] BIGINT NOT NULL,
    [CycleNo] INT NOT NULL CONSTRAINT [DF_RequestApproval_CycleNo] DEFAULT 1,
    [SlotKey] VARCHAR(30) NOT NULL,
    [AssignedUserId] BIGINT NULL,
    [AssignedRoleId] BIGINT NULL,
    [Decision] VARCHAR(10) NOT NULL CONSTRAINT [DF_RequestApproval_Decision] DEFAULT 'PENDING',
    [Source] VARCHAR(10) NULL,
    [ActedByUserId] BIGINT NULL,
    [OnBehalfOfUserId] BIGINT NULL,
    [DelegationId] BIGINT NULL,
    [ActedAt] DATETIME2(3) NULL,
    [Comment] NVARCHAR(2000) NULL,
    [SnapshotHash] VARBINARY(32) NULL,
    [ClientIp] VARCHAR(45) NULL,
    [AckWarningsJson] NVARCHAR(MAX) NULL,
    [AvailabilitySnapshotJson] NVARCHAR(MAX) NULL,
    [OverrideRequested] BIT NOT NULL CONSTRAINT [DF_RequestApproval_OverrideRequested] DEFAULT 0,
    [OverrideReason] NVARCHAR(500) NULL,
    [IsSodException] BIT NOT NULL CONSTRAINT [DF_RequestApproval_IsSodException] DEFAULT 0,
    [CreatedAt] DATETIME2(3) NOT NULL CONSTRAINT [DF_RequestApproval_CreatedAt] DEFAULT SYSUTCDATETIME(),
    [CreatedBy] BIGINT NULL,
    [UpdatedAt] DATETIME2(3) NULL,
    [UpdatedBy] BIGINT NULL,
    [RowVersion] ROWVERSION NOT NULL,
    CONSTRAINT [PK_RequestApproval] PRIMARY KEY CLUSTERED ([RequestApprovalId]),
    CONSTRAINT [UQ_RequestApproval_Tenant] UNIQUE ([TenantId], [RequestApprovalId]),
    CONSTRAINT [UQ_RequestApproval_StageInstanceId_SlotKey] UNIQUE ([TenantId], [StageInstanceId], [SlotKey]),
    CONSTRAINT [CK_RequestApproval_1] CHECK ((Decision = 'PENDING' AND ActedAt IS NULL) OR (Decision <> 'PENDING' AND ActedAt IS NOT NULL)),
    CONSTRAINT [CK_RequestApproval_2] CHECK (AssignedUserId IS NOT NULL OR AssignedRoleId IS NOT NULL),
    CONSTRAINT [CK_RequestApproval_3] CHECK (Decision NOT IN ('APPROVED','RETURNED','REJECTED') OR ActedByUserId IS NOT NULL),
    CONSTRAINT [CK_RequestApproval_4] CHECK (Decision <> 'APPROVED' OR SnapshotHash IS NOT NULL),
    CONSTRAINT [CK_RequestApproval_5] CHECK (Source <> 'DELEGATE' OR (DelegationId IS NOT NULL AND OnBehalfOfUserId IS NOT NULL)),
    CONSTRAINT [CK_RequestApproval_6] CHECK (OverrideRequested = 0 OR OverrideReason IS NOT NULL),
    CONSTRAINT [CK_RequestApproval_7] CHECK (CycleNo >= 1),
    CONSTRAINT [CK_RequestApproval_Decision] CHECK ([Decision] IS NULL OR [Decision] IN ('PENDING', 'APPROVED', 'RETURNED', 'REJECTED', 'VOIDED', 'SUPERSEDED')),
    CONSTRAINT [CK_RequestApproval_Source] CHECK ([Source] IS NULL OR [Source] IN ('USER', 'SUBMISSION', 'DELEGATE', 'SYSTEM')),
    CONSTRAINT [CK_RequestApproval_AckWarningsJson_json] CHECK ([AckWarningsJson] IS NULL OR ISJSON([AckWarningsJson]) = 1),
    CONSTRAINT [CK_RequestApproval_AvailabilitySnapshotJson_json] CHECK ([AvailabilitySnapshotJson] IS NULL OR ISJSON([AvailabilitySnapshotJson]) = 1)
);
GO
-- سجل إجراءات للإضافة فقط يغطي كل حدث؛ غير AuditLog الأمني (FR-WFL-033/034، §6.2)
CREATE TABLE [wfl].[RequestAction] (
    [TenantId] INT NOT NULL,
    [RequestActionId] BIGINT IDENTITY(1,1) NOT NULL,
    [RequestId] BIGINT NOT NULL,
    [StageInstanceId] BIGINT NULL,
    [CycleNo] INT NULL,
    [ActionType] VARCHAR(18) NOT NULL,
    [FromStageKey] VARCHAR(40) NULL,
    [ToStageKey] VARCHAR(40) NULL,
    [ActorType] VARCHAR(10) NOT NULL CONSTRAINT [DF_RequestAction_ActorType] DEFAULT 'USER',
    [ActorUserId] BIGINT NULL,
    [OnBehalfOfUserId] BIGINT NULL,
    [OccurredAt] DATETIME2(3) NOT NULL CONSTRAINT [DF_RequestAction_OccurredAt] DEFAULT SYSUTCDATETIME(),
    [Visibility] VARCHAR(17) NOT NULL CONSTRAINT [DF_RequestAction_Visibility] DEFAULT 'INTERNAL',
    [Comment] NVARCHAR(4000) NULL,
    [MetaJson] NVARCHAR(MAX) NULL,
    [SnapshotJson] NVARCHAR(MAX) NULL,
    [CorrelationId] UNIQUEIDENTIFIER NULL,
    [IdempotencyKey] VARCHAR(100) NULL,
    [IsSodException] BIT NOT NULL CONSTRAINT [DF_RequestAction_IsSodException] DEFAULT 0,
    [CreatedAt] DATETIME2(3) NOT NULL CONSTRAINT [DF_RequestAction_CreatedAt] DEFAULT SYSUTCDATETIME(),
    [CreatedBy] BIGINT NULL,
    CONSTRAINT [PK_RequestAction] PRIMARY KEY CLUSTERED ([RequestActionId]),
    CONSTRAINT [UQ_RequestAction_Tenant] UNIQUE ([TenantId], [RequestActionId]),
    CONSTRAINT [CK_RequestAction_1] CHECK (ActorType <> 'USER' OR ActorUserId IS NOT NULL),
    CONSTRAINT [CK_RequestAction_2] CHECK (ActionType NOT IN ('RETURNED','REJECTED') OR Comment IS NOT NULL),
    CONSTRAINT [CK_RequestAction_ActionType] CHECK ([ActionType] IS NULL OR [ActionType] IN ('CREATED', 'SUBMITTED', 'RESUBMITTED', 'NUMBER_ASSIGNED', 'FIELD_EDITED', 'APPROVED', 'RETURNED', 'REJECTED', 'CANCELLED', 'STAGE_CHANGED', 'SUBSTATUS_CHANGED', 'CLAIMED', 'RELEASED', 'REASSIGNED', 'COMMENT_ADDED', 'ATTACHMENT_ADDED', 'ATTACHMENT_REMOVED', 'EXTREF_ADDED', 'EXTREF_CHANGED', 'HOOK_EXECUTED', 'HOOK_FAILED', 'SLA_AT_RISK', 'SLA_BREACHED', 'ESCALATED', 'DELEGATED_ACTION', 'CHILD_CREATED', 'PRIORITY_CHANGED', 'TEMPLATE_MIGRATED', 'RESERVATION_LOST', 'DRAFT_ARCHIVED', 'DRAFT_RESTORED', 'CHANNEL_CHANGED', 'SOD_EXCEPTION_USED', 'DELEGATION_CREATED', 'DELEGATION_REVOKED', 'READY_TO_CLOSE', 'CLOSED')),
    CONSTRAINT [CK_RequestAction_ActorType] CHECK ([ActorType] IS NULL OR [ActorType] IN ('USER', 'SYSTEM', 'SERVICE')),
    CONSTRAINT [CK_RequestAction_Visibility] CHECK ([Visibility] IS NULL OR [Visibility] IN ('INTERNAL', 'REQUESTER_VISIBLE')),
    CONSTRAINT [CK_RequestAction_MetaJson_json] CHECK ([MetaJson] IS NULL OR ISJSON([MetaJson]) = 1),
    CONSTRAINT [CK_RequestAction_SnapshotJson_json] CHECK ([SnapshotJson] IS NULL OR ISJSON([SnapshotJson]) = 1)
);
GO
-- تنفيذ خطاف بمفتاح عدم تكرار يعيد النتيجة المخزَّنة (FR-WFL-021، BR-WFL-015) -- جدول جديد
CREATE TABLE [wfl].[HookExecution] (
    [TenantId] INT NOT NULL,
    [HookExecutionId] BIGINT IDENTITY(1,1) NOT NULL,
    [RequestId] BIGINT NOT NULL,
    [StageInstanceId] BIGINT NOT NULL,
    [HookKey] VARCHAR(60) NOT NULL,
    [TriggerKind] VARCHAR(10) NOT NULL,
    [ActionFilter] VARCHAR(10) NULL,
    [ExecMode] VARCHAR(12) NOT NULL,
    [OnFailure] VARCHAR(10) NOT NULL,
    [Status] VARCHAR(10) NOT NULL CONSTRAINT [DF_HookExecution_Status] DEFAULT 'PENDING',
    [AttemptCount] INT NOT NULL CONSTRAINT [DF_HookExecution_AttemptCount] DEFAULT 0,
    [IdempotencyKey] VARCHAR(100) NULL,
    [ResultJson] NVARCHAR(MAX) NULL,
    [ErrorCode] VARCHAR(60) NULL,
    [LastError] NVARCHAR(1000) NULL,
    [ExecutedAt] DATETIME2(3) NULL,
    [NextAttemptAt] DATETIME2(3) NULL,
    [TmNotifiedAt] DATETIME2(3) NULL,
    [CreatedAt] DATETIME2(3) NOT NULL CONSTRAINT [DF_HookExecution_CreatedAt] DEFAULT SYSUTCDATETIME(),
    [CreatedBy] BIGINT NULL,
    [UpdatedAt] DATETIME2(3) NULL,
    [UpdatedBy] BIGINT NULL,
    [RowVersion] ROWVERSION NOT NULL,
    CONSTRAINT [PK_HookExecution] PRIMARY KEY CLUSTERED ([HookExecutionId]),
    CONSTRAINT [UQ_HookExecution_Tenant] UNIQUE ([TenantId], [HookExecutionId]),
    CONSTRAINT [UQ_HookExecution_RequestId_StageInstanceId_HookKey_TriggerKind] UNIQUE ([TenantId], [RequestId], [StageInstanceId], [HookKey], [TriggerKind]),
    CONSTRAINT [CK_HookExecution_1] CHECK (AttemptCount >= 0),
    CONSTRAINT [CK_HookExecution_2] CHECK (Status <> 'SUCCEEDED' OR ExecutedAt IS NOT NULL),
    CONSTRAINT [CK_HookExecution_3] CHECK (Status <> 'GAVE_UP' OR (ExecMode = 'AFTER_COMMIT' AND AttemptCount >= 5)),
    CONSTRAINT [CK_HookExecution_TriggerKind] CHECK ([TriggerKind] IS NULL OR [TriggerKind] IN ('ON_ENTER', 'ON_EXIT', 'ON_ACTION')),
    CONSTRAINT [CK_HookExecution_ActionFilter] CHECK ([ActionFilter] IS NULL OR [ActionFilter] IN ('SUBMIT', 'APPROVE', 'COMPLETE', 'RETURN', 'REJECT', 'CANCEL', 'RESUBMIT')),
    CONSTRAINT [CK_HookExecution_ExecMode] CHECK ([ExecMode] IS NULL OR [ExecMode] IN ('SYNC_TX', 'AFTER_COMMIT')),
    CONSTRAINT [CK_HookExecution_OnFailure] CHECK ([OnFailure] IS NULL OR [OnFailure] IN ('BLOCK', 'WARN')),
    CONSTRAINT [CK_HookExecution_Status] CHECK ([Status] IS NULL OR [Status] IN ('PENDING', 'SUCCEEDED', 'FAILED', 'GAVE_UP')),
    CONSTRAINT [CK_HookExecution_ResultJson_json] CHECK ([ResultJson] IS NULL OR ISJSON([ResultJson]) = 1)
);
GO
-- تفويض مهام بفترة ونطاق؛ لا تفويض متسلسل (FR-WFL-020، BR-WFL-021، V-WFL-06)
CREATE TABLE [wfl].[UserDelegation] (
    [TenantId] INT NOT NULL,
    [UserDelegationId] BIGINT IDENTITY(1,1) NOT NULL,
    [FromUserId] BIGINT NOT NULL,
    [ToUserId] BIGINT NOT NULL,
    [StartsOn] DATE NOT NULL,
    [EndsOn] DATE NOT NULL,
    [Scope] VARCHAR(14) NOT NULL CONSTRAINT [DF_UserDelegation_Scope] DEFAULT 'ALL',
    [RequestTypeId] INT NULL,
    [Reason] NVARCHAR(500) NULL,
    [Status] VARCHAR(10) NOT NULL CONSTRAINT [DF_UserDelegation_Status] DEFAULT 'SCHEDULED',
    [RevokedAt] DATETIME2(3) NULL,
    [RevokedBy] BIGINT NULL,
    [PublicId] UNIQUEIDENTIFIER NOT NULL CONSTRAINT [DF_UserDelegation_PublicId] DEFAULT NEWSEQUENTIALID(),
    [CreatedAt] DATETIME2(3) NOT NULL CONSTRAINT [DF_UserDelegation_CreatedAt] DEFAULT SYSUTCDATETIME(),
    [CreatedBy] BIGINT NULL,
    [UpdatedAt] DATETIME2(3) NULL,
    [UpdatedBy] BIGINT NULL,
    [RowVersion] ROWVERSION NOT NULL,
    CONSTRAINT [PK_UserDelegation] PRIMARY KEY CLUSTERED ([UserDelegationId]),
    CONSTRAINT [UQ_UserDelegation_Tenant] UNIQUE ([TenantId], [UserDelegationId]),
    CONSTRAINT [UQ_UserDelegation_PublicId] UNIQUE ([PublicId]),
    CONSTRAINT [CK_UserDelegation_1] CHECK (FromUserId <> ToUserId),
    CONSTRAINT [CK_UserDelegation_2] CHECK (EndsOn >= StartsOn),
    CONSTRAINT [CK_UserDelegation_3] CHECK ((Scope = 'REQUEST_TYPE' AND RequestTypeId IS NOT NULL) OR (Scope <> 'REQUEST_TYPE' AND RequestTypeId IS NULL)),
    CONSTRAINT [CK_UserDelegation_4] CHECK ((Status = 'REVOKED' AND RevokedAt IS NOT NULL) OR (Status <> 'REVOKED' AND RevokedAt IS NULL)),
    CONSTRAINT [CK_UserDelegation_Scope] CHECK ([Scope] IS NULL OR [Scope] IN ('ALL', 'APPROVALS_ONLY', 'REQUEST_TYPE')),
    CONSTRAINT [CK_UserDelegation_Status] CHECK ([Status] IS NULL OR [Status] IN ('SCHEDULED', 'ACTIVE', 'ENDED', 'REVOKED'))
);
GO

-- ===== schema ntf =====
-- كتالوج الأحداث؛ تملكه 13 لكل الوحدات وتبذر فيه الوحدات أحداثها (FR-NTF-001، §9.2، §9.2-ب)
CREATE TABLE [ntf].[NotificationEventType] (
    [TenantId] INT NOT NULL,
    [NotificationEventTypeId] INT IDENTITY(1,1) NOT NULL,
    [Code] VARCHAR(60) NOT NULL,
    [OwnerModule] VARCHAR(20) NOT NULL,
    [GroupKey] VARCHAR(30) NOT NULL,
    [NameAr] NVARCHAR(200) NULL,
    [NameEn] NVARCHAR(200) NULL,
    [DefaultSeverity] VARCHAR(10) NOT NULL CONSTRAINT [DF_NotificationEventType_DefaultSeverity] DEFAULT 'INFO',
    [IsMandatory] BIT NOT NULL CONSTRAINT [DF_NotificationEventType_IsMandatory] DEFAULT 0,
    [IsActionRequired] BIT NOT NULL CONSTRAINT [DF_NotificationEventType_IsActionRequired] DEFAULT 0,
    [DefaultChannels] NVARCHAR(MAX) NULL,
    [AllowedPlaceholdersJson] NVARCHAR(MAX) NULL,
    [DedupWindowMinutes] INT NULL,
    [CoalesceWindowMinutes] INT NULL,
    [SeedKey] VARCHAR(80) NULL,
    [CreatedAt] DATETIME2(3) NOT NULL CONSTRAINT [DF_NotificationEventType_CreatedAt] DEFAULT SYSUTCDATETIME(),
    [CreatedBy] BIGINT NULL,
    [UpdatedAt] DATETIME2(3) NULL,
    [UpdatedBy] BIGINT NULL,
    [RowVersion] ROWVERSION NOT NULL,
    CONSTRAINT [PK_NotificationEventType] PRIMARY KEY CLUSTERED ([NotificationEventTypeId]),
    CONSTRAINT [UQ_NotificationEventType_Tenant] UNIQUE ([TenantId], [NotificationEventTypeId]),
    CONSTRAINT [UQ_NotificationEventType_Code] UNIQUE ([TenantId], [Code]),
    CONSTRAINT [CK_NotificationEventType_1] CHECK (Code LIKE '%.%'),
    CONSTRAINT [CK_NotificationEventType_2] CHECK (NameAr IS NOT NULL OR NameEn IS NOT NULL),
    CONSTRAINT [CK_NotificationEventType_3] CHECK (DedupWindowMinutes IS NULL OR DedupWindowMinutes >= 0),
    CONSTRAINT [CK_NotificationEventType_4] CHECK (CoalesceWindowMinutes IS NULL OR CoalesceWindowMinutes = 0 OR (IsMandatory = 0 AND DefaultSeverity <> 'HIGH')),
    CONSTRAINT [CK_NotificationEventType_DefaultSeverity] CHECK ([DefaultSeverity] IS NULL OR [DefaultSeverity] IN ('INFO', 'WARNING', 'HIGH')),
    CONSTRAINT [CK_NotificationEventType_DefaultChannels_json] CHECK ([DefaultChannels] IS NULL OR ISJSON([DefaultChannels]) = 1),
    CONSTRAINT [CK_NotificationEventType_AllowedPlaceholdersJson_json] CHECK ([AllowedPlaceholdersJson] IS NULL OR ISJSON([AllowedPlaceholdersJson]) = 1)
);
GO
-- قاعدة مستلمين لحدث؛ التعديل يسري على الأحداث التالية فقط (FR-NTF-003، BR-NTF-001، V-NTF-02)
CREATE TABLE [ntf].[NotificationRule] (
    [TenantId] INT NOT NULL,
    [NotificationRuleId] INT IDENTITY(1,1) NOT NULL,
    [EventTypeId] INT NOT NULL,
    [RecipientKind] VARCHAR(17) NOT NULL,
    [RoleId] BIGINT NULL,
    [PermissionId] INT NULL,
    [UserId] BIGINT NULL,
    [ConditionJson] NVARCHAR(MAX) NULL,
    [RequireCompanyScope] BIT NOT NULL CONSTRAINT [DF_NotificationRule_RequireCompanyScope] DEFAULT 1,
    [ChannelsOverride] NVARCHAR(MAX) NULL,
    [IsMandatory] BIT NOT NULL CONSTRAINT [DF_NotificationRule_IsMandatory] DEFAULT 0,
    [IsActive] BIT NOT NULL CONSTRAINT [DF_NotificationRule_IsActive] DEFAULT 1,
    [SeedKey] VARCHAR(80) NULL,
    [CreatedAt] DATETIME2(3) NOT NULL CONSTRAINT [DF_NotificationRule_CreatedAt] DEFAULT SYSUTCDATETIME(),
    [CreatedBy] BIGINT NULL,
    [UpdatedAt] DATETIME2(3) NULL,
    [UpdatedBy] BIGINT NULL,
    [RowVersion] ROWVERSION NOT NULL,
    CONSTRAINT [PK_NotificationRule] PRIMARY KEY CLUSTERED ([NotificationRuleId]),
    CONSTRAINT [UQ_NotificationRule_Tenant] UNIQUE ([TenantId], [NotificationRuleId]),
    CONSTRAINT [CK_NotificationRule_1] CHECK ((RecipientKind = 'ROLE' AND RoleId IS NOT NULL AND PermissionId IS NULL AND UserId IS NULL) OR (RecipientKind = 'PERMISSION' AND PermissionId IS NOT NULL AND RoleId IS NULL AND UserId IS NULL) OR (RecipientKind = 'USER' AND UserId IS NOT NULL AND RoleId IS NULL AND PermissionId IS NULL) OR (RecipientKind NOT IN ('ROLE','PERMISSION','USER') AND RoleId IS NULL AND PermissionId IS NULL AND UserId IS NULL)),
    CONSTRAINT [CK_NotificationRule_2] CHECK (IsMandatory = 0 OR IsActive = 1),
    CONSTRAINT [CK_NotificationRule_RecipientKind] CHECK ([RecipientKind] IS NULL OR [RecipientKind] IN ('ROLE', 'PERMISSION', 'USER', 'REQUESTER', 'REQUESTER_MANAGER', 'ASSIGNEE', 'STAGE_APPROVERS', 'DEPARTMENT_HEAD')),
    CONSTRAINT [CK_NotificationRule_ConditionJson_json] CHECK ([ConditionJson] IS NULL OR ISJSON([ConditionJson]) = 1),
    CONSTRAINT [CK_NotificationRule_ChannelsOverride_json] CHECK ([ChannelsOverride] IS NULL OR ISJSON([ChannelsOverride]) = 1)
);
GO
-- قالب رسالة لكل (حدث، قناة، لغة)؛ الحذف = العودة إلى قالب البذرة (FR-NTF-012، FR-NTF-025)
CREATE TABLE [ntf].[NotificationTemplate] (
    [TenantId] INT NOT NULL,
    [NotificationTemplateId] INT IDENTITY(1,1) NOT NULL,
    [EventTypeId] INT NOT NULL,
    [Channel] VARCHAR(10) NOT NULL,
    [Lang] VARCHAR(10) NOT NULL,
    [SubjectTemplate] NVARCHAR(300) NOT NULL,
    [BodyTemplate] NVARCHAR(MAX) NOT NULL,
    [IsTenantOverride] BIT NOT NULL CONSTRAINT [DF_NotificationTemplate_IsTenantOverride] DEFAULT 0,
    [CreatedAt] DATETIME2(3) NOT NULL CONSTRAINT [DF_NotificationTemplate_CreatedAt] DEFAULT SYSUTCDATETIME(),
    [CreatedBy] BIGINT NULL,
    [UpdatedAt] DATETIME2(3) NULL,
    [UpdatedBy] BIGINT NULL,
    [RowVersion] ROWVERSION NOT NULL,
    CONSTRAINT [PK_NotificationTemplate] PRIMARY KEY CLUSTERED ([NotificationTemplateId]),
    CONSTRAINT [UQ_NotificationTemplate_Tenant] UNIQUE ([TenantId], [NotificationTemplateId]),
    CONSTRAINT [UQ_NotificationTemplate_EventTypeId_Channel_Lang_IsTenantOverride] UNIQUE ([TenantId], [EventTypeId], [Channel], [Lang], [IsTenantOverride]),
    CONSTRAINT [CK_NotificationTemplate_Channel] CHECK ([Channel] IS NULL OR [Channel] IN ('IN_APP', 'EMAIL')),
    CONSTRAINT [CK_NotificationTemplate_Lang] CHECK ([Lang] IS NULL OR [Lang] IN ('ar', 'en'))
);
GO
-- تفضيل المستخدم لكل مجموعة أحداث وقناة (FR-NTF-010، BR-NTF-003/014)؛ الإلزامي لا يُوقَف في التطبيق
CREATE TABLE [ntf].[NotificationPreference] (
    [TenantId] INT NOT NULL,
    [NotificationPreferenceId] BIGINT IDENTITY(1,1) NOT NULL,
    [UserId] BIGINT NOT NULL,
    [GroupKey] VARCHAR(30) NOT NULL,
    [Channel] VARCHAR(10) NOT NULL,
    [Mode] VARCHAR(13) NOT NULL CONSTRAINT [DF_NotificationPreference_Mode] DEFAULT 'IMMEDIATE',
    [CreatedAt] DATETIME2(3) NOT NULL CONSTRAINT [DF_NotificationPreference_CreatedAt] DEFAULT SYSUTCDATETIME(),
    [CreatedBy] BIGINT NULL,
    [UpdatedAt] DATETIME2(3) NULL,
    [UpdatedBy] BIGINT NULL,
    [RowVersion] ROWVERSION NOT NULL,
    CONSTRAINT [PK_NotificationPreference] PRIMARY KEY CLUSTERED ([NotificationPreferenceId]),
    CONSTRAINT [UQ_NotificationPreference_Tenant] UNIQUE ([TenantId], [NotificationPreferenceId]),
    CONSTRAINT [UQ_NotificationPreference_UserId_GroupKey_Channel] UNIQUE ([TenantId], [UserId], [GroupKey], [Channel]),
    CONSTRAINT [CK_NotificationPreference_Channel] CHECK ([Channel] IS NULL OR [Channel] IN ('IN_APP', 'EMAIL')),
    CONSTRAINT [CK_NotificationPreference_Mode] CHECK ([Mode] IS NULL OR [Mode] IN ('IMMEDIATE', 'DIGEST_DAILY', 'DIGEST_WEEKLY', 'OFF'))
);
GO
-- دفعة ملخص لمستخدم وقناة وفترة؛ لا يُرسل فارغًا (FR-NTF-014، BR-NTF-004، JOB-NTF-DIGEST) -- جدول جديد
CREATE TABLE [ntf].[DigestBatch] (
    [TenantId] INT NOT NULL,
    [DigestBatchId] BIGINT IDENTITY(1,1) NOT NULL,
    [UserId] BIGINT NOT NULL,
    [Channel] VARCHAR(10) NOT NULL CONSTRAINT [DF_DigestBatch_Channel] DEFAULT 'EMAIL',
    [Kind] VARCHAR(10) NOT NULL,
    [PeriodStart] DATETIME2(3) NOT NULL,
    [PeriodEnd] DATETIME2(3) NOT NULL,
    [Status] VARCHAR(13) NOT NULL CONSTRAINT [DF_DigestBatch_Status] DEFAULT 'PENDING',
    [ItemCount] INT NOT NULL CONSTRAINT [DF_DigestBatch_ItemCount] DEFAULT 0,
    [GroupSummaryJson] NVARCHAR(MAX) NULL,
    [ScheduledFor] DATETIME2(3) NULL,
    [SentAt] DATETIME2(3) NULL,
    [CreatedAt] DATETIME2(3) NOT NULL CONSTRAINT [DF_DigestBatch_CreatedAt] DEFAULT SYSUTCDATETIME(),
    [CreatedBy] BIGINT NULL,
    [UpdatedAt] DATETIME2(3) NULL,
    [UpdatedBy] BIGINT NULL,
    [RowVersion] ROWVERSION NOT NULL,
    CONSTRAINT [PK_DigestBatch] PRIMARY KEY CLUSTERED ([DigestBatchId]),
    CONSTRAINT [UQ_DigestBatch_Tenant] UNIQUE ([TenantId], [DigestBatchId]),
    CONSTRAINT [UQ_DigestBatch_UserId_Channel_Kind_PeriodEnd] UNIQUE ([TenantId], [UserId], [Channel], [Kind], [PeriodEnd]),
    CONSTRAINT [CK_DigestBatch_1] CHECK (PeriodEnd > PeriodStart),
    CONSTRAINT [CK_DigestBatch_2] CHECK (ItemCount >= 0),
    CONSTRAINT [CK_DigestBatch_3] CHECK (Status <> 'SENT' OR (SentAt IS NOT NULL AND ItemCount > 0)),
    CONSTRAINT [CK_DigestBatch_4] CHECK (Status <> 'SKIPPED_EMPTY' OR ItemCount = 0),
    CONSTRAINT [CK_DigestBatch_Channel] CHECK ([Channel] IS NULL OR [Channel] IN ('IN_APP', 'EMAIL')),
    CONSTRAINT [CK_DigestBatch_Kind] CHECK ([Kind] IS NULL OR [Kind] IN ('DAILY', 'WEEKLY')),
    CONSTRAINT [CK_DigestBatch_Status] CHECK ([Status] IS NULL OR [Status] IN ('PENDING', 'SENT', 'SKIPPED_EMPTY', 'FAILED')),
    CONSTRAINT [CK_DigestBatch_GroupSummaryJson_json] CHECK ([GroupSummaryJson] IS NULL OR ISJSON([GroupSummaryJson]) = 1)
);
GO
-- إشعار لمستخدم؛ المحتوى بلا قيم مقيّدة (FR-NTF-005/006/007/021، BR-NTF-001/002/007/008/011)
CREATE TABLE [ntf].[Notification] (
    [TenantId] INT NOT NULL,
    [NotificationId] BIGINT IDENTITY(1,1) NOT NULL,
    [UserId] BIGINT NOT NULL,
    [EventTypeId] INT NOT NULL,
    [CompanyId] BIGINT NULL,
    [Severity] VARCHAR(10) NOT NULL,
    [Title] NVARCHAR(300) NOT NULL,
    [Body] NVARCHAR(2000) NOT NULL,
    [TargetEntityType] VARCHAR(60) NOT NULL,
    [TargetEntityId] BIGINT NOT NULL,
    [DeepLink] NVARCHAR(300) NULL,
    [ActionRequired] BIT NOT NULL CONSTRAINT [DF_Notification_ActionRequired] DEFAULT 0,
    [ActionState] VARCHAR(10) NOT NULL CONSTRAINT [DF_Notification_ActionState] DEFAULT 'NONE',
    [ResolvedAt] DATETIME2(3) NULL,
    [ReadAt] DATETIME2(3) NULL,
    [ArchivedAt] DATETIME2(3) NULL,
    [DedupKey] VARCHAR(200) NULL,
    [CoalescedCount] INT NOT NULL CONSTRAINT [DF_Notification_CoalescedCount] DEFAULT 1,
    [ReminderCount] INT NOT NULL CONSTRAINT [DF_Notification_ReminderCount] DEFAULT 0,
    [NextReminderAt] DATETIME2(3) NULL,
    [PayloadJson] NVARCHAR(MAX) NULL,
    [SourceEventId] UNIQUEIDENTIFIER NULL,
    [PublicId] UNIQUEIDENTIFIER NOT NULL CONSTRAINT [DF_Notification_PublicId] DEFAULT NEWSEQUENTIALID(),
    [CreatedAt] DATETIME2(3) NOT NULL CONSTRAINT [DF_Notification_CreatedAt] DEFAULT SYSUTCDATETIME(),
    [CreatedBy] BIGINT NULL,
    [UpdatedAt] DATETIME2(3) NULL,
    [UpdatedBy] BIGINT NULL,
    [RowVersion] ROWVERSION NOT NULL,
    CONSTRAINT [PK_Notification] PRIMARY KEY CLUSTERED ([NotificationId]),
    CONSTRAINT [UQ_Notification_Tenant] UNIQUE ([TenantId], [NotificationId]),
    CONSTRAINT [UQ_Notification_PublicId] UNIQUE ([PublicId]),
    CONSTRAINT [CK_Notification_1] CHECK ((ActionRequired = 0 AND ActionState = 'NONE') OR (ActionRequired = 1 AND ActionState IN ('OPEN','RESOLVED'))),
    CONSTRAINT [CK_Notification_2] CHECK ((ActionState = 'RESOLVED' AND ResolvedAt IS NOT NULL) OR (ActionState <> 'RESOLVED' AND ResolvedAt IS NULL)),
    CONSTRAINT [CK_Notification_3] CHECK (CoalescedCount >= 1),
    CONSTRAINT [CK_Notification_4] CHECK (ReminderCount >= 0 AND ReminderCount <= 3),
    CONSTRAINT [CK_Notification_5] CHECK (NextReminderAt IS NULL OR ActionState = 'OPEN'),
    CONSTRAINT [CK_Notification_Severity] CHECK ([Severity] IS NULL OR [Severity] IN ('INFO', 'WARNING', 'HIGH')),
    CONSTRAINT [CK_Notification_ActionState] CHECK ([ActionState] IS NULL OR [ActionState] IN ('NONE', 'OPEN', 'RESOLVED')),
    CONSTRAINT [CK_Notification_PayloadJson_json] CHECK ([PayloadJson] IS NULL OR ISJSON([PayloadJson]) = 1)
);
GO
-- تسليم الإشعار لكل قناة بحالاته وإعادة المحاولة (FR-NTF-019، BR-NTF-009، §8)
CREATE TABLE [ntf].[NotificationDelivery] (
    [TenantId] INT NOT NULL,
    [NotificationDeliveryId] BIGINT IDENTITY(1,1) NOT NULL,
    [NotificationId] BIGINT NOT NULL,
    [Channel] VARCHAR(10) NOT NULL,
    [Status] VARCHAR(10) NOT NULL CONSTRAINT [DF_NotificationDelivery_Status] DEFAULT 'PENDING',
    [Attempts] INT NOT NULL CONSTRAINT [DF_NotificationDelivery_Attempts] DEFAULT 0,
    [NextAttemptAt] DATETIME2(3) NULL,
    [SentAt] DATETIME2(3) NULL,
    [DigestBatchId] BIGINT NULL,
    [ProviderMessageId] VARCHAR(200) NULL,
    [LastError] NVARCHAR(500) NULL,
    [CreatedAt] DATETIME2(3) NOT NULL CONSTRAINT [DF_NotificationDelivery_CreatedAt] DEFAULT SYSUTCDATETIME(),
    [CreatedBy] BIGINT NULL,
    [UpdatedAt] DATETIME2(3) NULL,
    [UpdatedBy] BIGINT NULL,
    [RowVersion] ROWVERSION NOT NULL,
    CONSTRAINT [PK_NotificationDelivery] PRIMARY KEY CLUSTERED ([NotificationDeliveryId]),
    CONSTRAINT [UQ_NotificationDelivery_Tenant] UNIQUE ([TenantId], [NotificationDeliveryId]),
    CONSTRAINT [UQ_NotificationDelivery_NotificationId_Channel] UNIQUE ([TenantId], [NotificationId], [Channel]),
    CONSTRAINT [CK_NotificationDelivery_1] CHECK (Attempts >= 0),
    CONSTRAINT [CK_NotificationDelivery_2] CHECK (Status = 'SENT' OR SentAt IS NULL),
    CONSTRAINT [CK_NotificationDelivery_3] CHECK (Status <> 'SENT' OR SentAt IS NOT NULL),
    CONSTRAINT [CK_NotificationDelivery_4] CHECK (Status <> 'FAILED' OR NextAttemptAt IS NOT NULL),
    CONSTRAINT [CK_NotificationDelivery_5] CHECK (Status <> 'DIGESTED' OR DigestBatchId IS NOT NULL),
    CONSTRAINT [CK_NotificationDelivery_6] CHECK (DigestBatchId IS NULL OR Status IN ('DIGESTED','SENT')),
    CONSTRAINT [CK_NotificationDelivery_Channel] CHECK ([Channel] IS NULL OR [Channel] IN ('IN_APP', 'EMAIL')),
    CONSTRAINT [CK_NotificationDelivery_Status] CHECK ([Status] IS NULL OR [Status] IN ('PENDING', 'SENT', 'FAILED', 'DEAD', 'SUPPRESSED', 'DIGESTED'))
);
GO

-- ===== schema lc =====
-- تعريف حقل في شروط الاعتماد: بيانات تُبذر لكل مشترك (FR-LCT-004، BR-LCT-002)؛ مراجع UCP في lc.LcFieldUcpRef
CREATE TABLE [lc].[LcFieldDefinition] (
    [TenantId] INT NOT NULL,
    [LcFieldDefinitionId] BIGINT IDENTITY(1,1) NOT NULL,
    [FieldKey] VARCHAR(60) NOT NULL,
    [SectionKey] VARCHAR(40) NOT NULL,
    [LabelAr] NVARCHAR(200) NOT NULL,
    [LabelEn] NVARCHAR(200) NOT NULL,
    [HelpAr] NVARCHAR(500) NULL,
    [HelpEn] NVARCHAR(500) NULL,
    [DataType] VARCHAR(10) NOT NULL,
    [ListCode] VARCHAR(80) NULL,
    [ApplicabilityJson] NVARCHAR(MAX) NOT NULL,
    [VisibleToRequester] BIT NOT NULL CONSTRAINT [DF_LcFieldDefinition_VisibleToRequester] DEFAULT 1,
    [IsLocked] BIT NOT NULL CONSTRAINT [DF_LcFieldDefinition_IsLocked] DEFAULT 0,
    [SwiftTagHint] VARCHAR(10) NULL,
    [ValidationJson] NVARCHAR(MAX) NULL,
    [DefaultValue] NVARCHAR(500) NULL,
    [SortOrder] INT NOT NULL CONSTRAINT [DF_LcFieldDefinition_SortOrder] DEFAULT 0,
    [IsActive] BIT NOT NULL CONSTRAINT [DF_LcFieldDefinition_IsActive] DEFAULT 1,
    [SeedKey] VARCHAR(80) NULL,
    [CreatedAt] DATETIME2(3) NOT NULL CONSTRAINT [DF_LcFieldDefinition_CreatedAt] DEFAULT SYSUTCDATETIME(),
    [CreatedBy] BIGINT NULL,
    [UpdatedAt] DATETIME2(3) NULL,
    [UpdatedBy] BIGINT NULL,
    [RowVersion] ROWVERSION NOT NULL,
    CONSTRAINT [PK_LcFieldDefinition] PRIMARY KEY CLUSTERED ([LcFieldDefinitionId]),
    CONSTRAINT [UQ_LcFieldDefinition_Tenant] UNIQUE ([TenantId], [LcFieldDefinitionId]),
    CONSTRAINT [UQ_LcFieldDefinition_FieldKey] UNIQUE ([TenantId], [FieldKey]),
    CONSTRAINT [CK_LcFieldDefinition_1] CHECK (FieldKey NOT LIKE '% %'),
    CONSTRAINT [CK_LcFieldDefinition_2] CHECK (IsLocked = 0 OR IsActive = 1),
    CONSTRAINT [CK_LcFieldDefinition_3] CHECK (ListCode IS NULL OR DataType IN ('LIST','ENUM')),
    CONSTRAINT [CK_LcFieldDefinition_DataType] CHECK ([DataType] IS NULL OR [DataType] IN ('STRING', 'TEXT', 'INT', 'DECIMAL', 'DATE', 'BOOL', 'ENUM', 'LIST', 'REF', 'COMPUTED')),
    CONSTRAINT [CK_LcFieldDefinition_ApplicabilityJson_json] CHECK ([ApplicabilityJson] IS NULL OR ISJSON([ApplicabilityJson]) = 1),
    CONSTRAINT [CK_LcFieldDefinition_ValidationJson_json] CHECK ([ValidationJson] IS NULL OR ISJSON([ValidationJson]) = 1)
);
GO
-- مرجع UCP لحقل: مادة + فقرة (UcpRefs في المواصفة)؛ يغذّي الشارة وR-LCT-01 وBR-LCT-018 -- وسيط جديد
CREATE TABLE [lc].[LcFieldUcpRef] (
    [TenantId] INT NOT NULL,
    [LcFieldUcpRefId] BIGINT IDENTITY(1,1) NOT NULL,
    [LcFieldDefinitionId] BIGINT NOT NULL,
    [UcpArticleId] INT NOT NULL,
    [Paragraph] NVARCHAR(20) NULL,
    [CreatedAt] DATETIME2(3) NOT NULL CONSTRAINT [DF_LcFieldUcpRef_CreatedAt] DEFAULT SYSUTCDATETIME(),
    [CreatedBy] BIGINT NULL,
    [UpdatedAt] DATETIME2(3) NULL,
    [UpdatedBy] BIGINT NULL,
    [RowVersion] ROWVERSION NOT NULL,
    CONSTRAINT [PK_LcFieldUcpRef] PRIMARY KEY CLUSTERED ([LcFieldUcpRefId]),
    CONSTRAINT [UQ_LcFieldUcpRef_Tenant] UNIQUE ([TenantId], [LcFieldUcpRefId]),
    CONSTRAINT [UQ_LcFieldUcpRef_LcFieldDefinitionId_UcpArticleId_Paragraph] UNIQUE ([TenantId], [LcFieldDefinitionId], [UcpArticleId], [Paragraph])
);
GO
-- الطرف المقابل: مورّد/عميل خفيف بلا هوية؛ يُرقّى إلى Party عند الحاجة (FR-LCT-036/037، BR-LCT-022، Q-PTY-03)
CREATE TABLE [lc].[Counterparty] (
    [TenantId] INT NOT NULL,
    [CounterpartyId] BIGINT IDENTITY(1,1) NOT NULL,
    [Code] VARCHAR(20) NOT NULL,
    [Kind] VARCHAR(10) NOT NULL,
    [NameEn] NVARCHAR(300) NOT NULL,
    [NameAr] NVARCHAR(300) NULL,
    [NameNormalized] NVARCHAR(300) NOT NULL,
    [CountryId] INT NOT NULL,
    [City] NVARCHAR(100) NULL,
    [AddressLine] NVARCHAR(300) NULL,
    [PoBox] NVARCHAR(30) NULL,
    [PostalCode] NVARCHAR(20) NULL,
    [Phone] NVARCHAR(40) NULL,
    [Fax] NVARCHAR(40) NULL,
    [Email] NVARCHAR(254) NULL,
    [ErpCode] NVARCHAR(40) NULL,
    [ErpCodeNormalized] NVARCHAR(40) NULL,
    [TaxNumber] NVARCHAR(50) NULL,
    [PartyId] BIGINT NULL,
    [MergedIntoId] BIGINT NULL,
    [IsActive] BIT NOT NULL CONSTRAINT [DF_Counterparty_IsActive] DEFAULT 1,
    [Notes] NVARCHAR(1000) NULL,
    [PublicId] UNIQUEIDENTIFIER NOT NULL CONSTRAINT [DF_Counterparty_PublicId] DEFAULT NEWSEQUENTIALID(),
    [CreatedAt] DATETIME2(3) NOT NULL CONSTRAINT [DF_Counterparty_CreatedAt] DEFAULT SYSUTCDATETIME(),
    [CreatedBy] BIGINT NULL,
    [UpdatedAt] DATETIME2(3) NULL,
    [UpdatedBy] BIGINT NULL,
    [RowVersion] ROWVERSION NOT NULL,
    CONSTRAINT [PK_Counterparty] PRIMARY KEY CLUSTERED ([CounterpartyId]),
    CONSTRAINT [UQ_Counterparty_Tenant] UNIQUE ([TenantId], [CounterpartyId]),
    CONSTRAINT [UQ_Counterparty_PublicId] UNIQUE ([PublicId]),
    CONSTRAINT [UQ_Counterparty_Code] UNIQUE ([TenantId], [Code]),
    CONSTRAINT [CK_Counterparty_1] CHECK (ErpCode IS NULL OR ErpCodeNormalized IS NOT NULL),
    CONSTRAINT [CK_Counterparty_2] CHECK (MergedIntoId IS NULL OR (MergedIntoId <> CounterpartyId AND IsActive = 0)),
    CONSTRAINT [CK_Counterparty_Kind] CHECK ([Kind] IS NULL OR [Kind] IN ('SUPPLIER', 'CUSTOMER', 'BOTH'))
);
GO
-- مكتبة بنود المستندات بإصدارات: نص قالب بمعاملات (FR-LCT-017..019، BR-LCT-012)؛ مراجع UCP في lc.LcDocumentClauseUcpRef
CREATE TABLE [lc].[LcDocumentClause] (
    [TenantId] INT NOT NULL,
    [LcDocumentClauseId] BIGINT IDENTITY(1,1) NOT NULL,
    [Code] VARCHAR(40) NOT NULL,
    [VersionNo] INT NOT NULL CONSTRAINT [DF_LcDocumentClause_VersionNo] DEFAULT 1,
    [NameAr] NVARCHAR(200) NOT NULL,
    [NameEn] NVARCHAR(200) NOT NULL,
    [Category] VARCHAR(20) NOT NULL,
    [Scope] VARCHAR(13) NOT NULL CONSTRAINT [DF_LcDocumentClause_Scope] DEFAULT 'ANY',
    [ApplicableModes] NVARCHAR(MAX) NULL,
    [TemplateTextEn] NVARCHAR(MAX) NOT NULL,
    [TemplateTextAr] NVARCHAR(MAX) NOT NULL,
    [ParamSchemaJson] NVARCHAR(MAX) NOT NULL,
    [DefaultOriginals] INT NULL,
    [DefaultCopies] INT NULL,
    [InstitutionId] BIGINT NULL,
    [LegalReviewStatus] VARCHAR(10) NOT NULL CONSTRAINT [DF_LcDocumentClause_LegalReviewStatus] DEFAULT 'UNREVIEWED',
    [ReviewedByText] NVARCHAR(200) NULL,
    [ReviewedOn] DATE NULL,
    [Status] VARCHAR(10) NOT NULL CONSTRAINT [DF_LcDocumentClause_Status] DEFAULT 'ACTIVE',
    [SeedKey] VARCHAR(80) NULL,
    [PublicId] UNIQUEIDENTIFIER NOT NULL CONSTRAINT [DF_LcDocumentClause_PublicId] DEFAULT NEWSEQUENTIALID(),
    [CreatedAt] DATETIME2(3) NOT NULL CONSTRAINT [DF_LcDocumentClause_CreatedAt] DEFAULT SYSUTCDATETIME(),
    [CreatedBy] BIGINT NULL,
    [UpdatedAt] DATETIME2(3) NULL,
    [UpdatedBy] BIGINT NULL,
    [RowVersion] ROWVERSION NOT NULL,
    CONSTRAINT [PK_LcDocumentClause] PRIMARY KEY CLUSTERED ([LcDocumentClauseId]),
    CONSTRAINT [UQ_LcDocumentClause_Tenant] UNIQUE ([TenantId], [LcDocumentClauseId]),
    CONSTRAINT [UQ_LcDocumentClause_PublicId] UNIQUE ([PublicId]),
    CONSTRAINT [UQ_LcDocumentClause_Code_VersionNo] UNIQUE ([TenantId], [Code], [VersionNo]),
    CONSTRAINT [CK_LcDocumentClause_1] CHECK (Code NOT LIKE '%[^A-Z0-9_]%'),
    CONSTRAINT [CK_LcDocumentClause_2] CHECK (VersionNo >= 1),
    CONSTRAINT [CK_LcDocumentClause_3] CHECK (DefaultOriginals IS NULL OR DefaultOriginals >= 0),
    CONSTRAINT [CK_LcDocumentClause_4] CHECK (DefaultCopies IS NULL OR DefaultCopies >= 0),
    CONSTRAINT [CK_LcDocumentClause_5] CHECK (LegalReviewStatus <> 'REVIEWED' OR (ReviewedByText IS NOT NULL AND ReviewedOn IS NOT NULL)),
    CONSTRAINT [CK_LcDocumentClause_Category] CHECK ([Category] IS NULL OR [Category] IN ('COMMERCIAL_INVOICE', 'DELIVERY_NOTE', 'TRANSPORT_SEA', 'TRANSPORT_AIR', 'TRANSPORT_ROAD', 'TRANSPORT_MULTIMODAL', 'INSURANCE', 'ORIGIN', 'PACKING', 'WEIGHT', 'BENEFICIARY_CERT', 'FCR', 'OTHER')),
    CONSTRAINT [CK_LcDocumentClause_Scope] CHECK ([Scope] IS NULL OR [Scope] IN ('ANY', 'DOMESTIC', 'INTERNATIONAL')),
    CONSTRAINT [CK_LcDocumentClause_LegalReviewStatus] CHECK ([LegalReviewStatus] IS NULL OR [LegalReviewStatus] IN ('UNREVIEWED', 'REVIEWED')),
    CONSTRAINT [CK_LcDocumentClause_Status] CHECK ([Status] IS NULL OR [Status] IN ('ACTIVE', 'RETIRED')),
    CONSTRAINT [CK_LcDocumentClause_ApplicableModes_json] CHECK ([ApplicableModes] IS NULL OR ISJSON([ApplicableModes]) = 1),
    CONSTRAINT [CK_LcDocumentClause_ParamSchemaJson_json] CHECK ([ParamSchemaJson] IS NULL OR ISJSON([ParamSchemaJson]) = 1)
);
GO
-- مرجع UCP لبند مستند: مادة + فقرة (UcpRefs في المواصفة) -- وسيط جديد
CREATE TABLE [lc].[LcDocumentClauseUcpRef] (
    [TenantId] INT NOT NULL,
    [LcDocumentClauseUcpRefId] BIGINT IDENTITY(1,1) NOT NULL,
    [LcDocumentClauseId] BIGINT NOT NULL,
    [UcpArticleId] INT NOT NULL,
    [Paragraph] NVARCHAR(20) NULL,
    [CreatedAt] DATETIME2(3) NOT NULL CONSTRAINT [DF_LcDocumentClauseUcpRef_CreatedAt] DEFAULT SYSUTCDATETIME(),
    [CreatedBy] BIGINT NULL,
    [UpdatedAt] DATETIME2(3) NULL,
    [UpdatedBy] BIGINT NULL,
    [RowVersion] ROWVERSION NOT NULL,
    CONSTRAINT [PK_LcDocumentClauseUcpRef] PRIMARY KEY CLUSTERED ([LcDocumentClauseUcpRefId]),
    CONSTRAINT [UQ_LcDocumentClauseUcpRef_Tenant] UNIQUE ([TenantId], [LcDocumentClauseUcpRefId]),
    CONSTRAINT [UQ_LcDocumentClauseUcpRef_LcDocumentClauseId_UcpArticleId_Paragraph] UNIQUE ([TenantId], [LcDocumentClauseId], [UcpArticleId], [Paragraph])
);
GO
-- إصدار شروط اعتماد: صف لكل نسخة بأعمدة قاموس §6.2؛ مشترك بين البروفورما والطلب والاعتماد والتعديل (FR-LCT-001..035)
CREATE TABLE [lc].[LcTerms] (
    [TenantId] INT NOT NULL,
    [LcTermsId] BIGINT IDENTITY(1,1) NOT NULL,
    [OwnerType] VARCHAR(16) NOT NULL,
    [OwnerId] BIGINT NULL,
    [Purpose] VARCHAR(11) NOT NULL,
    [VersionNo] INT NOT NULL CONSTRAINT [DF_LcTerms_VersionNo] DEFAULT 1,
    [Status] VARCHAR(10) NOT NULL CONSTRAINT [DF_LcTerms_Status] DEFAULT 'DRAFT',
    [FieldSetVersion] INT NOT NULL CONSTRAINT [DF_LcTerms_FieldSetVersion] DEFAULT 1,
    [LcClass] VARCHAR(10) NOT NULL,
    [Scope] VARCHAR(13) NOT NULL,
    [ScopeOverrideReason] NVARCHAR(500) NULL,
    [UcpVersion] VARCHAR(10) NOT NULL CONSTRAINT [DF_LcTerms_UcpVersion] DEFAULT 'UCP600',
    [LcType] VARCHAR(16) NULL,
    [DeferralDays] INT NULL,
    [MaturityBasis] VARCHAR(22) NULL,
    [MixedPaymentText] NVARCHAR(500) NULL,
    [AvailableWith] VARCHAR(14) NULL CONSTRAINT [DF_LcTerms_AvailableWith] DEFAULT 'ADVISING_BANK',
    [DraftRequired] BIT NULL,
    [DraftDrawee] VARCHAR(15) NULL,
    [Confirmation] VARCHAR(10) NULL,
    [ConfirmingBankName] NVARCHAR(200) NULL,
    [ConfirmingBankBic] VARCHAR(11) NULL,
    [ApplicantCompanyId] BIGINT NULL,
    [ApplicantCounterpartyId] BIGINT NULL,
    [BeneficiaryCompanyId] BIGINT NULL,
    [BeneficiaryCounterpartyId] BIGINT NULL,
    [BeneficiaryAccountIbanEnc] VARBINARY(512) NULL,
    [BeneficiaryAccountIbanMask] NVARCHAR(40) NULL,
    [BeneficiaryAccountIbanHash] VARBINARY(32) NULL,
    [EncKeyPurpose] VARCHAR(10) NOT NULL CONSTRAINT [DF_LcTerms_EncKeyPurpose] DEFAULT 'DATA',
    [EncKeyId] BIGINT NULL,
    [HashKeyPurpose] VARCHAR(11) NOT NULL CONSTRAINT [DF_LcTerms_HashKeyPurpose] DEFAULT 'BLIND_INDEX',
    [HashKeyId] BIGINT NULL,
    [AdvisingBankName] NVARCHAR(200) NULL,
    [AdvisingBankAddress] NVARCHAR(300) NULL,
    [AdvisingBankBic] VARCHAR(11) NULL,
    [CurrencyId] INT NULL,
    [Amount] DECIMAL(19,4) NULL,
    [AmountInWordsAr] NVARCHAR(1000) NULL,
    [AmountInWordsEn] NVARCHAR(1000) NULL,
    [ToleranceMode] VARCHAR(10) NOT NULL CONSTRAINT [DF_LcTerms_ToleranceMode] DEFAULT 'NONE',
    [TolerancePlusPct] DECIMAL(9,6) NOT NULL CONSTRAINT [DF_LcTerms_TolerancePlusPct] DEFAULT 0,
    [ToleranceMinusPct] DECIMAL(9,6) NOT NULL CONSTRAINT [DF_LcTerms_ToleranceMinusPct] DEFAULT 0,
    [ExpiryRule] VARCHAR(16) NULL,
    [ExpiryDate] DATE NULL,
    [ExpiryDateHijri] NVARCHAR(20) NULL,
    [ExpiryDaysAfterIssue] INT NULL,
    [ExpiryPlace] NVARCHAR(200) NULL,
    [EarliestShipmentDate] DATE NULL,
    [LatestShipmentRule] VARCHAR(16) NULL,
    [LatestShipmentDate] DATE NULL,
    [LatestShipmentDateHijri] NVARCHAR(20) NULL,
    [LatestShipmentDaysAfterIssue] INT NULL,
    [PresentationDays] INT NULL CONSTRAINT [DF_LcTerms_PresentationDays] DEFAULT 21,
    [PresentationBasis] VARCHAR(18) NULL,
    [ExpectedIssueDate] DATE NULL,
    [PartialShipments] VARCHAR(11) NULL CONSTRAINT [DF_LcTerms_PartialShipments] DEFAULT 'ALLOWED',
    [InstallmentShipments] NVARCHAR(300) NULL,
    [Transhipment] VARCHAR(14) NULL,
    [TransportMode] VARCHAR(17) NULL,
    [PlaceOfDispatch] NVARCHAR(150) NULL,
    [PlaceOfFinalDestination] NVARCHAR(150) NULL,
    [PortOfLoading] NVARCHAR(150) NULL,
    [PortOfDischarge] NVARCHAR(150) NULL,
    [AirportOfDeparture] NVARCHAR(150) NULL,
    [AirportOfDestination] NVARCHAR(150) NULL,
    [IncotermId] INT NULL,
    [IncotermPlace] NVARCHAR(150) NULL,
    [GoodsCategory] VARCHAR(80) NULL,
    [GoodsDescription] NVARCHAR(2000) NULL,
    [SupplierProformaNo] NVARCHAR(60) NULL,
    [SupplierProformaDate] DATE NULL,
    [InsuranceResponsibility] VARCHAR(21) NULL,
    [InsuranceMinPct] DECIMAL(9,6) NULL,
    [InsurancePctStated] BIT NOT NULL CONSTRAINT [DF_LcTerms_InsurancePctStated] DEFAULT 0,
    [InsuranceClauses] NVARCHAR(300) NULL,
    [BankMayArrangeInsurance] BIT NULL,
    [AdditionalConditions] NVARCHAR(2000) NULL,
    [IsTransferable] BIT NULL,
    [AssignmentOfProceedsText] NVARCHAR(500) NULL,
    [LcTextLanguage] VARCHAR(10) NOT NULL CONSTRAINT [DF_LcTerms_LcTextLanguage] DEFAULT 'EN',
    [MarginPct] DECIMAL(9,6) NULL,
    [DebitAuthorization] VARCHAR(18) NULL,
    [MarginHeldCurrency] VARCHAR(10) NULL,
    [FacilityAccountId] BIGINT NULL,
    [MarginSettlementAccountId] BIGINT NULL,
    [ChargesAccountId] BIGINT NULL,
    [PostDeferralFinancingDays] INT NULL,
    [BankSpecificClauses] NVARCHAR(MAX) NULL,
    [PrevLcNumber] NVARCHAR(60) NULL,
    [PrevLcAmount] DECIMAL(19,4) NULL,
    [PrevLcCurrencyId] INT NULL,
    [PrevLcUtilizedAmount] DECIMAL(19,4) NULL,
    [PrevLcOpenedBy] NVARCHAR(200) NULL,
    [SnapshotHash] VARBINARY(32) NULL,
    [TreasuryHash] VARBINARY(32) NULL,
    [LockedAt] DATETIME2(3) NULL,
    [LockedBy] BIGINT NULL,
    [SupersedesTermsId] BIGINT NULL,
    [CopiedFromTermsId] BIGINT NULL,
    [ChangeReason] NVARCHAR(MAX) NULL,
    [PublicId] UNIQUEIDENTIFIER NOT NULL CONSTRAINT [DF_LcTerms_PublicId] DEFAULT NEWSEQUENTIALID(),
    [CreatedAt] DATETIME2(3) NOT NULL CONSTRAINT [DF_LcTerms_CreatedAt] DEFAULT SYSUTCDATETIME(),
    [CreatedBy] BIGINT NULL,
    [UpdatedAt] DATETIME2(3) NULL,
    [UpdatedBy] BIGINT NULL,
    [RowVersion] ROWVERSION NOT NULL,
    CONSTRAINT [PK_LcTerms] PRIMARY KEY CLUSTERED ([LcTermsId]),
    CONSTRAINT [UQ_LcTerms_Tenant] UNIQUE ([TenantId], [LcTermsId]),
    CONSTRAINT [UQ_LcTerms_PublicId] UNIQUE ([PublicId]),
    CONSTRAINT [CK_LcTerms_1] CHECK (VersionNo >= 1),
    CONSTRAINT [CK_LcTerms_2] CHECK (VersionNo = 1 OR SupersedesTermsId IS NOT NULL),
    CONSTRAINT [CK_LcTerms_3] CHECK (SupersedesTermsId IS NULL OR SupersedesTermsId <> LcTermsId),
    CONSTRAINT [CK_LcTerms_4] CHECK (CopiedFromTermsId IS NULL OR CopiedFromTermsId <> LcTermsId),
    CONSTRAINT [CK_LcTerms_5] CHECK ((Purpose = 'PROFORMA' AND OwnerType IN ('REQUEST','PROFORMA')) OR (Purpose = 'APPLICATION' AND OwnerType = 'REQUEST') OR (Purpose IN ('ISSUED','RECEIVED') AND OwnerType = 'LETTER_OF_CREDIT') OR (Purpose = 'AMENDMENT' AND OwnerType IN ('REQUEST','AMENDMENT'))),
    CONSTRAINT [CK_LcTerms_6] CHECK ((Purpose NOT IN ('APPLICATION','ISSUED') OR LcClass = 'PURCHASE') AND (Purpose NOT IN ('PROFORMA','RECEIVED') OR LcClass = 'SALES')),
    CONSTRAINT [CK_LcTerms_7] CHECK (OwnerType <> 'REQUEST' OR OwnerId IS NOT NULL),
    CONSTRAINT [CK_LcTerms_8] CHECK (Status = 'DRAFT' OR (SnapshotHash IS NOT NULL AND LockedAt IS NOT NULL)),
    CONSTRAINT [CK_LcTerms_9] CHECK (TreasuryHash IS NULL OR SnapshotHash IS NOT NULL),
    CONSTRAINT [CK_LcTerms_10] CHECK (Status = 'DRAFT' OR (LcType IS NOT NULL AND CurrencyId IS NOT NULL AND Amount IS NOT NULL AND ExpiryRule IS NOT NULL AND AmountInWordsAr IS NOT NULL AND AmountInWordsEn IS NOT NULL)),
    CONSTRAINT [CK_LcTerms_11] CHECK (Amount IS NULL OR Amount > 0),
    CONSTRAINT [CK_LcTerms_12] CHECK (TolerancePlusPct BETWEEN 0 AND 100 AND ToleranceMinusPct BETWEEN 0 AND 100),
    CONSTRAINT [CK_LcTerms_13] CHECK (Status = 'DRAFT' OR ToleranceMode <> 'NONE' OR (TolerancePlusPct = 0 AND ToleranceMinusPct = 0)),
    CONSTRAINT [CK_LcTerms_14] CHECK (Status = 'DRAFT' OR ToleranceMode <> 'ABOUT' OR (TolerancePlusPct = 10 AND ToleranceMinusPct = 10)),
    CONSTRAINT [CK_LcTerms_15] CHECK (DeferralDays IS NULL OR DeferralDays BETWEEN 1 AND 720),
    CONSTRAINT [CK_LcTerms_16] CHECK (Status = 'DRAFT' OR LcType <> 'SIGHT' OR (DeferralDays IS NULL AND MaturityBasis IS NULL)),
    CONSTRAINT [CK_LcTerms_17] CHECK (Status = 'DRAFT' OR LcType NOT IN ('DEFERRED_PAYMENT','ACCEPTANCE') OR (DeferralDays IS NOT NULL AND MaturityBasis IS NOT NULL)),
    CONSTRAINT [CK_LcTerms_18] CHECK (Status = 'DRAFT' OR LcType <> 'MIXED' OR MixedPaymentText IS NOT NULL),
    CONSTRAINT [CK_LcTerms_19] CHECK (Status = 'DRAFT' OR DraftDrawee IS NULL OR (DraftRequired IS NOT NULL AND DraftRequired = 1)),
    CONSTRAINT [CK_LcTerms_20] CHECK (Status = 'DRAFT' OR LcType NOT IN ('ACCEPTANCE','NEGOTIATION') OR (DraftRequired IS NOT NULL AND DraftRequired = 1)),
    CONSTRAINT [CK_LcTerms_21] CHECK (Status = 'DRAFT' OR ConfirmingBankBic IS NULL OR ((ConfirmingBankBic LIKE '________' OR ConfirmingBankBic LIKE '___________') AND ConfirmingBankBic NOT LIKE '%[^A-Z0-9]%')),
    CONSTRAINT [CK_LcTerms_22] CHECK (Status = 'DRAFT' OR AdvisingBankBic IS NULL OR ((AdvisingBankBic LIKE '________' OR AdvisingBankBic LIKE '___________') AND AdvisingBankBic NOT LIKE '%[^A-Z0-9]%')),
    CONSTRAINT [CK_LcTerms_23] CHECK ((BeneficiaryAccountIbanEnc IS NULL AND BeneficiaryAccountIbanMask IS NULL AND BeneficiaryAccountIbanHash IS NULL) OR (BeneficiaryAccountIbanEnc IS NOT NULL AND BeneficiaryAccountIbanMask IS NOT NULL AND BeneficiaryAccountIbanHash IS NOT NULL)),
    CONSTRAINT [CK_LcTerms_24] CHECK (BeneficiaryAccountIbanEnc IS NULL OR (EncKeyId IS NOT NULL AND HashKeyId IS NOT NULL AND DATALENGTH(BeneficiaryAccountIbanEnc) >= 29)),
    CONSTRAINT [CK_LcTerms_25] CHECK (LcClass = 'SALES' OR (ApplicantCounterpartyId IS NULL AND BeneficiaryCompanyId IS NULL)),
    CONSTRAINT [CK_LcTerms_26] CHECK (LcClass = 'PURCHASE' OR (ApplicantCompanyId IS NULL AND BeneficiaryCounterpartyId IS NULL)),
    CONSTRAINT [CK_LcTerms_27] CHECK (Status = 'DRAFT' OR (LcClass = 'PURCHASE' AND ApplicantCompanyId IS NOT NULL AND BeneficiaryCounterpartyId IS NOT NULL) OR (LcClass = 'SALES' AND ApplicantCounterpartyId IS NOT NULL AND BeneficiaryCompanyId IS NOT NULL)),
    CONSTRAINT [CK_LcTerms_28] CHECK (ExpiryDaysAfterIssue IS NULL OR ExpiryDaysAfterIssue > 0),
    CONSTRAINT [CK_LcTerms_29] CHECK (LatestShipmentDaysAfterIssue IS NULL OR LatestShipmentDaysAfterIssue > 0),
    CONSTRAINT [CK_LcTerms_30] CHECK (Status = 'DRAFT' OR ExpiryRule IS NULL OR (ExpiryRule = 'ABSOLUTE' AND ExpiryDate IS NOT NULL AND ExpiryDaysAfterIssue IS NULL) OR (ExpiryRule = 'DAYS_AFTER_ISSUE' AND ExpiryDaysAfterIssue IS NOT NULL)),
    CONSTRAINT [CK_LcTerms_31] CHECK (Status = 'DRAFT' OR (LatestShipmentRule IS NULL AND LatestShipmentDate IS NULL AND LatestShipmentDaysAfterIssue IS NULL) OR (LatestShipmentRule = 'ABSOLUTE' AND LatestShipmentDate IS NOT NULL AND LatestShipmentDaysAfterIssue IS NULL) OR (LatestShipmentRule = 'DAYS_AFTER_ISSUE' AND LatestShipmentDaysAfterIssue IS NOT NULL)),
    CONSTRAINT [CK_LcTerms_32] CHECK (Status = 'DRAFT' OR Purpose IN ('ISSUED','RECEIVED') OR EarliestShipmentDate IS NULL OR LatestShipmentDate IS NULL OR EarliestShipmentDate <= LatestShipmentDate),
    CONSTRAINT [CK_LcTerms_33] CHECK (Status = 'DRAFT' OR Purpose IN ('ISSUED','RECEIVED') OR ExpiryDate IS NULL OR LatestShipmentDate IS NULL OR ExpiryDate >= LatestShipmentDate),
    CONSTRAINT [CK_LcTerms_34] CHECK (PresentationDays IS NULL OR PresentationDays BETWEEN 1 AND 90),
    CONSTRAINT [CK_LcTerms_35] CHECK (Status = 'DRAFT' OR Purpose IN ('ISSUED','RECEIVED') OR IncotermId IS NULL OR IncotermPlace IS NOT NULL),
    CONSTRAINT [CK_LcTerms_36] CHECK (InsurancePctStated = 0 OR InsuranceMinPct IS NOT NULL),
    CONSTRAINT [CK_LcTerms_37] CHECK (InsuranceMinPct IS NULL OR InsuranceMinPct > 0),
    CONSTRAINT [CK_LcTerms_38] CHECK (MarginPct IS NULL OR MarginPct BETWEEN 0 AND 100),
    CONSTRAINT [CK_LcTerms_39] CHECK (Status = 'DRAFT' OR DebitAuthorization IS NULL OR DebitAuthorization <> 'FULL_LC_VALUE' OR (MarginPct IS NOT NULL AND MarginPct = 100)),
    CONSTRAINT [CK_LcTerms_40] CHECK (PostDeferralFinancingDays IS NULL OR PostDeferralFinancingDays >= 0),
    CONSTRAINT [CK_LcTerms_41] CHECK (PrevLcAmount IS NULL OR PrevLcAmount >= 0),
    CONSTRAINT [CK_LcTerms_42] CHECK (PrevLcUtilizedAmount IS NULL OR PrevLcUtilizedAmount >= 0),
    CONSTRAINT [CK_LcTerms_43] CHECK (PrevLcAmount IS NULL OR PrevLcUtilizedAmount IS NULL OR PrevLcUtilizedAmount <= PrevLcAmount),
    CONSTRAINT [CK_LcTerms_44] CHECK ((PrevLcAmount IS NULL AND PrevLcUtilizedAmount IS NULL) OR PrevLcCurrencyId IS NOT NULL),
    CONSTRAINT [CK_LcTerms_OwnerType] CHECK ([OwnerType] IS NULL OR [OwnerType] IN ('REQUEST', 'PROFORMA', 'LETTER_OF_CREDIT', 'AMENDMENT')),
    CONSTRAINT [CK_LcTerms_Purpose] CHECK ([Purpose] IS NULL OR [Purpose] IN ('PROFORMA', 'APPLICATION', 'ISSUED', 'RECEIVED', 'AMENDMENT')),
    CONSTRAINT [CK_LcTerms_Status] CHECK ([Status] IS NULL OR [Status] IN ('DRAFT', 'LOCKED', 'SUPERSEDED')),
    CONSTRAINT [CK_LcTerms_LcClass] CHECK ([LcClass] IS NULL OR [LcClass] IN ('PURCHASE', 'SALES')),
    CONSTRAINT [CK_LcTerms_Scope] CHECK ([Scope] IS NULL OR [Scope] IN ('DOMESTIC', 'INTERNATIONAL')),
    CONSTRAINT [CK_LcTerms_UcpVersion] CHECK ([UcpVersion] IS NULL OR [UcpVersion] IN ('UCP600')),
    CONSTRAINT [CK_LcTerms_LcType] CHECK ([LcType] IS NULL OR [LcType] IN ('SIGHT', 'DEFERRED_PAYMENT', 'ACCEPTANCE', 'NEGOTIATION', 'MIXED')),
    CONSTRAINT [CK_LcTerms_MaturityBasis] CHECK ([MaturityBasis] IS NULL OR [MaturityBasis] IN ('SHIPMENT_DATE', 'DELIVERY_NOTE_DATE', 'INVOICE_DATE', 'DOCUMENTS_RECEIPT_DATE', 'ACCEPTANCE_DATE')),
    CONSTRAINT [CK_LcTerms_AvailableWith] CHECK ([AvailableWith] IS NULL OR [AvailableWith] IN ('ISSUING_BANK', 'ADVISING_BANK', 'NOMINATED_BANK', 'ANY_BANK')),
    CONSTRAINT [CK_LcTerms_DraftDrawee] CHECK ([DraftDrawee] IS NULL OR [DraftDrawee] IN ('ISSUING_BANK', 'ADVISING_BANK', 'CONFIRMING_BANK')),
    CONSTRAINT [CK_LcTerms_Confirmation] CHECK ([Confirmation] IS NULL OR [Confirmation] IN ('CONFIRMED', 'MAY_ADD', 'WITHOUT')),
    CONSTRAINT [CK_LcTerms_EncKeyPurpose] CHECK ([EncKeyPurpose] IS NULL OR [EncKeyPurpose] IN ('DATA')),
    CONSTRAINT [CK_LcTerms_HashKeyPurpose] CHECK ([HashKeyPurpose] IS NULL OR [HashKeyPurpose] IN ('BLIND_INDEX')),
    CONSTRAINT [CK_LcTerms_ToleranceMode] CHECK ([ToleranceMode] IS NULL OR [ToleranceMode] IN ('NONE', 'ABOUT', 'PLUS_MINUS')),
    CONSTRAINT [CK_LcTerms_ExpiryRule] CHECK ([ExpiryRule] IS NULL OR [ExpiryRule] IN ('ABSOLUTE', 'DAYS_AFTER_ISSUE')),
    CONSTRAINT [CK_LcTerms_LatestShipmentRule] CHECK ([LatestShipmentRule] IS NULL OR [LatestShipmentRule] IN ('ABSOLUTE', 'DAYS_AFTER_ISSUE')),
    CONSTRAINT [CK_LcTerms_PresentationBasis] CHECK ([PresentationBasis] IS NULL OR [PresentationBasis] IN ('SHIPMENT_DATE', 'DELIVERY_NOTE_DATE', 'INVOICE_DATE')),
    CONSTRAINT [CK_LcTerms_PartialShipments] CHECK ([PartialShipments] IS NULL OR [PartialShipments] IN ('ALLOWED', 'NOT_ALLOWED')),
    CONSTRAINT [CK_LcTerms_Transhipment] CHECK ([Transhipment] IS NULL OR [Transhipment] IN ('ALLOWED', 'NOT_ALLOWED', 'NOT_APPLICABLE')),
    CONSTRAINT [CK_LcTerms_TransportMode] CHECK ([TransportMode] IS NULL OR [TransportMode] IN ('SEA', 'AIR', 'ROAD', 'RAIL', 'COURIER', 'MULTIMODAL', 'DOMESTIC_DELIVERY')),
    CONSTRAINT [CK_LcTerms_InsuranceResponsibility] CHECK ([InsuranceResponsibility] IS NULL OR [InsuranceResponsibility] IN ('BENEFICIARY', 'APPLICANT', 'NOT_REQUIRED_BY_TERMS')),
    CONSTRAINT [CK_LcTerms_LcTextLanguage] CHECK ([LcTextLanguage] IS NULL OR [LcTextLanguage] IN ('EN', 'AR', 'BOTH')),
    CONSTRAINT [CK_LcTerms_DebitAuthorization] CHECK ([DebitAuthorization] IS NULL OR [DebitAuthorization] IN ('CHARGES_AND_MARGIN', 'FULL_LC_VALUE')),
    CONSTRAINT [CK_LcTerms_MarginHeldCurrency] CHECK ([MarginHeldCurrency] IS NULL OR [MarginHeldCurrency] IN ('LOCAL', 'FOREIGN'))
);
GO
-- بند مستند مختار في الشروط ومعاملاته؛ النص المصيَّر يُجمَّد عند القفل (FR-LCT-018، BR-LCT-012) -- جديد
CREATE TABLE [lc].[LcTermsDocument] (
    [TenantId] INT NOT NULL,
    [LcTermsDocumentId] BIGINT IDENTITY(1,1) NOT NULL,
    [LcTermsId] BIGINT NOT NULL,
    [SeqNo] INT NOT NULL,
    [ClauseId] BIGINT NOT NULL,
    [ClauseVersion] INT NOT NULL,
    [Originals] INT NULL,
    [Copies] INT NULL,
    [ParamsJson] NVARCHAR(MAX) NULL,
    [RenderedTextEn] NVARCHAR(MAX) NULL,
    [RenderedTextAr] NVARCHAR(MAX) NULL,
    [IsFreeText] BIT NOT NULL CONSTRAINT [DF_LcTermsDocument_IsFreeText] DEFAULT 0,
    [FreeText] NVARCHAR(MAX) NULL,
    [CreatedAt] DATETIME2(3) NOT NULL CONSTRAINT [DF_LcTermsDocument_CreatedAt] DEFAULT SYSUTCDATETIME(),
    [CreatedBy] BIGINT NULL,
    [UpdatedAt] DATETIME2(3) NULL,
    [UpdatedBy] BIGINT NULL,
    [RowVersion] ROWVERSION NOT NULL,
    CONSTRAINT [PK_LcTermsDocument] PRIMARY KEY CLUSTERED ([LcTermsDocumentId]),
    CONSTRAINT [UQ_LcTermsDocument_Tenant] UNIQUE ([TenantId], [LcTermsDocumentId]),
    CONSTRAINT [UQ_LcTermsDocument_LcTermsId_SeqNo] UNIQUE ([TenantId], [LcTermsId], [SeqNo]),
    CONSTRAINT [CK_LcTermsDocument_1] CHECK (SeqNo >= 1),
    CONSTRAINT [CK_LcTermsDocument_2] CHECK (ClauseVersion >= 1),
    CONSTRAINT [CK_LcTermsDocument_3] CHECK (Originals IS NULL OR Originals >= 0),
    CONSTRAINT [CK_LcTermsDocument_4] CHECK (Copies IS NULL OR Copies >= 0),
    CONSTRAINT [CK_LcTermsDocument_5] CHECK ((IsFreeText = 1 AND FreeText IS NOT NULL) OR (IsFreeText = 0 AND FreeText IS NULL)),
    CONSTRAINT [CK_LcTermsDocument_ParamsJson_json] CHECK ([ParamsJson] IS NULL OR ISJSON([ParamsJson]) = 1)
);
GO
-- رسوم الشروط: صف لكل فئة (6 صفوف كاملة يتحقق منها التطبيق V-LCT-12) (FR-LCT-020، BR-LCT-014)
CREATE TABLE [lc].[LcChargesMatrix] (
    [TenantId] INT NOT NULL,
    [LcChargesMatrixId] BIGINT IDENTITY(1,1) NOT NULL,
    [LcTermsId] BIGINT NOT NULL,
    [ChargeCategory] VARCHAR(22) NOT NULL,
    [Payer] VARCHAR(11) NOT NULL,
    [ApplicantSharePct] DECIMAL(9,6) NULL,
    [PresetCode] VARCHAR(30) NULL,
    [Note] NVARCHAR(500) NULL,
    [CreatedAt] DATETIME2(3) NOT NULL CONSTRAINT [DF_LcChargesMatrix_CreatedAt] DEFAULT SYSUTCDATETIME(),
    [CreatedBy] BIGINT NULL,
    [UpdatedAt] DATETIME2(3) NULL,
    [UpdatedBy] BIGINT NULL,
    [RowVersion] ROWVERSION NOT NULL,
    CONSTRAINT [PK_LcChargesMatrix] PRIMARY KEY CLUSTERED ([LcChargesMatrixId]),
    CONSTRAINT [UQ_LcChargesMatrix_Tenant] UNIQUE ([TenantId], [LcChargesMatrixId]),
    CONSTRAINT [UQ_LcChargesMatrix_LcTermsId_ChargeCategory] UNIQUE ([TenantId], [LcTermsId], [ChargeCategory]),
    CONSTRAINT [CK_LcChargesMatrix_1] CHECK (Payer <> 'SHARED' OR (ApplicantSharePct IS NOT NULL AND ApplicantSharePct > 0 AND ApplicantSharePct < 100)),
    CONSTRAINT [CK_LcChargesMatrix_2] CHECK (Payer = 'SHARED' OR ApplicantSharePct IS NULL),
    CONSTRAINT [CK_LcChargesMatrix_ChargeCategory] CHECK ([ChargeCategory] IS NULL OR [ChargeCategory] IN ('ISSUING_BANK_LOCAL', 'ADVISING', 'CONFIRMATION', 'NEGOTIATION_SETTLEMENT', 'AMENDMENT', 'OTHER_OUTSIDE_ISSUING')),
    CONSTRAINT [CK_LcChargesMatrix_Payer] CHECK ([Payer] IS NULL OR [Payer] IN ('APPLICANT', 'BENEFICIARY', 'SHARED'))
);
GO
-- قالب نموذج بنك/منتج/نوع نموذج بإصدار وفترة نفاذ وملحق عقدي (FR-LCT-026، BR-LCT-017، 02 F-14)
CREATE TABLE [lc].[LcFormTemplate] (
    [TenantId] INT NOT NULL,
    [LcFormTemplateId] BIGINT IDENTITY(1,1) NOT NULL,
    [Code] VARCHAR(40) NOT NULL,
    [VersionNo] INT NOT NULL CONSTRAINT [DF_LcFormTemplate_VersionNo] DEFAULT 1,
    [FormKind] VARCHAR(16) NOT NULL,
    [InstitutionId] BIGINT NULL,
    [ProductId] INT NULL,
    [CompanyId] BIGINT NULL,
    [Scope] VARCHAR(13) NOT NULL CONSTRAINT [DF_LcFormTemplate_Scope] DEFAULT 'ANY',
    [Channel] VARCHAR(11) NOT NULL CONSTRAINT [DF_LcFormTemplate_Channel] DEFAULT 'ANY',
    [LayoutKind] VARCHAR(17) NOT NULL,
    [Language] VARCHAR(10) NULL,
    [EffectiveFrom] DATE NOT NULL,
    [EffectiveTo] DATE NULL,
    [SourceDocumentId] BIGINT NULL,
    [AnnexDocumentId] BIGINT NULL,
    [AnnexVersion] NVARCHAR(20) NULL,
    [LetterheadDocumentId] BIGINT NULL,
    [FooterTextAr] NVARCHAR(500) NULL,
    [FooterTextEn] NVARCHAR(500) NULL,
    [LegalReviewStatus] VARCHAR(10) NOT NULL CONSTRAINT [DF_LcFormTemplate_LegalReviewStatus] DEFAULT 'UNREVIEWED',
    [Status] VARCHAR(10) NOT NULL CONSTRAINT [DF_LcFormTemplate_Status] DEFAULT 'DRAFT',
    [PublicId] UNIQUEIDENTIFIER NOT NULL CONSTRAINT [DF_LcFormTemplate_PublicId] DEFAULT NEWSEQUENTIALID(),
    [CreatedAt] DATETIME2(3) NOT NULL CONSTRAINT [DF_LcFormTemplate_CreatedAt] DEFAULT SYSUTCDATETIME(),
    [CreatedBy] BIGINT NULL,
    [UpdatedAt] DATETIME2(3) NULL,
    [UpdatedBy] BIGINT NULL,
    [RowVersion] ROWVERSION NOT NULL,
    CONSTRAINT [PK_LcFormTemplate] PRIMARY KEY CLUSTERED ([LcFormTemplateId]),
    CONSTRAINT [UQ_LcFormTemplate_Tenant] UNIQUE ([TenantId], [LcFormTemplateId]),
    CONSTRAINT [UQ_LcFormTemplate_PublicId] UNIQUE ([PublicId]),
    CONSTRAINT [UQ_LcFormTemplate_Code_VersionNo] UNIQUE ([TenantId], [Code], [VersionNo]),
    CONSTRAINT [CK_LcFormTemplate_1] CHECK (VersionNo >= 1),
    CONSTRAINT [CK_LcFormTemplate_2] CHECK (EffectiveTo IS NULL OR EffectiveTo >= EffectiveFrom),
    CONSTRAINT [CK_LcFormTemplate_3] CHECK (LayoutKind <> 'PDF_ACROFORM_FILL' OR SourceDocumentId IS NOT NULL),
    CONSTRAINT [CK_LcFormTemplate_4] CHECK (AnnexDocumentId IS NULL OR AnnexVersion IS NOT NULL),
    CONSTRAINT [CK_LcFormTemplate_FormKind] CHECK ([FormKind] IS NULL OR [FormKind] IN ('LC_APPLICATION', 'LC_AMENDMENT', 'PROFORMA', 'COLLECTION_COVER')),
    CONSTRAINT [CK_LcFormTemplate_Scope] CHECK ([Scope] IS NULL OR [Scope] IN ('ANY', 'DOMESTIC', 'INTERNATIONAL')),
    CONSTRAINT [CK_LcFormTemplate_Channel] CHECK ([Channel] IS NULL OR [Channel] IN ('ANY', 'MANUAL_FORM', 'BANK_PORTAL')),
    CONSTRAINT [CK_LcFormTemplate_LayoutKind] CHECK ([LayoutKind] IS NULL OR [LayoutKind] IN ('SYSTEM_PRINT', 'PDF_ACROFORM_FILL')),
    CONSTRAINT [CK_LcFormTemplate_Language] CHECK ([Language] IS NULL OR [Language] IN ('ar', 'en', 'both')),
    CONSTRAINT [CK_LcFormTemplate_LegalReviewStatus] CHECK ([LegalReviewStatus] IS NULL OR [LegalReviewStatus] IN ('UNREVIEWED', 'REVIEWED')),
    CONSTRAINT [CK_LcFormTemplate_Status] CHECK ([Status] IS NULL OR [Status] IN ('DRAFT', 'ACTIVE', 'RETIRED'))
);
GO
-- تعيين حقل نظام إلى حقل PDF أو بند في ورقة البوابة (FR-LCT-027، BR-LCT-020) -- جديد
CREATE TABLE [lc].[LcFormFieldMap] (
    [TenantId] INT NOT NULL,
    [LcFormFieldMapId] BIGINT IDENTITY(1,1) NOT NULL,
    [TemplateId] BIGINT NOT NULL,
    [TargetName] NVARCHAR(120) NOT NULL,
    [SourceExpr] NVARCHAR(200) NOT NULL,
    [Transform] VARCHAR(15) NOT NULL CONSTRAINT [DF_LcFormFieldMap_Transform] DEFAULT 'NONE',
    [TransformArg] NVARCHAR(100) NULL,
    [IsRequired] BIT NOT NULL CONSTRAINT [DF_LcFormFieldMap_IsRequired] DEFAULT 0,
    [SeqNo] INT NULL,
    [CreatedAt] DATETIME2(3) NOT NULL CONSTRAINT [DF_LcFormFieldMap_CreatedAt] DEFAULT SYSUTCDATETIME(),
    [CreatedBy] BIGINT NULL,
    [UpdatedAt] DATETIME2(3) NULL,
    [UpdatedBy] BIGINT NULL,
    [RowVersion] ROWVERSION NOT NULL,
    CONSTRAINT [PK_LcFormFieldMap] PRIMARY KEY CLUSTERED ([LcFormFieldMapId]),
    CONSTRAINT [UQ_LcFormFieldMap_Tenant] UNIQUE ([TenantId], [LcFormFieldMapId]),
    CONSTRAINT [UQ_LcFormFieldMap_TemplateId_TargetName] UNIQUE ([TenantId], [TemplateId], [TargetName]),
    CONSTRAINT [CK_LcFormFieldMap_1] CHECK (SourceExpr LIKE 'terms.%' OR SourceExpr LIKE 'company.%' OR SourceExpr LIKE 'counterparty.%' OR SourceExpr LIKE 'facility.%' OR SourceExpr LIKE 'relationship.%' OR SourceExpr LIKE 'request.%' OR SourceExpr LIKE 'lc.%'),
    CONSTRAINT [CK_LcFormFieldMap_2] CHECK (SourceExpr NOT LIKE '%[^A-Za-z0-9._]%'),
    CONSTRAINT [CK_LcFormFieldMap_3] CHECK (Transform <> 'CHECKBOX_EQ' OR TransformArg IS NOT NULL),
    CONSTRAINT [CK_LcFormFieldMap_4] CHECK (SeqNo IS NULL OR SeqNo >= 1),
    CONSTRAINT [CK_LcFormFieldMap_Transform] CHECK ([Transform] IS NULL OR [Transform] IN ('NONE', 'UPPER', 'DATE_DMY', 'DATE_HIJRI', 'AMOUNT_WORDS_AR', 'AMOUNT_WORDS_EN', 'CHECKBOX_EQ', 'CONCAT_DOCS', 'CHARGES_SUMMARY'))
);
GO
-- سجل الاعتماد للجانبين: مشتريات (نحن الطالب) ومبيعات (نحن المستفيد) (FR-LCI-011..016، FR-LCE-009، BR-LCI-004/008/016، BR-LCE-007/009)
CREATE TABLE [lc].[LetterOfCredit] (
    [TenantId] INT NOT NULL,
    [LetterOfCreditId] BIGINT IDENTITY(1,1) NOT NULL,
    [LcClass] VARCHAR(10) NOT NULL,
    [Scope] VARCHAR(13) NOT NULL,
    [CompanyId] BIGINT NOT NULL,
    [LcNumber] NVARCHAR(60) NOT NULL,
    [LcNumberNormalized] NVARCHAR(60) NOT NULL,
    [InternalRef] NVARCHAR(40) NULL,
    [Status] VARCHAR(10) NOT NULL CONSTRAINT [DF_LetterOfCredit_Status] DEFAULT 'ACTIVE',
    [CounterpartyId] BIGINT NOT NULL,
    [InstitutionId] BIGINT NULL,
    [RelationshipId] BIGINT NULL,
    [OtherBankText] NVARCHAR(200) NULL,
    [OtherBankBic] VARCHAR(11) NULL,
    [IssuingBranch] NVARCHAR(150) NULL,
    [BankReference] NVARCHAR(60) NULL,
    [Channel] VARCHAR(18) NULL,
    [ProductId] INT NULL,
    [FacilityId] BIGINT NULL,
    [LimitId] BIGINT NULL,
    [LimitProductLineId] BIGINT NULL,
    [UtilizationId] BIGINT NULL,
    [RequestId] BIGINT NULL,
    [ProformaId] BIGINT NULL,
    [CurrentTermsId] BIGINT NOT NULL,
    [CurrencyId] INT NOT NULL,
    [Amount] DECIMAL(19,4) NOT NULL,
    [OriginalAmount] DECIMAL(19,4) NOT NULL,
    [TolerancePlusPct] DECIMAL(9,6) NOT NULL CONSTRAINT [DF_LetterOfCredit_TolerancePlusPct] DEFAULT 0,
    [ToleranceMinusPct] DECIMAL(9,6) NOT NULL CONSTRAINT [DF_LetterOfCredit_ToleranceMinusPct] DEFAULT 0,
    [ExposureAmount] DECIMAL(19,4) NULL,
    [MarginPct] DECIMAL(9,6) NULL,
    [MarginAmount] DECIMAL(19,4) NULL,
    [DrawnAmount] DECIMAL(19,4) NOT NULL CONSTRAINT [DF_LetterOfCredit_DrawnAmount] DEFAULT 0,
    [SettledAmount] DECIMAL(19,4) NOT NULL CONSTRAINT [DF_LetterOfCredit_SettledAmount] DEFAULT 0,
    [EarmarkedRemaining] DECIMAL(19,4) NOT NULL CONSTRAINT [DF_LetterOfCredit_EarmarkedRemaining] DEFAULT 0,
    [IssueDate] DATE NULL,
    [ReceivedDate] DATE NULL,
    [ExpiryDate] DATE NOT NULL,
    [LatestShipmentDate] DATE NULL,
    [AmendmentNo] INT NOT NULL CONSTRAINT [DF_LetterOfCredit_AmendmentNo] DEFAULT 0,
    [UndrawnReleasedOn] DATE NULL,
    [ClosedOn] DATE NULL,
    [ClosedReason] NVARCHAR(500) NULL,
    [LegacyEntry] BIT NOT NULL CONSTRAINT [DF_LetterOfCredit_LegacyEntry] DEFAULT 0,
    [AnnexVersion] NVARCHAR(20) NULL,
    [PublicId] UNIQUEIDENTIFIER NOT NULL CONSTRAINT [DF_LetterOfCredit_PublicId] DEFAULT NEWSEQUENTIALID(),
    [CreatedAt] DATETIME2(3) NOT NULL CONSTRAINT [DF_LetterOfCredit_CreatedAt] DEFAULT SYSUTCDATETIME(),
    [CreatedBy] BIGINT NULL,
    [UpdatedAt] DATETIME2(3) NULL,
    [UpdatedBy] BIGINT NULL,
    [RowVersion] ROWVERSION NOT NULL,
    CONSTRAINT [PK_LetterOfCredit] PRIMARY KEY CLUSTERED ([LetterOfCreditId]),
    CONSTRAINT [UQ_LetterOfCredit_Tenant] UNIQUE ([TenantId], [LetterOfCreditId]),
    CONSTRAINT [UQ_LetterOfCredit_Scope_CompanyId] UNIQUE ([TenantId], [CompanyId], [LetterOfCreditId]),
    CONSTRAINT [UQ_LetterOfCredit_Scope_CurrencyId] UNIQUE ([TenantId], [CurrencyId], [LetterOfCreditId]),
    CONSTRAINT [UQ_LetterOfCredit_PublicId] UNIQUE ([PublicId]),
    CONSTRAINT [UQ_LetterOfCredit_CurrentTermsId] UNIQUE ([TenantId], [CurrentTermsId]),
    CONSTRAINT [CK_LetterOfCredit_1] CHECK (Amount > 0 AND OriginalAmount > 0),
    CONSTRAINT [CK_LetterOfCredit_2] CHECK (TolerancePlusPct BETWEEN 0 AND 100 AND ToleranceMinusPct BETWEEN 0 AND 100),
    CONSTRAINT [CK_LetterOfCredit_3] CHECK (DrawnAmount >= 0 AND SettledAmount >= 0 AND SettledAmount <= DrawnAmount),
    CONSTRAINT [CK_LetterOfCredit_4] CHECK (EarmarkedRemaining >= 0),
    CONSTRAINT [CK_LetterOfCredit_5] CHECK (ExposureAmount IS NULL OR ExposureAmount >= Amount),
    CONSTRAINT [CK_LetterOfCredit_6] CHECK ((LcClass = 'PURCHASE' AND IssueDate IS NOT NULL AND ReceivedDate IS NULL) OR (LcClass = 'SALES' AND ReceivedDate IS NOT NULL AND IssueDate IS NULL)),
    CONSTRAINT [CK_LetterOfCredit_7] CHECK (IssueDate IS NULL OR ExpiryDate >= IssueDate),
    CONSTRAINT [CK_LetterOfCredit_8] CHECK (LimitId IS NULL OR FacilityId IS NOT NULL),
    CONSTRAINT [CK_LetterOfCredit_9] CHECK (LimitProductLineId IS NULL OR LimitId IS NOT NULL),
    CONSTRAINT [CK_LetterOfCredit_10] CHECK (UtilizationId IS NULL OR FacilityId IS NOT NULL),
    CONSTRAINT [CK_LetterOfCredit_11] CHECK (RelationshipId IS NULL OR InstitutionId IS NOT NULL),
    CONSTRAINT [CK_LetterOfCredit_12] CHECK (LcClass = 'PURCHASE' OR (FacilityId IS NULL AND UtilizationId IS NULL AND ExposureAmount IS NULL AND MarginPct IS NULL AND MarginAmount IS NULL)),
    CONSTRAINT [CK_LetterOfCredit_13] CHECK (LcClass = 'SALES' OR ExposureAmount IS NOT NULL),
    CONSTRAINT [CK_LetterOfCredit_14] CHECK (LcClass = 'SALES' OR (ProformaId IS NULL AND OtherBankText IS NULL AND OtherBankBic IS NULL AND EarmarkedRemaining = 0)),
    CONSTRAINT [CK_LetterOfCredit_15] CHECK (MarginPct IS NULL OR MarginPct BETWEEN 0 AND 100),
    CONSTRAINT [CK_LetterOfCredit_16] CHECK (MarginAmount IS NULL OR MarginAmount >= 0),
    CONSTRAINT [CK_LetterOfCredit_17] CHECK (Status NOT IN ('CLOSED','CANCELLED') OR (ClosedOn IS NOT NULL AND ClosedReason IS NOT NULL)),
    CONSTRAINT [CK_LetterOfCredit_18] CHECK (Status IN ('CLOSED','CANCELLED') OR (ClosedOn IS NULL AND ClosedReason IS NULL)),
    CONSTRAINT [CK_LetterOfCredit_19] CHECK (UndrawnReleasedOn IS NULL OR Status IN ('EXPIRED','CLOSED','CANCELLED')),
    CONSTRAINT [CK_LetterOfCredit_20] CHECK (LegacyEntry = 0 OR RequestId IS NULL),
    CONSTRAINT [CK_LetterOfCredit_21] CHECK (OtherBankBic IS NULL OR ((OtherBankBic LIKE '________' OR OtherBankBic LIKE '___________') AND OtherBankBic NOT LIKE '%[^A-Z0-9]%')),
    CONSTRAINT [CK_LetterOfCredit_22] CHECK (AmendmentNo >= 0),
    CONSTRAINT [CK_LetterOfCredit_23] CHECK (LcNumberNormalized NOT LIKE '% %'),
    CONSTRAINT [CK_LetterOfCredit_LcClass] CHECK ([LcClass] IS NULL OR [LcClass] IN ('PURCHASE', 'SALES')),
    CONSTRAINT [CK_LetterOfCredit_Scope] CHECK ([Scope] IS NULL OR [Scope] IN ('DOMESTIC', 'INTERNATIONAL')),
    CONSTRAINT [CK_LetterOfCredit_Status] CHECK ([Status] IS NULL OR [Status] IN ('ACTIVE', 'EXPIRED', 'CLOSED', 'CANCELLED')),
    CONSTRAINT [CK_LetterOfCredit_Channel] CHECK ([Channel] IS NULL OR [Channel] IN ('BANK_PORTAL', 'MANUAL_FORM', 'DIRECT_INTEGRATION'))
);
GO
-- مرجع خارجي للاعتماد (ERP...)؛ بلا فرادة؛ البحث بالمطبَّع (FR-LCI-013، BR-REQ-006) -- جديد
CREATE TABLE [lc].[LcExternalRef] (
    [TenantId] INT NOT NULL,
    [LcExternalRefId] BIGINT IDENTITY(1,1) NOT NULL,
    [LcId] BIGINT NOT NULL,
    [SystemCode] NVARCHAR(40) NOT NULL,
    [RefType] NVARCHAR(60) NOT NULL,
    [RefValue] NVARCHAR(100) NOT NULL,
    [NormalizedValue] NVARCHAR(100) NOT NULL,
    [IsActive] BIT NOT NULL CONSTRAINT [DF_LcExternalRef_IsActive] DEFAULT 1,
    [SupersededById] BIGINT NULL,
    [CreatedAt] DATETIME2(3) NOT NULL CONSTRAINT [DF_LcExternalRef_CreatedAt] DEFAULT SYSUTCDATETIME(),
    [CreatedBy] BIGINT NULL,
    [UpdatedAt] DATETIME2(3) NULL,
    [UpdatedBy] BIGINT NULL,
    [RowVersion] ROWVERSION NOT NULL,
    CONSTRAINT [PK_LcExternalRef] PRIMARY KEY CLUSTERED ([LcExternalRefId]),
    CONSTRAINT [UQ_LcExternalRef_Tenant] UNIQUE ([TenantId], [LcExternalRefId]),
    CONSTRAINT [UQ_LcExternalRef_Scope_LcId] UNIQUE ([TenantId], [LcId], [LcExternalRefId]),
    CONSTRAINT [CK_LcExternalRef_1] CHECK (SupersededById IS NULL OR (IsActive = 0 AND SupersededById <> LcExternalRefId))
);
GO
-- تعديل اعتماد صادر أو مستلَم (FR-LCI-018/019، FR-LCE-020، BR-LCI-011/012، BR-LCE-014)؛ الحالات §8
CREATE TABLE [lc].[LcAmendment] (
    [TenantId] INT NOT NULL,
    [LcAmendmentId] BIGINT IDENTITY(1,1) NOT NULL,
    [CompanyId] BIGINT NOT NULL,
    [LcId] BIGINT NOT NULL,
    [AmendmentNo] INT NULL,
    [Origin] VARCHAR(22) NOT NULL,
    [ChangeKinds] VARCHAR(87) NOT NULL,
    [RequestId] BIGINT NULL,
    [TermsId] BIGINT NOT NULL,
    [ChangedFieldsJson] NVARCHAR(MAX) NULL,
    [CurrencyId] INT NOT NULL,
    [AmountDelta] DECIMAL(19,4) NOT NULL,
    [NewAmount] DECIMAL(19,4) NULL,
    [NewExpiryDate] DATE NULL,
    [Status] VARCHAR(11) NOT NULL CONSTRAINT [DF_LcAmendment_Status] DEFAULT 'DRAFT',
    [BankAmendmentRef] NVARCHAR(60) NULL,
    [BankIssuedOn] DATE NULL,
    [BeneficiaryResponse] VARCHAR(10) NULL CONSTRAINT [DF_LcAmendment_BeneficiaryResponse] DEFAULT 'PENDING',
    [RespondedOn] DATE NULL,
    [AppliedOn] DATETIME2(3) NULL,
    [AppliedBy] BIGINT NULL,
    [ReservationDeltaApplied] DECIMAL(19,4) NULL,
    [Reason] NVARCHAR(1000) NULL,
    [CreatedAt] DATETIME2(3) NOT NULL CONSTRAINT [DF_LcAmendment_CreatedAt] DEFAULT SYSUTCDATETIME(),
    [CreatedBy] BIGINT NULL,
    [UpdatedAt] DATETIME2(3) NULL,
    [UpdatedBy] BIGINT NULL,
    [RowVersion] ROWVERSION NOT NULL,
    CONSTRAINT [PK_LcAmendment] PRIMARY KEY CLUSTERED ([LcAmendmentId]),
    CONSTRAINT [UQ_LcAmendment_Tenant] UNIQUE ([TenantId], [LcAmendmentId]),
    CONSTRAINT [UQ_LcAmendment_TermsId] UNIQUE ([TenantId], [TermsId]),
    CONSTRAINT [CK_LcAmendment_1] CHECK (AmendmentNo IS NULL OR AmendmentNo >= 1),
    CONSTRAINT [CK_LcAmendment_2] CHECK (ChangeKinds <> ''),
    CONSTRAINT [CK_LcAmendment_3] CHECK (ChangeKinds NOT LIKE '%INCREASE_AMOUNT%' OR ChangeKinds NOT LIKE '%DECREASE_AMOUNT%'),
    CONSTRAINT [CK_LcAmendment_4] CHECK (Status = 'DRAFT' OR ChangeKinds NOT LIKE '%INCREASE_AMOUNT%' OR AmountDelta > 0),
    CONSTRAINT [CK_LcAmendment_5] CHECK (Status = 'DRAFT' OR ChangeKinds NOT LIKE '%DECREASE_AMOUNT%' OR AmountDelta < 0),
    CONSTRAINT [CK_LcAmendment_6] CHECK (Status = 'DRAFT' OR (ChangeKinds NOT LIKE '%INCREASE_AMOUNT%' AND ChangeKinds NOT LIKE '%DECREASE_AMOUNT%') OR NewAmount IS NOT NULL),
    CONSTRAINT [CK_LcAmendment_7] CHECK (Status = 'DRAFT' OR ChangeKinds NOT LIKE '%EXTEND_EXPIRY%' OR NewExpiryDate IS NOT NULL),
    CONSTRAINT [CK_LcAmendment_8] CHECK (NewAmount IS NULL OR NewAmount > 0),
    CONSTRAINT [CK_LcAmendment_9] CHECK (Status NOT IN ('BANK_ISSUED','APPLIED') OR (AmendmentNo IS NOT NULL AND BankIssuedOn IS NOT NULL)),
    CONSTRAINT [CK_LcAmendment_10] CHECK (Status <> 'APPLIED' OR (BeneficiaryResponse = 'ACCEPTED' AND AppliedOn IS NOT NULL AND AppliedBy IS NOT NULL)),
    CONSTRAINT [CK_LcAmendment_11] CHECK (BeneficiaryResponse IS NULL OR BeneficiaryResponse = 'PENDING' OR RespondedOn IS NOT NULL),
    CONSTRAINT [CK_LcAmendment_Origin] CHECK ([Origin] IS NULL OR [Origin] IN ('OUR_REQUEST', 'RECEIVED_FROM_CUSTOMER')),
    CONSTRAINT [CK_LcAmendment_Status] CHECK ([Status] IS NULL OR [Status] IN ('DRAFT', 'REQUESTED', 'BANK_ISSUED', 'APPLIED', 'REJECTED', 'WITHDRAWN')),
    CONSTRAINT [CK_LcAmendment_BeneficiaryResponse] CHECK ([BeneficiaryResponse] IS NULL OR [BeneficiaryResponse] IN ('PENDING', 'ACCEPTED', 'REJECTED')),
    CONSTRAINT [CK_LcAmendment_ChangedFieldsJson_json] CHECK ([ChangedFieldsJson] IS NULL OR ISJSON([ChangedFieldsJson]) = 1)
);
GO
-- سحب/تقديم مستندات تحت اعتماد؛ في التصدير يشمل تحويل التخصيص (FR-LCI-023، BR-LCI-013، BR-LCE-011)؛ الحالات §8
CREATE TABLE [lc].[LcDrawing] (
    [TenantId] INT NOT NULL,
    [LcDrawingId] BIGINT IDENTITY(1,1) NOT NULL,
    [CompanyId] BIGINT NOT NULL,
    [LcId] BIGINT NOT NULL,
    [DrawingNo] INT NOT NULL,
    [Amount] DECIMAL(19,4) NOT NULL,
    [CurrencyId] INT NOT NULL,
    [PresentationDate] DATE NOT NULL,
    [BankAdviceRef] NVARCHAR(60) NULL,
    [InvoiceRefsText] NVARCHAR(1000) NULL,
    [Status] VARCHAR(10) NOT NULL CONSTRAINT [DF_LcDrawing_Status] DEFAULT 'PRESENTED',
    [MaturityBasisDate] DATE NULL,
    [MaturityDate] DATE NULL,
    [ExaminationDeadline] DATE NULL,
    [SettledAmount] DECIMAL(19,4) NOT NULL CONSTRAINT [DF_LcDrawing_SettledAmount] DEFAULT 0,
    [LastSettledOn] DATE NULL,
    [SettlementAccountId] BIGINT NULL,
    [RequestId] BIGINT NULL,
    [OverrideReason] NVARCHAR(500) NULL,
    [Notes] NVARCHAR(1000) NULL,
    [CreatedAt] DATETIME2(3) NOT NULL CONSTRAINT [DF_LcDrawing_CreatedAt] DEFAULT SYSUTCDATETIME(),
    [CreatedBy] BIGINT NULL,
    [UpdatedAt] DATETIME2(3) NULL,
    [UpdatedBy] BIGINT NULL,
    [RowVersion] ROWVERSION NOT NULL,
    CONSTRAINT [PK_LcDrawing] PRIMARY KEY CLUSTERED ([LcDrawingId]),
    CONSTRAINT [UQ_LcDrawing_Tenant] UNIQUE ([TenantId], [LcDrawingId]),
    CONSTRAINT [UQ_LcDrawing_Scope_LcId] UNIQUE ([TenantId], [LcId], [LcDrawingId]),
    CONSTRAINT [UQ_LcDrawing_Scope_LcId_CurrencyId] UNIQUE ([TenantId], [LcId], [CurrencyId], [LcDrawingId]),
    CONSTRAINT [UQ_LcDrawing_LcId_DrawingNo] UNIQUE ([TenantId], [LcId], [DrawingNo]),
    CONSTRAINT [CK_LcDrawing_1] CHECK (Amount > 0),
    CONSTRAINT [CK_LcDrawing_2] CHECK (SettledAmount >= 0 AND SettledAmount <= Amount),
    CONSTRAINT [CK_LcDrawing_3] CHECK (Status <> 'SETTLED' OR SettledAmount = Amount),
    CONSTRAINT [CK_LcDrawing_4] CHECK (Status NOT IN ('REFUSED','CANCELLED') OR SettledAmount = 0),
    CONSTRAINT [CK_LcDrawing_5] CHECK (SettledAmount = 0 OR LastSettledOn IS NOT NULL),
    CONSTRAINT [CK_LcDrawing_6] CHECK (MaturityDate IS NULL OR MaturityBasisDate IS NULL OR MaturityDate >= MaturityBasisDate),
    CONSTRAINT [CK_LcDrawing_7] CHECK (ExaminationDeadline IS NULL OR ExaminationDeadline >= PresentationDate),
    CONSTRAINT [CK_LcDrawing_Status] CHECK ([Status] IS NULL OR [Status] IN ('PRESENTED', 'DISCREPANT', 'ACCEPTED', 'SETTLED', 'REFUSED', 'CANCELLED'))
);
GO
-- تخصيص أمر بيع على اعتماد مستلَم؛ لا يقابله حد ائتماني (FR-LCE-013..015، BR-LCE-009..013)؛ الحالات §8
CREATE TABLE [lc].[LcSalesOrder] (
    [TenantId] INT NOT NULL,
    [LcSalesOrderId] BIGINT IDENTITY(1,1) NOT NULL,
    [CompanyId] BIGINT NOT NULL,
    [LcId] BIGINT NOT NULL,
    [RequestId] BIGINT NOT NULL,
    [OrderRef] NVARCHAR(60) NOT NULL,
    [OrderDate] DATE NOT NULL,
    [Amount] DECIMAL(19,4) NOT NULL,
    [CurrencyId] INT NOT NULL,
    [ConvertedAmount] DECIMAL(19,4) NOT NULL CONSTRAINT [DF_LcSalesOrder_ConvertedAmount] DEFAULT 0,
    [ReleasedAmount] DECIMAL(19,4) NOT NULL CONSTRAINT [DF_LcSalesOrder_ReleasedAmount] DEFAULT 0,
    [Status] VARCHAR(19) NOT NULL CONSTRAINT [DF_LcSalesOrder_Status] DEFAULT 'EARMARKED',
    [DeliveryDate] DATE NULL,
    [ClosedOn] DATE NULL,
    [ClosedReason] NVARCHAR(500) NULL,
    [CreatedAt] DATETIME2(3) NOT NULL CONSTRAINT [DF_LcSalesOrder_CreatedAt] DEFAULT SYSUTCDATETIME(),
    [CreatedBy] BIGINT NULL,
    [UpdatedAt] DATETIME2(3) NULL,
    [UpdatedBy] BIGINT NULL,
    [RowVersion] ROWVERSION NOT NULL,
    CONSTRAINT [PK_LcSalesOrder] PRIMARY KEY CLUSTERED ([LcSalesOrderId]),
    CONSTRAINT [UQ_LcSalesOrder_Tenant] UNIQUE ([TenantId], [LcSalesOrderId]),
    CONSTRAINT [UQ_LcSalesOrder_Scope_LcId_CurrencyId] UNIQUE ([TenantId], [LcId], [CurrencyId], [LcSalesOrderId]),
    CONSTRAINT [UQ_LcSalesOrder_RequestId] UNIQUE ([TenantId], [RequestId]),
    CONSTRAINT [CK_LcSalesOrder_1] CHECK (Amount > 0),
    CONSTRAINT [CK_LcSalesOrder_2] CHECK (ConvertedAmount >= 0 AND ReleasedAmount >= 0 AND Amount >= ConvertedAmount + ReleasedAmount),
    CONSTRAINT [CK_LcSalesOrder_3] CHECK (Status <> 'EARMARKED' OR (ConvertedAmount = 0 AND ReleasedAmount = 0)),
    CONSTRAINT [CK_LcSalesOrder_4] CHECK (Status <> 'PARTIALLY_CONVERTED' OR (ConvertedAmount > 0 AND ConvertedAmount < Amount)),
    CONSTRAINT [CK_LcSalesOrder_5] CHECK (Status <> 'CONVERTED' OR ConvertedAmount = Amount),
    CONSTRAINT [CK_LcSalesOrder_6] CHECK (Status <> 'RELEASED' OR ReleasedAmount > 0),
    CONSTRAINT [CK_LcSalesOrder_7] CHECK (Status <> 'CANCELLED' OR (ConvertedAmount = 0 AND ReleasedAmount = 0)),
    CONSTRAINT [CK_LcSalesOrder_8] CHECK (Status NOT IN ('RELEASED','CANCELLED') OR (ClosedOn IS NOT NULL AND ClosedReason IS NOT NULL)),
    CONSTRAINT [CK_LcSalesOrder_Status] CHECK ([Status] IS NULL OR [Status] IN ('EARMARKED', 'PARTIALLY_CONVERTED', 'CONVERTED', 'RELEASED', 'CANCELLED'))
);
GO
-- توزيع سحب تصدير على أوامر بيع (FR-LCE-016/017، BR-LCE-011/013) -- جديد؛ Σ التوزيع ≤ مبلغ السحب وكل جزء ≤ متبقي أمره يتحقق منهما التطبيق
CREATE TABLE [lc].[LcDrawingAllocation] (
    [TenantId] INT NOT NULL,
    [LcDrawingAllocationId] BIGINT IDENTITY(1,1) NOT NULL,
    [LcId] BIGINT NOT NULL,
    [DrawingId] BIGINT NOT NULL,
    [SalesOrderId] BIGINT NOT NULL,
    [Amount] DECIMAL(19,4) NOT NULL,
    [CurrencyId] INT NOT NULL,
    [CreatedAt] DATETIME2(3) NOT NULL CONSTRAINT [DF_LcDrawingAllocation_CreatedAt] DEFAULT SYSUTCDATETIME(),
    [CreatedBy] BIGINT NULL,
    [UpdatedAt] DATETIME2(3) NULL,
    [UpdatedBy] BIGINT NULL,
    [RowVersion] ROWVERSION NOT NULL,
    CONSTRAINT [PK_LcDrawingAllocation] PRIMARY KEY CLUSTERED ([LcDrawingAllocationId]),
    CONSTRAINT [UQ_LcDrawingAllocation_Tenant] UNIQUE ([TenantId], [LcDrawingAllocationId]),
    CONSTRAINT [UQ_LcDrawingAllocation_DrawingId_SalesOrderId] UNIQUE ([TenantId], [DrawingId], [SalesOrderId]),
    CONSTRAINT [CK_LcDrawingAllocation_1] CHECK (Amount > 0)
);
GO
-- مخالفة على مستندات سحب أو اعتماد؛ القرار يتطلب lc.discrepancy.decide (FR-LCI-024، FR-LCE-021، §8) -- جديد
CREATE TABLE [lc].[LcDiscrepancy] (
    [TenantId] INT NOT NULL,
    [LcDiscrepancyId] BIGINT IDENTITY(1,1) NOT NULL,
    [LcId] BIGINT NOT NULL,
    [DrawingId] BIGINT NULL,
    [Source] VARCHAR(11) NOT NULL,
    [Description] NVARCHAR(MAX) NOT NULL,
    [Status] VARCHAR(10) NOT NULL CONSTRAINT [DF_LcDiscrepancy_Status] DEFAULT 'OPEN',
    [DecidedBy] BIGINT NULL,
    [DecidedOn] DATETIME2(3) NULL,
    [DecisionNote] NVARCHAR(1000) NULL,
    [CreatedAt] DATETIME2(3) NOT NULL CONSTRAINT [DF_LcDiscrepancy_CreatedAt] DEFAULT SYSUTCDATETIME(),
    [CreatedBy] BIGINT NULL,
    [UpdatedAt] DATETIME2(3) NULL,
    [UpdatedBy] BIGINT NULL,
    [RowVersion] ROWVERSION NOT NULL,
    CONSTRAINT [PK_LcDiscrepancy] PRIMARY KEY CLUSTERED ([LcDiscrepancyId]),
    CONSTRAINT [UQ_LcDiscrepancy_Tenant] UNIQUE ([TenantId], [LcDiscrepancyId]),
    CONSTRAINT [CK_LcDiscrepancy_1] CHECK (Status = 'OPEN' OR (DecidedBy IS NOT NULL AND DecidedOn IS NOT NULL AND DecisionNote IS NOT NULL)),
    CONSTRAINT [CK_LcDiscrepancy_2] CHECK (Status <> 'OPEN' OR (DecidedBy IS NULL AND DecidedOn IS NULL)),
    CONSTRAINT [CK_LcDiscrepancy_Source] CHECK ([Source] IS NULL OR [Source] IN ('BANK_NOTICE', 'INTERNAL')),
    CONSTRAINT [CK_LcDiscrepancy_Status] CHECK ([Status] IS NULL OR [Status] IN ('OPEN', 'WAIVED', 'CORRECTED', 'REFUSED'))
);
GO
-- البروفورما الصادرة: لا تعديل بعد الإصدار؛ الرقم {seq:000}-{erp}-{yy} (FR-LCE-005..008، BR-LCE-001..006)
CREATE TABLE [lc].[ProformaInvoice] (
    [TenantId] INT NOT NULL,
    [ProformaInvoiceId] BIGINT IDENTITY(1,1) NOT NULL,
    [CompanyId] BIGINT NOT NULL,
    [ProformaNo] NVARCHAR(30) NOT NULL,
    [NumberYear] SMALLINT NOT NULL,
    [NumberSeq] INT NOT NULL,
    [RequestId] BIGINT NOT NULL,
    [ErpCompanyCodeSnapshot] NVARCHAR(20) NOT NULL,
    [BranchCode] NVARCHAR(40) NULL,
    [BranchName] NVARCHAR(200) NULL,
    [ProjectCode] NVARCHAR(40) NULL,
    [ProjectName] NVARCHAR(200) NULL,
    [ProjectSite] NVARCHAR(200) NULL,
    [CustomerId] BIGINT NOT NULL,
    [CustomerSnapshotJson] NVARCHAR(MAX) NOT NULL,
    [IssueDate] DATE NOT NULL,
    [OfferValidityDays] INT NULL,
    [CurrencyId] INT NOT NULL,
    [Subtotal] DECIMAL(19,4) NOT NULL,
    [VatRatePct] DECIMAL(9,6) NOT NULL,
    [VatAmount] DECIMAL(19,4) NOT NULL,
    [Total] DECIMAL(19,4) NOT NULL,
    [LcPaymentPct] DECIMAL(9,6) NOT NULL CONSTRAINT [DF_ProformaInvoice_LcPaymentPct] DEFAULT 100,
    [PlacesJson] NVARCHAR(MAX) NULL,
    [TermsId] BIGINT NOT NULL,
    [ProceedsAccountId] BIGINT NOT NULL,
    [PrintLanguage] VARCHAR(10) NOT NULL CONSTRAINT [DF_ProformaInvoice_PrintLanguage] DEFAULT 'both',
    [DocumentId] BIGINT NOT NULL,
    [Status] VARCHAR(10) NOT NULL CONSTRAINT [DF_ProformaInvoice_Status] DEFAULT 'ISSUED',
    [VoidReason] NVARCHAR(500) NULL,
    [SupersededById] BIGINT NULL,
    [PublicId] UNIQUEIDENTIFIER NOT NULL CONSTRAINT [DF_ProformaInvoice_PublicId] DEFAULT NEWSEQUENTIALID(),
    [CreatedAt] DATETIME2(3) NOT NULL CONSTRAINT [DF_ProformaInvoice_CreatedAt] DEFAULT SYSUTCDATETIME(),
    [CreatedBy] BIGINT NULL,
    [UpdatedAt] DATETIME2(3) NULL,
    [UpdatedBy] BIGINT NULL,
    [RowVersion] ROWVERSION NOT NULL,
    CONSTRAINT [PK_ProformaInvoice] PRIMARY KEY CLUSTERED ([ProformaInvoiceId]),
    CONSTRAINT [UQ_ProformaInvoice_Tenant] UNIQUE ([TenantId], [ProformaInvoiceId]),
    CONSTRAINT [UQ_ProformaInvoice_Scope_CompanyId] UNIQUE ([TenantId], [CompanyId], [ProformaInvoiceId]),
    CONSTRAINT [UQ_ProformaInvoice_Scope_CurrencyId] UNIQUE ([TenantId], [CurrencyId], [ProformaInvoiceId]),
    CONSTRAINT [UQ_ProformaInvoice_PublicId] UNIQUE ([PublicId]),
    CONSTRAINT [UQ_ProformaInvoice_ProformaNo] UNIQUE ([TenantId], [ProformaNo]),
    CONSTRAINT [UQ_ProformaInvoice_CompanyId_NumberYear_NumberSeq] UNIQUE ([TenantId], [CompanyId], [NumberYear], [NumberSeq]),
    CONSTRAINT [UQ_ProformaInvoice_RequestId] UNIQUE ([TenantId], [RequestId]),
    CONSTRAINT [UQ_ProformaInvoice_TermsId] UNIQUE ([TenantId], [TermsId]),
    CONSTRAINT [UQ_ProformaInvoice_DocumentId] UNIQUE ([TenantId], [DocumentId]),
    CONSTRAINT [CK_ProformaInvoice_1] CHECK (ProformaNo LIKE '[0-9][0-9][0-9]%-%-[0-9][0-9]'),
    CONSTRAINT [CK_ProformaInvoice_2] CHECK (NumberSeq >= 1 AND NumberYear BETWEEN 2000 AND 2999),
    CONSTRAINT [CK_ProformaInvoice_3] CHECK (Subtotal >= 0 AND VatAmount >= 0),
    CONSTRAINT [CK_ProformaInvoice_4] CHECK (Total = Subtotal + VatAmount),
    CONSTRAINT [CK_ProformaInvoice_5] CHECK (VatRatePct BETWEEN 0 AND 100),
    CONSTRAINT [CK_ProformaInvoice_6] CHECK (LcPaymentPct > 0 AND LcPaymentPct <= 100),
    CONSTRAINT [CK_ProformaInvoice_7] CHECK (OfferValidityDays IS NULL OR OfferValidityDays > 0),
    CONSTRAINT [CK_ProformaInvoice_8] CHECK (Status <> 'VOID' OR VoidReason IS NOT NULL),
    CONSTRAINT [CK_ProformaInvoice_9] CHECK (VoidReason IS NULL OR Status = 'VOID'),
    CONSTRAINT [CK_ProformaInvoice_10] CHECK ((Status = 'SUPERSEDED' AND SupersededById IS NOT NULL) OR (Status <> 'SUPERSEDED' AND SupersededById IS NULL)),
    CONSTRAINT [CK_ProformaInvoice_11] CHECK (SupersededById IS NULL OR SupersededById <> ProformaInvoiceId),
    CONSTRAINT [CK_ProformaInvoice_PrintLanguage] CHECK ([PrintLanguage] IS NULL OR [PrintLanguage] IN ('ar', 'en', 'both')),
    CONSTRAINT [CK_ProformaInvoice_Status] CHECK ([Status] IS NULL OR [Status] IN ('ISSUED', 'VOID', 'SUPERSEDED')),
    CONSTRAINT [CK_ProformaInvoice_CustomerSnapshotJson_json] CHECK ([CustomerSnapshotJson] IS NULL OR ISJSON([CustomerSnapshotJson]) = 1),
    CONSTRAINT [CK_ProformaInvoice_PlacesJson_json] CHECK ([PlacesJson] IS NULL OR ISJSON([PlacesJson]) = 1)
);
GO
-- بند في البروفورما (FR-LCE-003، BR-LCE-001)؛ يُثبَّت بعد الإصدار
CREATE TABLE [lc].[ProformaLine] (
    [TenantId] INT NOT NULL,
    [ProformaLineId] BIGINT IDENTITY(1,1) NOT NULL,
    [ProformaId] BIGINT NOT NULL,
    [LineNo] INT NOT NULL,
    [Description] NVARCHAR(MAX) NOT NULL,
    [Qty] DECIMAL(19,4) NOT NULL,
    [UnitCode] VARCHAR(80) NOT NULL,
    [UnitPrice] DECIMAL(19,4) NOT NULL,
    [LineTotal] DECIMAL(19,4) NOT NULL,
    [CurrencyId] INT NOT NULL,
    [Notes] NVARCHAR(500) NULL,
    [CreatedAt] DATETIME2(3) NOT NULL CONSTRAINT [DF_ProformaLine_CreatedAt] DEFAULT SYSUTCDATETIME(),
    [CreatedBy] BIGINT NULL,
    [UpdatedAt] DATETIME2(3) NULL,
    [UpdatedBy] BIGINT NULL,
    [RowVersion] ROWVERSION NOT NULL,
    CONSTRAINT [PK_ProformaLine] PRIMARY KEY CLUSTERED ([ProformaLineId]),
    CONSTRAINT [UQ_ProformaLine_Tenant] UNIQUE ([TenantId], [ProformaLineId]),
    CONSTRAINT [UQ_ProformaLine_ProformaId_LineNo] UNIQUE ([TenantId], [ProformaId], [LineNo]),
    CONSTRAINT [CK_ProformaLine_1] CHECK (LineNo >= 1),
    CONSTRAINT [CK_ProformaLine_2] CHECK (Qty > 0),
    CONSTRAINT [CK_ProformaLine_3] CHECK (UnitPrice >= 0 AND LineTotal >= 0)
);
GO
-- نتيجة مقارنة شروط الاعتماد المستلَم بالبروفورما (FR-LCT-031، FR-LCE-023، BR-LCT-021) -- جديد (أولوية: ممكن)
CREATE TABLE [lc].[LcTermsComparison] (
    [TenantId] INT NOT NULL,
    [LcTermsComparisonId] BIGINT IDENTITY(1,1) NOT NULL,
    [BaselineTermsId] BIGINT NOT NULL,
    [ReceivedTermsId] BIGINT NOT NULL,
    [RunAt] DATETIME2(3) NOT NULL,
    [RunBy] BIGINT NULL,
    [SummaryJson] NVARCHAR(MAX) NULL,
    [Status] VARCHAR(10) NOT NULL CONSTRAINT [DF_LcTermsComparison_Status] DEFAULT 'OPEN',
    [CreatedAt] DATETIME2(3) NOT NULL CONSTRAINT [DF_LcTermsComparison_CreatedAt] DEFAULT SYSUTCDATETIME(),
    [CreatedBy] BIGINT NULL,
    [UpdatedAt] DATETIME2(3) NULL,
    [UpdatedBy] BIGINT NULL,
    [RowVersion] ROWVERSION NOT NULL,
    CONSTRAINT [PK_LcTermsComparison] PRIMARY KEY CLUSTERED ([LcTermsComparisonId]),
    CONSTRAINT [UQ_LcTermsComparison_Tenant] UNIQUE ([TenantId], [LcTermsComparisonId]),
    CONSTRAINT [UQ_LcTermsComparison_BaselineTermsId_ReceivedTermsId_RunAt] UNIQUE ([TenantId], [BaselineTermsId], [ReceivedTermsId], [RunAt]),
    CONSTRAINT [CK_LcTermsComparison_1] CHECK (BaselineTermsId <> ReceivedTermsId),
    CONSTRAINT [CK_LcTermsComparison_Status] CHECK ([Status] IS NULL OR [Status] IN ('OPEN', 'REVIEWED')),
    CONSTRAINT [CK_LcTermsComparison_SummaryJson_json] CHECK ([SummaryJson] IS NULL OR ISJSON([SummaryJson]) = 1)
);
GO
-- فرق حقل واحد وحكمه وقرار الخزينة (FR-LCT-031، BR-LCT-021) -- جديد (أولوية: ممكن)
CREATE TABLE [lc].[LcTermsComparisonLine] (
    [TenantId] INT NOT NULL,
    [LcTermsComparisonLineId] BIGINT IDENTITY(1,1) NOT NULL,
    [ComparisonId] BIGINT NOT NULL,
    [FieldKey] VARCHAR(60) NOT NULL,
    [BaselineValue] NVARCHAR(MAX) NULL,
    [ReceivedValue] NVARCHAR(MAX) NULL,
    [Verdict] VARCHAR(15) NOT NULL,
    [Decision] VARCHAR(17) NULL,
    [DecisionNote] NVARCHAR(1000) NULL,
    [CreatedAt] DATETIME2(3) NOT NULL CONSTRAINT [DF_LcTermsComparisonLine_CreatedAt] DEFAULT SYSUTCDATETIME(),
    [CreatedBy] BIGINT NULL,
    [UpdatedAt] DATETIME2(3) NULL,
    [UpdatedBy] BIGINT NULL,
    [RowVersion] ROWVERSION NOT NULL,
    CONSTRAINT [PK_LcTermsComparisonLine] PRIMARY KEY CLUSTERED ([LcTermsComparisonLineId]),
    CONSTRAINT [UQ_LcTermsComparisonLine_Tenant] UNIQUE ([TenantId], [LcTermsComparisonLineId]),
    CONSTRAINT [UQ_LcTermsComparisonLine_ComparisonId_FieldKey] UNIQUE ([TenantId], [ComparisonId], [FieldKey]),
    CONSTRAINT [CK_LcTermsComparisonLine_1] CHECK (Decision IS NULL OR Verdict <> 'MATCH'),
    CONSTRAINT [CK_LcTermsComparisonLine_Verdict] CHECK ([Verdict] IS NULL OR [Verdict] IN ('MATCH', 'MORE_FAVOURABLE', 'LESS_FAVOURABLE', 'ADDED', 'MISSING', 'REVIEW')),
    CONSTRAINT [CK_LcTermsComparisonLine_Decision] CHECK ([Decision] IS NULL OR [Decision] IN ('ACCEPT', 'REQUEST_AMENDMENT', 'IGNORE'))
);
GO
